window.__D("text/torat-shmuel/c041",{"p":[[2000470232,"<h3>[גן נעול] והנה כו' גן נעול</h3>\n<b>בס\"ד פ' שמיני</b>\n(יא) <b>והנה</b><sup data-n=\"1629\">317</sup> בת\"ז תיקון י\"ט דל\"ז<sup data-n=\"1630\">319</sup> פי' גן נעול ע\"ד מ\"ש שער החצר הפנימית הפונה קדים סגור יהי'<sup data-n=\"1631\">320</sup> כו', ושזה\"ע מ\"ם סתומה כי היא אות ב' וע\"י ו' נעשית מ\"ם סתומה כו' ע\"ש, והיינו כי בגן עדן נא' גן בעדן מקדם<sup data-n=\"1632\">321</sup>, א\"כ הו\"ע חצר הפנימית הפונה קדים, ולכן גן נעול ע\"ד יהי' סגור כו', והנה ענין בחי' הסגירה זהו כמו בחי' המסך שבין אצי' לבריאה<sup data-n=\"1633\">322</sup> ושרשו<sup data-n=\"1634\">323</sup> מהכתר<sup data-n=\"1635\">318</sup>, כי הנה כדי שיומשך אור האצי' בבריאה זהו ע\"י הפרסא המפסקת בין האצי' לבריאה, משא\"כ אם לא הי' הפרסא לא הי' אפשר כלל שיהי' התחברות האצי' בבריאה, וכמו בעולם התהו לא הי' כלל התחברות וגילוי אצי' בבריאה, וכדי שיהי' התחברות זו זהו ע\"י הפרסא וכענין ויבא משה בתוך הענן<sup data-n=\"1636\">325</sup>, שהענן הי' לבוש שע\"י לבוש זה הי' ביכולת משה לבוא בהר ולהיות ניזון מזיו השכינה, וכענין המשל שבו וע\"י אפשר להשיג השכל, והגם שהמשל מעלים עליו, שמי שאין דעתו וחכמתו יפה לא יבין כלל, הנה סיבת העלם השכל בלבוש המשל זהו סיבה שעכ\"פ מי שדעתו ושכלו יפה ישיג הנמשל ע\"י אמצעית המשל, משא\"כ בלא המשל א\"א שישיגו גם מי ששכלו ודעתו<sup data-n=\"1637\">326</sup> יפה, א\"כ ההעלם של המשל הוא סיבת הגילוי כו', ובאמת שרש פרסא נמשך ממקום גבוה<sup data-n=\"1638\">324</sup>, והוא מבחי' ת\"ת דאימא שנעשה כתר לז\"א<sup data-n=\"1639\">328</sup>, אשר בחי' כתר הוא יחידה<sup data-n=\"1640\">329</sup> שהוא בחי' מקיף, והמקיף דיחידה הוא מקיף הראש והרגל",[["1629","317","<b>והנה</b>: מכאן מתחיל מאמר הג' מהמשך מצה זו (הכולל פרקים יא-יג).\nלפי\"א — ראה אוה\"ת שה\"ש כאן ע' תלג פ\"ה (בשינויים). לקו\"ת שה\"ש מט, ד נא, א לו, ג (בשינויים — צויין אליו באוה\"ת שם).\nלפי\"ב — ראה אוה\"ת שה\"ש כאן ע' תלג פ\"ה (בשינויים). לקו\"ת שה\"ש יז, ג ואילך (בשינויים — צויין אליו באוה\"ת שם).\nלפי\"ג — ראה אוה\"ת שה\"ש כאן ע' תלג ואילך (בשינויים). לקו\"ת בהר לט, סע\"ג ואילך (בשינויים — צויין אליו באוה\"ת כאן ע' תלד). לקו\"ת במדבר ב, ג (בשינויים — צויין אליו באוה\"ת שה\"ש שם).\nהנחת<sup data-n=\"e97\">*</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן (בחלק הנחותיו) ושם הפתיחה: גן נעול אחותי כלה."],["1630","319","<b>בת\"ז. . דל\"ז</b>: דפוס אמשטרדם תקכ\"ח (לז, ד). לפנינו לח, א. ראה שם בשינוי."],["1631","320","<b>סגור יהי'</b>: ביחזקאל, אוה\"ת ות\"ז: יהי' סגור — וכ\"ה בסמוך בפנים. אבל באוה\"ת כאן בסוף העמוד (הובא לקמן פי\"ג) כבפנים. וכן (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן."],["1632","321","<b>גן בעדן מקדם</b>: בראשית ב, ח."],["1633","322","<b>המסך שבין אצי' לבריאה</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"ד. פי\"ג. מאמרי אדה\"א דברים ח\"ג ע' תתפא. וש\"נ."],["1634","323","<b>המסך. . ושרשו מהכתר</b>: ראה בסמוך בפנים."],["1635","318","<b>והנה בת\"ז. . ושרשו מהכתר</b>: אוה\"ת שה\"ש כאן ע' תלג רפ\"ה (בשינויים)."],["1636","325","<b>ויבא משה בתוך הענן</b>: משפטים כד, יח. ראה גם אגה\"ק סכ\"ט (קמט, א). תו\"א ח\"ש טז, א. סה\"מ תרל\"ח ע' רמח. וש\"נ."],["1637","326","<b>ששכלו ודעתו</b>: בהמשך הנדפס: שדעתו ושכלו."],["1638","324","<b>כי הנה. . ממקום גבוה</b>: ראה לקו\"ת שה\"ש מט, ד."],["1639","328","<b>ת\"ת דאימא שנעשה כתר לז\"א</b>: ראה ע\"ח שער מוחין דצלם שכ\"ג, רפ\"ה ורפ\"ז. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["1640","329","<b>כתר הוא יחידה</b>: ראה ע\"ח המובא בסמוך בפנים. מאו\"א מערכת יחיד סל\"ט. (בנוסף ללקו\"ת כאן) סה\"מ תרל\"ח ע' רמט ובהנסמן בריש המאמר שם."],["e97","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470233,"בהשוואה א' כמ\"ש בע\"ח שער העקודים פ\"ה בהג\"ה ממה\"ק, שלכן נק' יחידה כו', ולכן כמו שמקיף על חב\"ד דז\"א מלמעלה עד\"מ כך הוא מקיף ג\"כ מתחת רגליו מלמטה ולכן ממנו נמשך ג\"כ הפרגוד והמסך שבין אצי' לבריאה, וכמ\"ש בע\"ח שמ\"א שהמסך הוא החשמל שנמשך מבחי' בינה<sup data-n=\"1641\">330</sup> ומבואר בהרמ\"ז ס\"פ יתרו בדף ע\"ח שסוד החשמל הוא בת\"ת בין דאימא בין דז\"א, נמצא שהמסך הנ\"ל נמשך מת\"ת דאימא, אלא שמ\"מ מבואר שם בע\"ח פ\"א<sup data-n=\"1642\">331</sup> דהמסך הוא החיצוני' דת\"ת דאימא, ואמנם היחידה והמקיף דז\"א הוא עצמיות דת\"ת דאימא, ומ\"מ המקיף עצמו הוא הגורם להיות בחי' מסך הנ\"ל<sup data-n=\"1643\">327</sup>, ונמצא שהפרסא שרשה מהכתר.\n<b>ועוי\"ל</b> פי' יהי' סגור התענוג נעלם בתוך השכל והמדות בימי המעשה, וביום השבת יפתח<sup data-n=\"1644\">333</sup> ויתגלה ונהר יוצא מעדן כו', והפרסא ז\"ע עד<sup data-n=\"1645\">334</sup> הגל<sup data-n=\"1646\">332</sup> והוא בחי' המסך המפסיק בין הקדושה לסט\"א בחי' חשמ\"ל ושרשו מהמסך המפסיק בין אצי' לבריאה, שע\"י מסך זה לא יוכלו הקליפות להתקרב לקדושת האצי' שהוא אור התומ\"צ, וענין הגל הזה בעבודה הוא משארז\"ל רשעים נדמה להם כחוט השערה וצדיקים נדמה להם כהר<sup data-n=\"1647\">336</sup>, ועמך כולם צדיקים<sup data-n=\"1648\">337</sup> פי' שכל איסור קטן נדמה להם כהר ומסך מבדיל בינו לבין קונו, וזה בא ונמשך מבחי' יראת חטא, וענין יראת חטא הוא יראה הכלולה באהבה שמצד עוצם האהבה מתיירא מן החטא שלא ינתק חבל האהבה כו', ולכן נדמה לו כהר &lt;16&gt;\nּ ומסך מבדיל ונק' הר הגלעד<sup data-n=\"1649\">338</sup> שהיא מחיצה המפסקת כו', או הר הוא אהבה<sup data-n=\"1650\">339</sup> וחסד דקדושה שמזה נמשך יראת חטא להיות גל עד ומחיצה מפסקת בינו ליצה\"ר, וממילא כשישים אל לבו כל הנ\"ל שהוא בחי' הר ומחיצה מפסקת אפי' עבירה קלה שבקלים<sup data-n=\"1651\">340</sup> ממילא לא ישאר ח\"ו<sup data-n=\"e2\">*</sup>",[["1641","330","<b>בע\"ח שמ\"א שהמסך. . בינה</b>: בדפוס שקלאב תק\"ס. ולפנינו שער דרושי אבי\"ע שמ\"ב, פי\"ג. ראה גם תו\"א לך יב, ג. הגהות לד\"ה פתח אלי' תרנ\"ח פ\"ה ס\"ע סח ואילך."],["1642","331","<b>בע\"ח פ\"א</b>: ראה הערה שלפנ\"ז. בלקו\"ת כאן: בע\"ח פ\"א ואל תטעה לומר כי זהו האור המקיף כו' ע\"ש."],["1643","327","<b>והוא מבחי'. . הנ\"ל</b>: ראה לקו\"ת שה\"ש נא, א."],["1644","333","<b>וביום השבת יפתח</b>: המשך הכתוב שער החצר הפנימית (יחזקאל מו, א)."],["1645","334","<b>עד הגל</b>: ויצא לא, נב."],["1646","332","<b>ועוי\"ל. . ז\"ע עד הגל</b>: ראה אוה\"ת שה\"ש כאן ע' תלג."],["1647","336","<b>רשעים. . וצדיקים נדמה להם כהר</b>: סוכה נב, א (בהיפך הסדר — וכ\"ה בלקו\"ת כאן). ראה גם לקו\"ת אמור לב, א."],["1648","337","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["1649","338","<b>הר הגלעד</b>: לשון הכתוב ויצא לא, כא."],["1650","339","<b>הר הוא אהבה</b>: ראה גם לעיל המשך זאת חנוכת המזבח פי\"ב ובהערה 240."],["1651","340","<b>שבקלים</b>: בלקו\"ת ובהמשך הנדפס: שבקלות."],["e2","*","<b>נכתב בשולי היריעה</b>: ענין אינה נוטלת שם רעא י\"ל שפרעה נק' שם קראו שם, והוא ב\"ן ורפ\"חב וז\"ע שם רע, אבל ע\"י שהי' עם ישראל במצרי' אינה נוטלת שם רע כ\"א בירור רפ\"ח וכנודע שביררו במצרים ר\"ב ניצוצותג, וזהו ע\"י שהי' עמהם כו'.כ4 גג ט\nראה לקמן פי\"ג פיסקא נמצא. וש\"נ.\nנסמן להלן שם הערה 385.\nנסמן להלן שם הערה 388."]]],[2000470234,"בעניניו בלי כוונת הלב<sup data-n=\"1652\">341</sup> המשכת אלקות בזה הדבר, ושרש ענין גלעד הוא אבנים כשהבית נופל ונעשה חורבה נק' גל, כמ\"כ אבנים הם אותיות<sup data-n=\"1653\">342</sup> וכשהצירופי אותיות הם בדברים בטלים נעשה ג\"כ חורבה ולכן זהו הר ומסך מבדיל כו'<sup data-n=\"1654\">335</sup>.\n<b></b>קיצור. בת\"ז פי' גן נעול ע\"ד סגור יהי', וענין הסגירה זהו ע\"ד הפרסא שבין אצי' לבי\"ע, ושרשו מהכתר, ת\"ת דאימא, אלא שהוא מהחיצוני', או<sup data-n=\"1655\">343</sup> י\"ל סגור יהי' העלם התענוג בשכל, והפרסא זהו כענין הפרסא שבין הקדושה לסט\"א, ובעבודה ז\"ע לצדיקים נדמה להם כהר, הר הגלעד, דב\"ט.\n(יב) <b>ולפ\"ז</b><sup data-n=\"1656\">344</sup> ענין גן נעול זהו ע\"י שס\"ה ל\"ת<sup data-n=\"1657\">345</sup> לשמרה<sup data-n=\"1658\">346</sup> כו', כי ל\"ת נמשכים מהכתר י\"ה<sup data-n=\"1659\">347</sup> ומשם הפרסא כו', כי ענין ל\"ת להרחיק הרע שלא יקרב זר, א\"כ ז\"ע<sup data-n=\"1660\">348</sup> המסך לפי פי' השני, וכן נעל שלא יהיו הקוצים עוקצים לרגל, ולכן לפעמים איתא מ\"ע בז\"א ול\"ת במל'<sup data-n=\"1661\">349</sup> ולפעמים ל\"ת באו\"א<sup data-n=\"1662\">350</sup>, אלא כי ל\"ת במל' המסך חשמל ושרשו למעלה מז\"א והיינו מאו\"א, ובכס\"מ דקי\"ו<sup data-n=\"1663\">351</sup> וז\"ל ולהיות<sup data-n=\"1664\">352</sup> כי המחשבה הוא<sup data-n=\"1665\">353</sup> באבא<sup data-n=\"1666\">354</sup> לכן מצות ל\"ת שאין בהם קום ועשה<sup data-n=\"1667\">355</sup> זולתי סור מרע במחשבה בלבד הם תלוים בשם י\"ה באו\"א, האמנם זו\"נ שהם עולם המעשה מששת ימי בראשית הנק' ששת ימי המעשה<sup data-n=\"1668\">356</sup> לכן תלוי בהם מ\"ע, ואעפ\"כ כו' ונמנע ולא עשאה כו' עכ\"ל. ובמאו\"א אלף סעי' קע\"ג אבי\"ע הם הד' עולמות נק' מחשבה רצון קול דבור כי המחשבה מתפשטת באברים וא\"צ לדבור וכן האצי' איהו וגרמוהי חד<sup data-n=\"1669\">357</sup> עכ\"ל. וביאור הענין דכתי'<sup data-n=\"1670\">358</sup> כי לא מחשבותי מחשבותיכם<sup data-n=\"1671\">359</sup> ומבואר במ\"א<sup data-n=\"1672\">360</sup> שאינו מובן לפי פשוטו כי מילתא דפשיטא היא שאין ערוך",[["1652","341","<b>הלב</b>: כ\"ה גם בלקו\"ת. ובהמשך הנדפס ליתא."],["1653","342","<b>אבנים הם אותיות</b>: ראה ס\"י פ\"ד, מי\"ב. לעיל מאמר ד\"ה כמגדל דוד צוארך ובהערה 45."],["1654","335","<b>עד הגל. . כו'</b>: ראה לקו\"ת שה\"ש לו, ג."],["1655","343","<b>או</b>: בהמשך הנדפס: אלא. וכנראה צ\"ל כבפנים."],["1656","344","<b>ולפ\"ז. . עכ\"ל</b>: ראה אוה\"ת שה\"ש כאן ע' תלג פ\"ה."],["1657","345","<b>שס\"ה ל\"ת</b>: מכות כג, סע\"ב."],["1658","346","<b>לשמרה</b>: נסמן לקמן הערה 1783."],["1659","347","<b>ל\"ת. . י\"ה</b>: בהמשך הנדפס: ו\"ה. באוה\"ת שה\"ש כאן כבפנים. ראה גם לקמן רפ\"מ ובהערה 1239."],["1660","348","<b>ז\"ע</b>: באוה\"ת שה\"ש כאן: זהו עצמו."],["1661","349","<b>מ\"ע בז\"א ול\"ת במל'</b>: ראה זהר מקץ קצט, ב."],["1662","350","<b>ל\"ת באו\"א</b>: ראה הקדמה לטעמי המצות לקו\"ת (להאריז\"ל ס\"פ בראשית). תו\"א שמות נב, ג ואילך. לקו\"ת פקודי ג, ב ו, ב ואילך."],["1663","351","<b>ובכס\"מ דקי\"ו</b>: באוה\"ת שה\"ש כאן דקי\"ד — בדפוס אמשטרדם תקכ\"ט באות ר. בדפוס צילום ירושלים ת\"ז תס\"ט קמט, ב ”אות ק\"."],["1664","352","<b>ולהיות</b>: בכס\"מ ובאוה\"ת: להיות."],["1665","353","<b>הוא</b>: בכס\"מ: היא."],["1666","354","<b>באבא</b>: שם: באבא כנודע."],["1667","355","<b>ועשה</b>: בכס\"מ ובאוה\"ת: עשה."],["1668","356","<b>הנק' ששת ימי המעשה</b>: באוה\"ת: (הנק' ששת ימי המעשה). וזה הוספת הצ\"צ ובכס\"מ ליתא."],["1669","357","<b>איהו וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב."],["1670","358","<b>דכתי'. . זו כו'</b>: ראה לקו\"ת שה\"ש יז, ג ואילך (פ\"א)."],["1671","359","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח."],["1672","360","<b>ומבואר במ\"א</b>: ראה גם לקו\"ת ר\"ה נה, א. מאמרי אדה\"ז תקס\"ט ע' קפג ואילך. (נביאים ע' רלב)."]]],[2000470235,"מחשבתינו המלובשת בגוף לגבי מחשבתו של הקב\"ה שאין לו דמות הגוף<sup data-n=\"1673\">361</sup> ולא גוף ח\"ו, והענין הוא כי הנה באדם הרהור דהיינו מחשבה לא עביד מידי<sup data-n=\"1674\">362</sup>, כי הנה המחשבה נק' נהר<sup data-n=\"1675\">363</sup> והיינו דכמו<sup data-n=\"1676\">364</sup> הנהר שנובע מן מקורו והולך בתמידות לא ינוח ולא יעמוד, כך המחשבה היא נובעת בתמידות ממקורה מהשכל ולא תנוח אפי' רגע שתמיד תשוטט מחשבת האדם באיזהו דבר, ואעפ\"כ לא תפעול שום פעולה מורגשת ולא תעשה רושם כלל כמו הדבור והמעשה, כמו עד\"מ כאשר ידמה אדם במחשבתו להוות ולעשות איזה מציאות שיהי' הנה מחשבתו &lt;17&gt;\nּ לא תפעול, ואף אם ידמה ויצייר בשכלו צורת המציאות אשר ברצונו להוות עכ\"ז הי' כלא הי' עד יפעול ויצא לפועל ע\"י כח המעשה דוקא או ע\"י הדבור שמצוה לאחרים לעשות, ונמצא המחשבה אין לה כח לפעול ולעשות כמו הדבור והמעשה שעיקר הפעולה הוא ע\"י המעשה דוקא או הדבור עכ\"פ שמצוה לאחרים, וזהו דהרהור לא עביד מידי שהמחשבה היא בחי' אין לגבי הדבור והמעשה שהם היש, ואינו כן במחשבתו ית' שהמח' דוקא היא תפעול והיא<sup data-n=\"1677\">365</sup> היש כי כאשר עלה במחשבתו ורצונו להוות ולהאציל האצילות הנה אז נאצל ונתהוה ממש ע\"י מחשבה זו כו' וכמ\"ש כ\"ז בפרד\"ס שער הצחצחות פ\"ג<sup data-n=\"1678\">366</sup>, ואדרבה שם נהפוך הוא שהתהוות המציאות שע\"י מחשבה הוא הרבה גבוה במעלה ומדריגה מהמציאות שנתהווה ע\"י הדבור, וכידוע מענין צופה ומביט<sup data-n=\"1679\">367</sup> עד סוף כל הדורות במחשבה א', ששם הוא למעלה מבחי' גדר וזמן, וכמ\"ש בזהר שבמחשבה אחת נבראו כל העולמות<sup data-n=\"1680\">368</sup> אבי\"ע, וגם תחה\"מ ואלף השביעי, וכל העליות הכל נכלל במחשבה זו שממנה התהוותם, אך כשבא השפע בבחי' הדבור הוא שנתצמצם האור בבחי' מיעוט אחר מיעוט ובבחי' ההתחלקות עד ששם נעשה ונתהוה בחי' זמן להיות שנים וחדשים וימים כו' וכמ\"ש בסש\"ב ח\"ב פ\"ז שהתהוות הזמן הוא רק מבחי' מל' שהוא דבור העליון, אבל בחי' המדות עליונות שלמעלה מהדיבור כתי' כי אלף שנים בעיניך<sup data-n=\"1681\">369</sup> כיום אתמול, שכולל אלף שנים ביום א' עד שבמחשבה עילאה הוא למעלה מהזמן כנ\"ל שהרי צופה ומביט עד סוף כל הדורות במח' וסקירה אחת, נמצא מובן מזה שלמעלה עיקר בחי' ההתהוות הוא מבחי' המחשבה דוקא עד שגם כל מציאות כשעלה במח' ונתהוה שם עי\"ז, הנה יש בו חיות ואור יותר הרבה מכמו שהוא מהותו ומציאותו<sup data-n=\"1682\">370</sup> כשנמשך אח\"כ למטה ע\"י הדבור",[["1673","361","<b>שאין לו דמות הגוף</b>: ע\"פ פיוט יגדל. ראה גם לעיל מאמר ד\"ה נעשה אדם ובהערה 31."],["1674","362","<b>הרהור. . לא עביד מידי</b>: זהר אמור קה, א."],["1675","363","<b>מחשבה. . נהר</b>: ראה תו\"א נח ט, ב. לקו\"ת צו יז, סע\"א. שה\"א צ, א ובהערה 10."],["1676","364","<b>דכמו</b>: בהמשך הנדפס: דבחי'. בלקו\"ת כבפנים. וכנראה שבהמשך הנדפס ישנו כעין סימן על תיבה זו, ואולי לא יצא התיקון בהצילום וצ\"ל כבפנים?"],["1677","365","<b>והיא</b>: בהמשך הנדפס: והוא. בלקו\"ת כבפנים."],["1678","366","<b>בפרד\"ס שער הצחצחות פ\"ג</b>: הובא גם בלקו\"ת ר\"ה נה, א. סהמ\"צ להצ\"צ ע' נח. ע' קעח."],["1679","367","<b>צופה ומביט</b>: ראה ברכת זכרונות. ר\"ה יח, א. סהמ\"צ להצ\"צ ע' פב. תו\"ח שמות ח\"א מח, ב. וש\"נ."],["1680","368","<b>במחשבה אחת נבראו כל העולמות</b>: ראה זהר שמות כ, א. שם תוספות רעו, סע\"ב. סידור שער התפלה יח, סע\"ד. סהמ\"צ להצ\"צ ע' קעח ואילך. מאמרי אדה\"א קונטרסים ע' תלג. וש\"נ."],["1681","369","<b>כי אלף שנים בעיניך</b>: תהלים צ, ד."],["1682","370","<b>מהותו ומציאותו</b>: בהמשך הנדפס: מציאותו ומהותו. בלקו\"ת כבפנים."]]],[2000470236,"כו' להתהוות בבי\"ע, שהרי מה שנמשך ונתהוה ע\"י הדבור ירד ונמשך תחת הזמן ממש, משא\"כ מה שהוא בבחי' מחשבה הוא למעלה מזה כו', וזהו כי לא מחשבותי מחשבותיכם שבאדם גשמי נראה מחשבתו נחשבת לאין שלא יומשך ממנה שום התהוות מחמת דקותה, ומה שהולך ומתעבה לבחי' הדבור ומעשה נחשב יותר ליש שמהם יומשך התהוות דבר, אבל מדת הקב\"ה אינו כן שהוא ית' הסוכ\"ע הוא היש ואין בלתו, ומה שהולך ומתפשט יותר בבחי' עולמות עליונים ותחתוני' הוא נחשב יותר לאין כי הכל בטל נגדו וכולא קמי' כלא חשיב<sup data-n=\"1683\">371</sup> לכן כמ\"כ בענין מחשבה ודבור שלו ית' הם הארות והתפשטות אלקותו ית'<sup data-n=\"1684\">372</sup> הנה המח' הוא בחי' יש ועז\"נ להנחיל אוהבי יש<sup data-n=\"1685\">373</sup> וממנה עיקר ההתהוות עד שהדבור נחשב לבחי' אין וכלא חשיב לגבי מחשבה זו כו'.\n<b></b>קיצור. גן נעול מל\"ת, ותלוי' במח', וכתי' כי לא מחשבותי מחשבותיכם שבאדם לא יתהווה מהמח' מאומה, ולמעלה עיקר ההתהוות הוא מבחי' המח' כו'.\n(יג) <b>וע'</b><sup data-n=\"1686\">374</sup> בד\"ה למנצח על השמינית בענין מחשבה שלמעלה מהרצון<sup data-n=\"1687\">375</sup>, והנה מח' עילאה שולטת &lt;18&gt;\nּ על הכל, ולכן ע\"י קיום מצות ל\"ת שהמחשבה שולטת על המעשה שנמנע ואינו עושה ממשיך מח' עילאה הנ\"ל בחי' כי לא מחשבותי כו', וזהו שרש הפרסא המפסיק, וזהו גן נעול שמה שהוא נעול זהו ע\"י קיום מל\"ת<sup data-n=\"1688\">376</sup> ואבדיל אתכם<sup data-n=\"1689\">377</sup> כו', ע\"ד רקיע המבדיל בין מים למים כו' וע\"ד ויבדל בין האור ובין החשך<sup data-n=\"1690\">378</sup>, וזהו שער החצר כו' סגור יהי' ששת ימי המעשה פי' האור של הל\"ת בחי' י\"ה אינו מתגלה בימי המעשה שהם בחי' ו\"ה, וביום השבת יפתח כי אז עליות זו\"נ במקום או\"א, א\"כ אזי ו\"ה הם במדריגת י\"ה, וע\"ד מ\"ש בביאור והי' מספר פ\"ד<sup data-n=\"1691\">379</sup>, שז\"ע והי' מספר כו' אשר לא יספר<sup data-n=\"1692\">380</sup>, ושז\"ע ביום ההוא יהיה<sup data-n=\"1693\">381</sup> שבחי' ו\"ה תהי' במדרגת י\"ה, ובחי' זו מאיר בשבת כי אז מקבל העולם חיות מהמחשבה ולא מהדיבור, וע' בד\"ה למנצח על השמינית<sup data-n=\"1694\">382</sup>",[["1683","371","<b>וכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1684","372","<b>ית'</b>: בהמשך הנדפס ליתא."],["1685","373","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["1686","374","<b>וע'</b>: לפרק זה ראה אוה\"ת שה\"ש כאן ע' תלג ואילך (בשינויים). לקו\"ת בהר לט, סע\"א ואילך (בשינויים — צויין אליו באוה\"ת כאן ע' תלד). לקו\"ת במדבר ב, ג (בשינויים — צויין אליו באוה\"ת שה\"ש שם)."],["1687","375","<b>בד\"ה למנצח על השמינית בענין מחשבה שלמעלה מהרצון</b>: ראה לקו\"ת תזריע כ, ד (פ\"ב). כב, א (פ\"ג)."],["1688","376","<b>גן נעול. . קיום מל\"ת</b>: ראה סה\"מ מלוקט ד' ע' רלז ובהערה 6."],["1689","377","<b>ואבדיל אתכם</b>: קדושים כ, כו. תניא פמ\"ו (סו, א)."],["1690","378","<b>רקיע המבדיל. . למים. . ויבדל. . ובין החשך</b>: בראשית א, ו. שם א, ד [בדילוג]."],["1691","379","<b>בביאור והי' מספר פ\"ד</b>: לקו\"ת במדבר ז, ג ואילך."],["1692","380","<b>והי' מספר. . לא יספר</b>: הושע ב, א."],["1693","381","<b>ביום ההוא יהי'</b>: זכרי' יד, ט ובלקו\"ת מהאריז\"ל שם. ראה הנסמן במאמרי אדה\"א נ\"ך ע' קנב. סה\"מ תרכ\"ט ע' קכג. וש\"נ."],["1694","382","<b>בשבת. . מהמחשבה. . בד\"ה למנצח על השמינית</b>: ראה לקו\"ת תזריע כ, ד. כא, ג."]]],[2000470237,"ובד\"ה שובה ישראל<sup data-n=\"1695\">383</sup>, וע' בר\"ח שעה\"ק פ\"א קדושת המחשבה שהוא שרש לכל הקדושות והיא אחרית לכולם, ובפ\"ד פי' כי המח' ז\"ע נשמה והוא בריאה שבתוכה אצי', ובכללות העולמות אצי' ובריאה היינו חו\"ב י\"ה, וזה מתבאר מענין מל\"ת שגבוהים ממ\"ע והם תלוים במחשבה, כמ\"כ המח' שרש לכל הקדושות כו'.\n<b>נמצא</b> ענין גן נעול שלמעלה שנמשך ע\"י שלמטה כנס\"י הוא גן נעול שנפרד ונבדל ממנה להיות יניקת החיצונים וזהו ע\"י וגלחה את ראשה<sup data-n=\"1696\">384</sup> מותרי מוחין ועשתה את צפרני' מותרי המדות כו', ויש אתכפי' ואתהפכא כו', אך הכח הזה בנשמות שיהי' גן נעול זהו ע\"י גן סדרים דאורייתא וכמ\"ש במד\"ר הנ\"ל כל הימים שאני עמהם אינם נוטלים שם רע, במצרים כו' שנא' גן נעול, ופי' וענין שם רע כי הנה שם הוא ב\"ן רפ\"ח<sup data-n=\"1697\">385</sup> וגלות מצרים הי' בכדי לברר ש' ב\"ן היינו להעלות רפ\"ח ניצוצין<sup data-n=\"1698\">386</sup>, ופי' שאינם נוטלים שם רע שלא נשקעו בשה\"נ<sup data-n=\"1699\">387</sup>, כ\"א אדרבה בררו רפ\"ח ניצוצין וכנודע שבמצרים העלו ר\"ב ניצוצין<sup data-n=\"1700\">388</sup> וזהו וגם ערב ר\"ב עלה אתם<sup data-n=\"1701\">389</sup>, וכ\"ז ע\"י היותם גן נעול, וז\"ע מ\"ם סתומה שהוא ב' עם ו' שהוא\"ו שהוא תורה<sup data-n=\"1702\">390</sup> קול יעקב<sup data-n=\"1703\">391</sup> עושה הב' להיות נעול מאמר סתום<sup data-n=\"1704\">392</sup> וכמ\"ש בר\"ח שם ספ\"ד שקניית האדם טהרה וקדושה הוא ע\"י עסק התורה.\n<b>והנה</b> ע\"י שהוא בבחי' גן נעול עי\"ז הוא בחי' אחותי כלה, כי הנה ענין אחותי הוא לשון איחוי וחיבור מלשון איחוי אלכסנדרית שבגמ'<sup data-n=\"1705\">394</sup> שהוא מל' חיבור",[["1695","383","<b>בשבת. . מהמחשבה. . ובד\"ה שובה ישראל</b>: ראה לקו\"ת שבת שובה סו, ג. סה\"מ תרכ\"ז ע' רסה. לקמן ח\"ב (בחלק המאמרים) המשך יונתי ס\"כ שוה\"ג ב. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה הג' על יד הערה 65. (בחלק ההנחות) שם על יד הערה 68. וראה ג\"כ סה\"מ תקס\"ב ח\"א ע' רמו."],["1696","384","<b>וגלחה את ראשה</b>: תצא כא, יב. ראה לקו\"ת תצא לו, ג. לז, ב."],["1697","385","<b>שם הוא ב\"ן רפ\"ח</b>: פע\"ח שער הק\"ש ש\"ח, פ\"ט."],["1698","386","<b>רפ\"ח ניצוצין</b>: ראה ע\"ח שער רפ\"ח שי\"ח, פ\"ב. לקו\"ש וישב כרך טו ע' 524 (אג\"ק שלו ח\"ב ע' כא). וש\"נ. מאמרי אדה\"א דברים ח\"ד ע' א'קעד. וש\"נ."],["1699","387","<b>שלא נשקעו בשה\"נ</b>: ראה זהר חדש יתרו לא, א. מאמרי אדה\"א דברים ח\"ד ע' א'רסב. וש\"נ. שה\"א יג, ב ובהערה 23. תו\"ח לך צא, ד ובהערה 48. שמות ח\"א מא, ד ובהערה 210."],["1700","388","<b>שבמצרים העלו ר\"ב ניצוצין</b>: ראה כנפי יונה ח\"ג סנ\"ו. תו\"א בא ס, ג. תו\"ח בא ח\"א קטו, סע\"ב. וש\"נ. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 131."],["1701","389","<b>וגם ערב ר\"ב עלה אתם</b>: בא יב, לח."],["1702","390","<b>שהוא\"ו שהוא תורה</b>: ראה גם זהר רע\"מ תצא רעח, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע קס ואילך[ednref_98_א]. ש\"א נא, ב ובהערה 33."],["1703","391","<b>תורה קול יעקב</b>: תולדות כז, כב. ראה ב\"ר פס\"ה, כ. זהר בראשית נ, ב."],["1704","392","<b>מאמר סתום</b>: שבת קד, א. ראה מאמרי אדה\"ז תקס\"ט ע' קפד. מאמרי אדה\"א שמות ח\"א ע' ריג. וש\"נ. תו\"ח שמות ח\"א יב, ב ובהערה 543."],["1705","394","<b>איחוי אלכסנדרית שבגמ'</b>: מוע\"ק כו, ריש ע\"ב.\n\n[edn_98_א] <b>בתכריך כת\"י שפתיחתו היא ”שערי שעיעי שערי רכיכין\" (הדרוש הראשון שנרשם במפתח הכת\"י הוא ”הבא לטהר\"), ושם פח, ב נרשם בסוף ”דרושי תקס\"ג\" מאמר זה בקיצור, בכותרת</b>: ”מכתבי ב\"ה [ בן הרב] מהר\"מ\" [ מורינו הרב ר' משה]."]]],[2000470238,"שמחבר שני דברים להיות לאחדים כגוף אחד ממש, וכך הוא עד\"מ ענין האהבה הטבעית שבנפשות ממקור חוצבן שהם חלק אלק' ממש<sup data-n=\"1706\">395</sup> ומיוחדי' בתכלית היחוד באוא\"ס ממש, ע\"כ גם למטה אחר שנבראו מאין ליש וירדו מטה להתלבש בגוף ונפש החיונית זאת היא מדת הצדיקים מצד נפש האלקית אשר בקרבם חשקם ותשוקתם להתכלל באור ה' ולהבטל במציאות אליו ית' בכלות הנפש ממש מעומקא דלבא וכל ימיהם תמיד הם בביטול הנ\"ל מחמת טבע נפשותם שנעשה להם טבע ואין צריכים שום התבוננות והכנה לעורר את האהבה<sup data-n=\"1707\">393</sup>, וזהו ע\"ד תרין ריעין דלא מתפרשין, והוא עד\"מ כאהבת אח ואחות שהאהבה ביניהם קבוע ונטוע מעצמה בטבע בתולדותם בלי שום התעוררות כלל, וע' בת\"א בד\"ה רני ושמחי בת<sup data-n=\"1708\">396</sup> בענין עד שקראה אחותי כו', &lt;19&gt;\nּ ובחי' כלה כלתה נפשי אינו שייך רק כשהוא מרחוק ע\"ד צמאה לך נפשי<sup data-n=\"1709\">397</sup> כו' בארץ ציה כו', אמנם שתהי' אחותי וגם בחי' כלה, היינו ע\"ד לאתבא צדיקייא בתיובתא<sup data-n=\"1710\">398</sup>, כי גם אצי' נק' עשייה<sup data-n=\"1711\">399</sup> לגבי אוא\"ס ב\"ה וכתר עליון כו' אע\"ג כו' אוכם הוא<sup data-n=\"1712\">400</sup>.\n<b>וזהו</b> וגם אמנה אחותי<sup data-n=\"1713\">401</sup> בת אבי כו' ותהי לי לאשה כו', כי באמת כל<sup data-n=\"1714\">402</sup> העולמות עליונים מריש כל דרגין כו' הם בחי' מדבר ושממון ובחי' דומם ממש שאין בהם חיות כלל לגבי הקב\"ה כי אתה עשית את השמים ושמי השמים<sup data-n=\"1715\">403</sup> ואתה מחי' את כולם שהוא הוא ית' חיות כל העולמות ואין עוד מלבדו ואפס זולתו, והיו כלא היו, וכמ\"ש אשר שם שמות בארץ<sup data-n=\"1716\">405</sup> א\"ת שמות אלא ש מות<sup data-n=\"1717\">406</sup> שכל העולמות עליונים הם ג\"כ בחי' שמות מפני שהם מקבלים מבחי' שמות בלבד בחי' שם והארה, בי\"ה הוי' צור<sup data-n=\"1718\">407</sup> עולמים<sup data-n=\"1719\">404</sup>, ולזאת תכלה אליו נפש כל חי לדבקה בו ית' חיי החיים<sup data-n=\"1720\">408</sup> ב\"ה וכמ\"ש לאהבה את ה' כי הוא חייך<sup data-n=\"1721\">409</sup> פי' שאין חייך אלא הוא וכדכתי'",[["1706","395","<b>חלק אלק' ממש</b>: ראה איוב לא, ב. תניא רפ\"ב. סידור ר' יעקב קאפיל בהקדמת הכותב ע' ג. מאמרי אדה\"א ויקרא ח\"ב ע' שעג. וש\"נ. תו\"ח וארא ח\"א נא, ד. וש\"נ. סה\"ש תש\"נ ע' 381."],["1707","393","<b>מלשון. . האהבה</b>: ראה לקו\"ת בהר לט, סע\"ג ואילך (בשינויים — צויין אליו באוה\"ת שה\"ש כאן ע' תלד)."],["1708","396","<b>בת\"א בד\"ה רני ושמחי בת</b>: מקץ לו, ד."],["1709","397","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["1710","398","<b>לאתבא צדיקייא בתיובתא</b>: ראה זהר רע\"מ בהעלותך קנג, ב. מאמרי אדה\"א קונטרסים ע' רפא. וש\"נ. תו\"ח שמות ח\"א מא, ב. וש\"נ."],["1711","399","<b>אצי' נק' עשייה</b>: ראה גם תו\"א בראשית ג, א."],["1712","400","<b>וכתר עליון. . אוכם הוא</b>: ראה ת\"ז ת\"ע קלה, ב. מאמרי אדה\"א דברים ח\"ג ע' תתיא. וש\"נ. המשך והחרים תרל\"א ע' סט. סה\"מ תרל\"ד ע' רמז. המשך תער\"ב ח\"א ע' כא."],["1713","401","<b>וגם אמנה אחותי</b>: וירא כ, יב."],["1714","402","<b>כל. . כו'</b>: לקו\"ת במדבר ב, ג (בשינויים — צויין אליו באוה\"ת שה\"ש כאן ע' תלד)."],["1715","403","<b>אתה עשית. . השמים</b>: בלקו\"ת כאן ניתוסף כו' — נחמי' ט, ו."],["1716","405","<b>אשר שם שמות בארץ</b>: תהלים מו, ט."],["1717","406","<b>א\"ת שמות אלא שמות</b>: ברכות ז, ב. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשצב. וש\"נ. נ\"ך ע' תעב."],["1718","407","<b>בי\"ה הוי' צור עולמים</b>: ישעי' כו, ד."],["1719","404","<b>וכמ\"ש. . עולמים</b>: באוה\"ת שה\"ש כאן: ועמ\"ש. . ובענין א\"ת שמות אלא שמות — ראה לקו\"ת בהר מא, ד."],["1720","408","<b>חיי החיים</b>: יומא עא, א. ראה גם תניא פמ\"ד (סג, א)."],["1721","409","<b>לאהבה את ה' כי הוא חייך</b>: נצבים ל, כ [בדילוג]."]]],[2000470239,"ראו עתה כי אני אני הוא<sup data-n=\"1722\">410</sup> אלא שמקרא זה על העתיד נא' שאז יראו, משא\"כ עכשיו הוא בבחי' הצמאון כמ\"ש צמאה נפשי לאלקי' לאל<sup data-n=\"1723\">411</sup> חי מתי אבוא ואראה כו' ועי\"ז גם בחי' אחותי נעשית כלה, וכ\"ז הוא ע\"י שהוא בחי' גן נעול כו'.\n<b></b>קיצור. זה<sup data-n=\"1724\">412</sup> שהוא גן נעול, סור מרע וקדושת המח' הוא ע\"י גן סדרים דאורייתא כי מם סתומה הוא ב' וא\"ו אשר<sup data-n=\"1725\">413</sup> ו' שהוא תורה עושה הב' להיות מאמר סתום, ועי\"ז שהוא גן נעול נעשית אחותי כלה כו'.",[["1722","410","<b>ראו עתה. . אני הוא</b>: האזינו לב, לט."],["1723","411","<b>צמאה נפשי לאלקי'</b>: תהלים מב, ג."],["1724","412","<b>זה</b>: בהמשך הנדפס: מטושטש. באוה\"ת כאן כבפנים."],["1725","413","<b>אשר</b>: בהמשך הנדפס: ליתא. באוה\"ת כאן כבפנים."]]],[2000470240,"<h3>[גן נעול] והנה בתרגום פי' גן נעול</h3>\n<b>בס\"ד פ' תזומ\"צ</b>\n(יד) <b>והנה</b><sup data-n=\"1726\">414</sup> בתרגום פי' גן נעול<sup data-n=\"1727\">415</sup> כמו שגן עדן נעול כו' כך הם נשי ישראל אוגדות פתחיהן, ובעבודה בנפש האדם ז\"ע מה שאומרים בתפלת שבת ויו\"ט קדשנו במצותיך<sup data-n=\"1728\">416</sup> ותן חלקינו בתורתיך, פי' חלקינו יובן ע\"פ המד\"ר שבכל ימי הסוכות מקריבין ע' פרים, ואח\"כ בשמע\"צ<sup data-n=\"1729\">417</sup> פר אחד ואיל אחד<sup data-n=\"1730\">418</sup>, משל למלך שעשה סעודה ז' ימים וזימן כל בני אדם שבמדינה, אמר לאוהבו כבר יצאנו לפני כל<sup data-n=\"1731\">419</sup> בני המדינה נגלגל אני ואתה במה שנמצא<sup data-n=\"1732\">420</sup> ליטרא בשר כו', שז\"ע חלקינו",[["1726","414","<b>והנה</b>: מכאן מתחיל מאמר הד' מהמשך מצה זו (הכולל פרקים יד-טז).\nפי\"ד — ראה אוה\"ת שה\"ש כאן ע' תלב פ\"ד וע' תמג (בשינויים). לקו\"ת שמע\"צ צא, א (בהוספות ושינויים — צויין אליו באוה\"ת שם). ראה סה\"מ מלוקט ד' ע' רלז ואילך.\nפט\"ו — לשון אוה\"ת שה\"ש כאן ע' תלב ואילך פ\"ד בשינויים והוספות.\nפט\"ז — לשון אוה\"ת שה\"ש כאן ע' תלד ואילך ס\"ו בשינויים. ע' תלא ואילך ס\"ג בשינויים.\nהנחת<sup data-n=\"e99\">*</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן (בחלק הנחותיו) ושם הפתיחה: גן נעול אחותי כלה."],["1727","415","<b>בתרגום פי' גן נעול</b>: שה\"ש ד, יב."],["1728","416","<b>מה שאומרים. . קדשנו במצותיך</b>: בתפלת העמידה.\nלשון לקו\"ת שמע\"צא צא, א (בהוספות ושינויים — צויין אליו באוה\"ת שם). ראה גם לקו\"ת במדבר טז, ג. בלק סחא, ב. ועוד."],["1729","417","<b>המד\"ר. . הסוכות. . בשמע\"צ</b>: ראה במדב\"ר פכ\"א, כד. תנחומא פינחס טז."],["1730","418","<b>פר אחד איל אחד</b>: פינחס כט, לו."],["1731","419","<b>לפני כל</b>: במדרש: ידינו מכל."],["1732","420","<b>שנמצא</b>: וכ\"ה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן. המשך תער\"ב ח\"א ע' קנח וע' תכח. במדרש ובהמשך תער\"ב ח\"ב ע' א'קסח: שתמצא."],["e99","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470241,"בתורתיך שאז זמן קליטה שקולטת כנס\"י טיפת החכ' דהיינו התורה שירדה מרצונו וחכמתו ית' אלא שנתגשמה ונתלבשה בדברים גשמי', ובהיות כל איש ישראל לומד תורה וחוזר לימודו ותופס בזכרונו היטב נק' קולטת שקולט דבר החכ' שבחכ' התורה כו', אלא שמתחלה צ\"ל קדשנו במצותיך ואח\"כ ותן חלקנו בתורתיך, וכמו בגשמיות שמתחלה צ\"ל קדושין ואח\"כ נשואין, כך צ\"ל תחלה קדשנו במצותיך שזהו בחי' קדושין ואח\"כ ותן חלקנו המשכת טפת החכמה, וענין הקדושין ז\"ע הזמנה ועי\"ז אוסרה על כל העולם<sup data-n=\"1733\">421</sup>, ובעבודה ז\"ע ואבדיל אתכם כו' להיות לי, וכמו וארשתיך לי<sup data-n=\"1734\">422</sup> לשון אירוסין וכמו שאצלם הי' הנהוג שהיו מקדשין בשעת האירוסין, ואח\"כ הוא הנשואין בחי' קליטת התורה, וכן יובן זה בתפלה שהוא ע\"י הדעת והתקשרות במוחו ולבו שיתקע &lt;20&gt;\nּ בחוזק במחשבתו בבחי' הרגשה וכמארז\"ל הכר את בוראך<sup data-n=\"1735\">423</sup> שנתפס לתוך מוחו וגם לתוך לבו להיות לו רעותא דלבא מעומקא דלבא לה' לבדו כו', והנה עד\"מ כי יקח איש אשה<sup data-n=\"1736\">424</sup> שצריך לקדשה תחלה שנותן לה פרוטה או שוה פרוטה<sup data-n=\"1737\">425</sup> שהוא רק דבר שתוכל לקנות לה חיי נפשה, כך א\"א להיות הנשמות קולטות כ\"א כאשר ימשיך לה תחלה חיות אלקות מלמעלה וזהו וארשתיך לי, ואח\"כ וידעת את הוי'<sup data-n=\"1738\">426</sup>.\n<b>וענין</b> הקדושין הוא כמ\"ש והייתם קדושים<sup data-n=\"1739\">427</sup> כו' להיות לי, וזהו פי' הרי את מקודשת לי<sup data-n=\"1740\">428</sup> פי' שתהי' מובדל ומופרש לי לשמי, וז\"ע כל כוונת המצות כי מצות צריכות כוונה<sup data-n=\"1741\">429</sup> פי' לדעת המכוון, והמכוון הוא להיות מובדל מן התאוות ומכל מדות הרעות, ולכן תקנו חז\"ל לומר אשר קדשנו במצותיו בברכת המצות, ועי\"ז יוכל להיות לו בחי' קליטה הנ\"ל בתורה ותפלה, משא\"כ בלא בחי' קדושין הנ\"ל א\"א להיות בחי' קליטה, והנה ענין בחי' המשכת קדושין הנ\"ל הוא מלמעלה מבחי' סוכ\"ע, וז\"ע טבעת קדושין<sup data-n=\"1742\">430</sup> עגול<sup data-n=\"1743\">431</sup> סוכ\"ע ששם שוה הכל אצלו ית' הי' הוה ויהי' הכל ברגע א'<sup data-n=\"1744\">432</sup> ואין בו שום שינוי ח\"ו, וכמ\"ש גדול הוי' ומהולל מאד<sup data-n=\"1745\">433</sup> ולגדולתו אין חקר, פי' שגדולת הוי' הוא מאד בלי שיעור,",[["1733","421","<b>הקדושין. . אוסרה על כל העולם</b>: קדושין ב, ב ובתוד\"ה דאסר."],["1734","422","<b>וארשתיך לי</b>: הושע ב, (כא). כב. ראה שה\"א ט, א ובהערה 8. תו\"ח בא ח\"א קי, א הערה 541."],["1735","423","<b>הכר את בוראך</b>: ראה (בנוסף ללקו\"ת כאן) (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 11 בשם הספרי. ב\"ר פפ\"ה, יא. עין יעקב סוטה י, ב."],["1736","424","<b>כי יקח איש אשה</b>: תצא כד, א."],["1737","425","<b>פרוטה או שוה פרוטה</b>: משנה ריש קדושין."],["1738","426","<b>וידעת את הוי'</b>: סיום הכתוב וארשתיך לי. ראה לקו\"ת במדבר ט, א."],["1739","427","<b>והייתם קדושים</b>: קדושים כ, כו [בדילוג]."],["1740","428","<b>הרי את מקודשת לי</b>: נוסח הקדושין. קדושין ה, ב. שו\"ע אבהע\"ז רסכ\"ז."],["1741","429","<b>מצות צריכות כוונה</b>: ערובין צה, סע\"ב."],["1742","430","<b>טבעת קדושין</b>: ראה רמ\"א בשו\"ע אבהע\"ז רסכ\"ז. סל\"א, ס\"ב."],["1743","431","<b>טבעת קדושין עגול</b>: ראה סידור ברכת נשואין קלח, ד. תורה אור ויגש מו, ד. מאמרי אדה\"ז תקס\"ב ח\"ב ע' של. מאמרי אדה\"א בראשית ע' ריט וע' רכט. אוה\"ת תצא ע' תתרכז. ברכה ע' א'תתמה."],["1744","432","<b>הי'. . ברגע א'</b>: ראה שער היחוד והאמונה פ\"ז. תו\"ח מקץ ריט, ד הערה 62."],["1745","433","<b>גדול הוי' ומהולל מאד</b>: תהלים קמה, ג."]]],[2000470242,"וכמארז\"ל מן הארץ לרקיע<sup data-n=\"1746\">434</sup> מהלך ת\"ק שנה בין כל רקיע כו' רגלי החיות כו' אבל לגדולתו אין חקר פי' ולגדולתו בעצמו אין שייך ל' גדולה, רק שבמקום גדולתו אתה מוצא ענוותנותו<sup data-n=\"1747\">435</sup> שאצלו ית' בחי' הגדולה לענוה נחשבת כי<sup data-n=\"1748\">436</sup> לשון גדולה נופל על התפשטות אור בבחי' א\"ס ואין קץ כו' ולא על מקור האור וחיי החיים שהוא מתגדל<sup data-n=\"1749\">437</sup> על דבר שהוא כאין ואפס ממש, וזהו לך ה' הגדולה<sup data-n=\"1750\">438</sup> פי' כי מדת הגדולה היא רק בחי' הארה שנתהוה ממך וג\"ז ע\"י צמצום והתפשטות והמשכה שע\"ז מורים אותיות יו\"ד ה' וא\"ו דש' הוי', ותי' ה' ל' הויה כו' שנתהוה ממך מדת הגדולה, וע\"י התבוננות זו נמשך לאדם ג\"כ לב נשבר ונדכה שיהי' שוה בעיניו כל עניני העולם<sup data-n=\"1751\">439</sup> שנופלים תחת הזמן עבר ועתיד והוה ולא יתאוה להם ולא ישית אליהם לב כלל, כי יאמר ללבו הרי קודם זה כמה שנים לא עלתה על לבי כלל לחשוב ולהרהר בענין זה, ואחר כמה שנים לא יהי' הדבר ולא יבוא כלל, ולכן גם עתה יהי' דומה בעיניו כאלו היום קודם הזמן הזה ואחריו, וזהו איזהו חכם הרואה את הנולד<sup data-n=\"1752\">440</sup> שרואה בבחי' ראי' ממש מה שנולד אח\"כ שלא יהי' הדבר הרע כמ\"ש ואת רוח הטומאה אעביר מן הארץ<sup data-n=\"1753\">441</sup> כו'<sup data-n=\"1754\">442</sup>, ואחרית כל דבר הוא רימה ותולעה<sup data-n=\"1755\">443</sup> והוה ונפסד, וזהו אתה פוררת בעזך ים<sup data-n=\"1756\">444</sup>, פי' ים<sup data-n=\"1757\">445</sup> נק' כמה בחי' שהם מצולות ים וכמ\"ש ותשליך במצולות ים<sup data-n=\"1758\">446</sup> כל חטאתם, ואתה מפרר ומפזר<sup data-n=\"1759\">447</sup> אותם בעזך היינו ע\"י בחי' התבוננות הנ\"ל אין לו תפיסת מקום להחשב<sup data-n=\"1760\">448</sup> בבחי' יש רק יפרר ע\"י בחי' לב נשבר ונדכה<sup data-n=\"1761\">449</sup> כו'.",[["1746","434","<b>מן הארץ לרקיע</b>: ראה חגיגה יג, א."],["1747","435","<b>שבמקום גדולתו. . ענוותנותו</b>: ראה מגילה לא, א. סה\"מ תרנ\"א ע' עא. ה'ש\"ת ע' 40 בהערה. תו\"ח יתרו ח\"ב רנט, ב הערה 122."],["1748","436","<b>כי</b>: בהמשך הנדפס: כו'. בלקו\"ת כאן כבפנים."],["1749","437","<b>מתגדל</b>: וכ\"ה בלקו\"ת כאן. בהמשך הנדפס: מתגלה."],["1750","438","<b>לך ה' הגדולה</b>: דהי\"א כט, יא."],["1751","439","<b>העולם</b>: בהמשך הנדפס: העוה\"ז. בלקו\"ת כאן כבפנים."],["1752","440","<b>איזהו חכם הרואה את הנולד</b>: תמיד לב, א. ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 268."],["1753","441","<b>ואת רוח. . הארץ</b>: זכרי' יג, ב."],["1754","442","<b>כו'</b>: בלקו\"ת כאן צא, ב: וגו'."],["1755","443","<b>ואחרית. . רימה ותולעה</b>: ראה אבות רפ\"ג."],["1756","444","<b>אתה פוררת בעזך</b>: תהלים עד, יג."],["1757","445","<b>פי' ים נק'</b>: וכ\"ה בלקו\"ת כאן. בהמשך הנדפס: ונז'."],["1758","446","<b>ותשליך במצולות ים</b>: מיכה ז, יט."],["1759","447","<b>ומפזר</b>: בהמשך הנדפס: ומפריד. בלקו\"ת כאן כבפנים."],["1760","448","<b>להחשב</b>: בהמשך הנדפס: להתפס. בלקו\"ת כאן כלל להחשב."],["1761","449","<b>לב נשבר ונדכה</b>: תהלים נא, יט."]]],[2000470243,"<b></b>קיצור. גן נעול פי' בתרגום שכמו הג\"ע נעול כך אוגדות פתחיהן, ובעבודה זהו קדשנו &lt;21&gt;\nּ במצותיך ואבדיל אתכם, ועי\"ז ותן חלקנו בתורתיך, בחי' השפעת טיפת חכ' התורה בבחי' קליטה, והקדושין הוא מבחי' סוכ\"ע שלגדולתו אין חקר, והגדולה היא ענוה, ועי\"ז יהי' לב נשבר ונדכה שע\"י התבוננות עבר ועתיד שיראה את הנולד יהי' אצלו גם בהוה כן וזהו<sup data-n=\"1762\">450</sup> אתה פוררת בעזך ים כו'.\n(טו) <b>והנה</b><sup data-n=\"1763\">451</sup> ענין הגן הוא בחי' תענוג, וגן נעול שאין התענוג רק באלקות ועמך לא חפצתי<sup data-n=\"1764\">452</sup>, ובמד\"ר גן נעול אלו הבתולות<sup data-n=\"1765\">453</sup>, ובמאו\"א בי\"ת סמ\"ד בתולה נק' המל' כי מעיינה סתום בחותם הבינה, (וי\"ל בכנס\"י זהו שבהתבוננות הנ\"ל נמשך להיות מעיינה סתום שלא יקרב זר הוא בחי' תאוות העולם), בתולות רעותיה<sup data-n=\"1766\">454</sup> הם ההיכלות, וע' ברבות פקודי ר\"פ נ\"ב, וברבקה נא' והנערה טובת מראה מאד בתולה ואיש לא ידעה, פ' חיי ך\"ד ט\"ז, וענין טובת מראה מאד פי' בלק\"ת סד\"ה קול דודי<sup data-n=\"1767\">455</sup> מאד בלי גבול, והיינו כי יפת מראה בינה עילאה במאו\"א יו\"ד ססעי' י\"ב, ורבינו ז\"ל פי' שהיא רעו\"ד<sup data-n=\"1768\">456</sup>, כי בינה ליבא<sup data-n=\"1769\">457</sup> פנימיות הלב כמ\"ש בד\"ה<sup data-n=\"1770\">458</sup> ושאבתם מים בששון<sup data-n=\"1771\">459</sup> וא\"כ מאד היינו התגלות עתיק בבינה<sup data-n=\"1772\">460</sup>, והו\"ע אהבה בתענוגי' שלמעלה מבחי' אה\"ר ואה\"ע פנימיות הלב וחיצוני' הלב כמ\"ש בד\"ה חכלילי עינים מיין<sup data-n=\"1773\">461</sup> ע\"ש שאינו סותר למ\"ש בסש\"ב שאה\"ר היא אהבה בתענוגי'<sup data-n=\"1774\">462</sup> כו', וענין בתולה ואיש לא ידעה פי' בזהר חקת דק\"פ ע\"ב שלא קרב אלי' הקלי' והיינו איש זר בא נחש על חוה<sup data-n=\"1775\">463</sup>, משא\"כ בשרה כנז' בזהר ר\"פ חיי דקךב\"ב<sup data-n=\"1776\">464</sup>, וז\"ע ואיש לא ידעה, וע' בזהר ר\"פ תצא דרע\"ו א', וע' בבה\"ז<sup data-n=\"1777\">465</sup> ע\"פ הזהר חקת הנ\"ל בענין תיו ד' נו\"ן ענין כן דרך<sup data-n=\"1778\">466</sup> אשה מנאפת כו' שז\"ע בא נחש על חוה כו' והוא כשמקבלת מגבורות קשות יש יניקה לנחש כו', ובמאו\"א נ' י\"ד נאף בגימ' ס\"מ<sup data-n=\"1779\">467</sup> כי<sup data-n=\"1780\">468</sup> הוא נאף אשה חסר לב<sup data-n=\"1781\">*469</sup> דמפתי לי' לאתתא<sup data-n=\"1782\">469</sup> לנטלא נהורא והטיל זוהמא בחוה עכ\"ל, וע' בזהר ויקהל דר\"ג<sup data-n=\"1783\">470</sup>, וענין הגבורות בעבודה הוא ע\"ד כעס, טורף נפשו<sup data-n=\"1784\">471</sup> כו', וע'",[["1762","450","<b>וזהו</b>: בהמשך הנדפס: ליתא."],["1763","451","<b>והנה</b>: לשון אוה\"ת שה\"ש כאן ע' תלב ואילך פ\"ד בשינויים והוספות."],["1764","452","<b>ועמך לא חפצתי</b>: תהלים עג, כה."],["1765","453","<b>ובמד\"ר גן נעול אלו הבתולות</b>: ויק\"ר פל\"ב, ה. במדב\"ר פ\"ג, ו. שהש\"ר פ\"ד, יב (א). אוה\"ת כאן ע' תמג."],["1766","454","<b>בתולות רעותיה</b>: תהלים מה, טו [בדילוג]."],["1767","455","<b>בלק\"ת סד\"ה קול דודי</b>: שה\"ש טו, ג (הובא לקמן פכ\"ח). טז, ג. וראה גם (לקמן בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 99."],["1768","456","<b>יפת מראה. . ורבינו ז\"ל פי' שהיא רעו\"ד</b>: ראה תו\"א ויצא כג, סע\"ב ואילך. לקו\"ת מטות פז, ג."],["1769","457","<b>בינה ליבא</b>: ת\"ז בהקדמה יז, א."],["1770","458","<b>בד\"ה</b>: בהמשך הנדפס: ליתא. באוה\"ת כאן כבפנים."],["1771","459","<b>בד\"ה ושאבתם מים בששון</b>: ראה לקו\"ת סוכות עח, ד. עט, ג. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה זה פ\"ג."],["1772","460","<b>התגלות עתיק בבינה</b>: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. תו\"ח לך פא, ב. ביאוה\"ז להצ\"צ אחרי ע' שסד."],["1773","461","<b>אהבה בתענוגי'. . בד\"ה חכלילי עינים מיין</b>: תו\"א ויחי מז, ג."],["1774","462","<b>בסש\"ב שאה\"ר היא אהבה בתענוגי'</b>: פמ\"ג."],["1775","463","<b>בא נחש על חוה</b>: שבת קמו, רע\"א."],["1776","464","<b>דקךב\"ב</b>: בהמשך הנדפס: דקך\"ב. באוה\"ת כאן כבפנים."],["1777","465","<b>בבה\"ז</b>: חוקת צו, ב. ולהצ\"צ כרך א' ע' תפז."],["1778","466","<b>ענין כן דרך</b>: בהמשך הנדפס: אינו כן רק. באוה\"ת כאן כבפנים."],["1779","467","<b>נאף בגימ' ס\"מ</b>: במאו\"א שם: נאף הוא סמאל. וביאיר נתיב שם: נא\"ף גי' סמ\"אל. באוה\"ת כאן: נאף הוא סמאל גימ' אחת."],["1780","468","<b>כי</b>: בהמשך הנדפס: כו'. במאו\"א ואוה\"ת כאן כבפנים."],["1781","*469","<b>נאף אשה חסר לב</b>: משלי ו, לב."],["1782","469","<b>דמפתי לי' לאתתא</b>: במאו\"א שם: דפתי לתתא. ובאוה\"ת כאן: דפתי לאתתא."],["1783","470","<b>דר\"ג</b>: ע\"ב."],["1784","471","<b>כעס טורף נפשו</b>: ראה איוב יח, ד. זהר תצוה קפב, א ואילך. ספר הגלגולים ספי\"ב. נגיד ומצוה ירושלים תשכ\"ה ע' קפד. שער מאמרי רז\"ל אבות פ\"ב, מ\"י. שער רוח הקודש [תל אביב תשכ\"ג] לג, ב ואילך. שער הגלגולים הקדמה ה. ספר הליקוטים סוף קהלת. של\"ה שער האותיות אות ר (קו, ב). שו\"ע אדה\"ז הל' משא ומתן סקנ\"ו, ס\"ג. לקו\"ת פינחס פ, ד."]]],[2000470244,"בד\"ה לא תהי' משכלה בענין כוס של ברכה<sup data-n=\"1785\">472</sup> צריך הדחה מבפנים<sup data-n=\"1786\">473</sup>, שצ\"ל מודח מבפנים מכל תאוות גשמיות, ואז יכול להיות בבחי' ותתפלל חנה על הוי'<sup data-n=\"1787\">474</sup> ע\"ש, ועד\"ז יובן כאן ענין בתולה ואיש לא ידעה ואזי יכול להיות רעו\"ד יסוד דנוק' ציון התקשרות ע\"ד ותתפלל חנה על הוי' כו'.\n<b></b>קיצור<sup data-n=\"1788\">475</sup>. ענין נעול בתולה ועמך לא חפצתי, טובת מראה בינה רעו\"ד פנימיות הלב, מאד אהבה בתענוגי', התגלות עתיק בבינה, והיינו ע\"י בתולה כנ\"ל ואיש זר כעס לא ידעה, כוס של ברכה צריך הדחה, וע\"י בחי' רעו\"ד עי\"ז ותתפלל חנה על הוי' כו'.\n(טז) <b>והנה</b> ע\"י<sup data-n=\"1789\">476</sup> שהוא בבחי' גן נעול עי\"ז פתחי לי אחותי<sup data-n=\"1790\">477</sup>, וזהו שאמר אח\"כ בקפיטל<sup data-n=\"1791\">478</sup> שאחר זה פתחי לי אחותי, והיינו ע\"י היותה גן נעול שאוגדת פתחה מזר איש מדון<sup data-n=\"1792\">479</sup> איש תהפוכות<sup data-n=\"1793\">480</sup>, ובעבודה הו\"ע כעס שעי\"ז טורף נפשו, עי\"ז נעשה פתחי לי, ופי' לי הוא ע\"ד וארשתיך לי לעולם<sup data-n=\"1794\">481</sup>, וע' בזהר תרומה דקל\"ד ב' ע\"פ ויקחו לי תרומה ובפי' הרמ\"ז שם<sup data-n=\"1795\">482</sup>, גם י\"ל פתחי לי לבחי' יו\"ד כנודע מענין יעקב יו\"ד עקב<sup data-n=\"1796\">483</sup>, ובפסח נא' ופסח ה' על הפתח<sup data-n=\"1797\">484</sup> שהי' דילוג והמשכה מלמעלה מהשתלשלות והיינו לבחי' פתח הנ\"ל, ולכן נא' לא תצאו מפתח ביתו<sup data-n=\"1798\">485</sup> שהי' צריכין שמירה ע\"ד גן נעול, והפתח יש בו משקוף ושתי המזוזות שהם ג' אבות<sup data-n=\"1799\">486</sup> כמ\"ש",[["1785","472","<b>בד\"ה לא תהי' משכלה בענין כוס של ברכה</b>: תו\"א משפטים עט, א ואילך. תו\"ח משפטים ח\"ב רצז, ד ואילך. וראה גם סה\"מ תרנ\"ד ע' קא ואילך."],["1786","473","<b>כוס של ברכה צריך הדחה מבפנים</b>: ברכות נא, א. שו\"ע אדה\"ז הל' ברהמ\"ז סקפ\"ג, ס\"ב."],["1787","474","<b>ותתפלל חנה על הוי'</b>: חיבור שני כתובים שמואל-א א, י (ותתפלל על הוי'). שם ב, א (ותתפל חנה) — ראה מאמרי אדה\"א ויקרא ח\"א ע' צב. וש\"נ. אוה\"ת כאן ריש ע' תלג. סה\"מ תרל\"ח ע' תקכא. וש\"נ."],["1788","475","<b>קיצור</b>: לשון אוה\"ת שה\"ש כאן ע' תלג בשינויים."],["1789","476","<b>והנה ע\"י</b>: לשון אוה\"ת שה\"ש כאן ע' תלד ואילך ס\"ו בשינויים. ע' תלא ואילך ס\"ג בשינויים."],["1790","477","<b>פתחי לי אחותי</b>: שה\"ש ה, ב."],["1791","478","<b>בקפיטל</b>: ראה גם קול ברמה לד, ב. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ויובן כו' הני ששה ועשרים הודו על יד הערה 38. מאמרי אדה\"ז על מארז\"ל ריש ע' תיד. תו\"ח בא ח\"א קז, ג. וש\"נ. אוה\"ת (יהל אור) תהלים ע' לא ס\"ח. סה\"מ תרל\"ו ח\"ב ע' שלח."],["1792","479","<b>איש מדון</b>: ראה ירמי' טו, י."],["1793","480","<b>איש תהפוכות</b>: משלי טז, כח."],["1794","481","<b>וארשתיך לי לעולם</b>: הושע ב, כא."],["1795","482","<b>בזהר. . ובפי' הרמ\"ז שם</b>: ראה גם אוה\"ת שה\"ש כרך ב ע' תקיג."],["1796","483","<b>יעקב. . יו\"ד עקב</b>: ע\"ח שער סדר אצי' ש\"ג, פ\"ב. ראה לקמן רפ\"כ. תו\"א ר\"פ ויצא. מאמרי אדה\"א דברים ח\"ג ע' תתמז. וש\"נ. תו\"ח שמות ח\"א יח, ב. וש\"נ."],["1797","484","<b>ופסח ה' על הפתח</b>: בא יב, כג."],["1798","485","<b>לא תצאו מפתח ביתו</b>: בא יב, כב [בדילוג]."],["1799","486","<b>משקוף ושתי המזוזות שהם ג' אבות</b>: שמו\"ר ספ\"א. פי\"ז, ג. ראה אוה\"ת חנוכה ח\"ב ע' שכח. ואתחנן כרך ו ע' ב'רעט ואילך. עקב ע' תרכג. דברים כרך ד ע' א'תתקמד."]]],[2000470245,"במ\"א, וכן פי' בזח\"א בהשמטות סי' ך\"ט די\"ג ע\"א<sup data-n=\"1800\">487</sup> גן נעול כו' סתימא דלא\n&lt;22&gt;\nּ אתפתחית<sup data-n=\"1801\">488</sup> אלא לגבי בעלה, והיינו פתחי לי כנ\"ל.\n<b>ובת\"י</b><sup data-n=\"1802\">489</sup> מפרש ע\"פ פתחי לי פתחי פומך בשירין ותושבחין<sup data-n=\"1803\">490</sup> כו', וא\"כ יש לפרש כמו שנת' לעיל גן נעול שיהי' פי' נעול מלדבר דברים בטלים<sup data-n=\"1804\">491</sup> רק יהי' דבורו בג\"ן סדרי' דאוריי' וזהו פתחי לי כו'.\n<b>והנה</b> כתי' כבוד חכמים ינחלו<sup data-n=\"1805\">492</sup>, ואין כבוד אלא תורה, ובבחיי<sup data-n=\"1806\">493</sup> ס\"פ תולדות<sup data-n=\"1807\">494</sup> כי הנפש נק' כבוד לפי שהיא חצובה מכסה\"כ, ושרשה שהיא<sup data-n=\"1808\">495</sup> עתידה לשוב שם הוא כסה\"כ, וזהו למען יזמרך כבוד, וכתי'<sup data-n=\"1809\">496</sup> וכבוד ה' יאספך<sup data-n=\"1810\">497</sup>, וי\"ל שלפי שנש\"י שרשם מס\"ר אותיות התו' וכנ\"ל לכן נק' כבוד, ועז\"נ ג\"כ כבוד חכמים ינחלו שחכמים שלומדי' תורה מתעלי' לשרשן בחי' אותיות התו', וכן פי' הבחיי ג\"כ בפ' כי תשא<sup data-n=\"1811\">498</sup> שכ' וידוע כי הלוחות של סנפירין היו<sup data-n=\"1812\">499</sup> ולוקחו מכסה\"כ, וכן מצינו בכה\"כ דכתי'<sup data-n=\"1813\">500</sup> כמראה אבן ספיר<sup data-n=\"1814\">501</sup> דמות כסא<sup data-n=\"1815\">502</sup>, ומפני שהתו' לוקחה<sup data-n=\"1816\">503</sup> מכה\"כ נק' התו' כבוד שנא' כבוד חכמים ינחלו, וכן הנפש השכלית שרשה בכסה\"כ ונקראת כבוד שנא' למען יזמרך כבוד, ונפשו של אדם המתעסק בתורה זוכה לשוב לשרשו<sup data-n=\"1817\">504</sup> שנא' תורת ה' תמימה<sup data-n=\"1818\">505</sup> משיבת נפש<sup data-n=\"1819\">506</sup> עכ\"ל. ומפרש שמשיבת הנפש הוא בתורת ה' והיינו כנ\"ל.\n<b>ופי'</b> ענין כבוד ע' בע\"ח שער כסה\"כ, ובמאו\"א ך' סעי' ך\"ב כסא נק' היכל קדה\"ק דבריאה כסא לבחי' המל' שנק'<sup data-n=\"1820\">507</sup> כבוד, ובפרד\"ס ערך כסא<sup data-n=\"1821\">508</sup> לפעמים",[["1800","487","<b>בזח\"א. . די\"ג ע\"א</b>: לפנינו: רסב, ב."],["1801","488","<b>אתפתחית</b>: וכ\"ה באוה\"ת כאן. בזהר ובהמשך הנדפס: אתפתחת."],["1802","489","<b>ובת\"י</b>: וכ\"ה לעיל מאמר ד\"ה סמכוני באשישות ובהערה 88."],["1803","490","<b>פתחי פומך בשירין ותושבחין</b>: בתרגום שם: פתחי פומך ובועי ושבחי."],["1804","491","<b>שיהי' פי' </b>[באוה\"ת: פיו]<b> נעול מלדבר דברים בטלים</b>: ראה סה\"מ מלוקט ד' ע' רלז ובהערה 7."],["1805","492","<b>כבוד חכמים ינחלו</b>: משלי ג, לה."],["1806","493","<b>ובבחיי</b>: לשון אוה\"ת שה\"ש כאן ע' תלא ואילך ס\"ג בשינויים והוספות."],["1807","494","<b>ובבחיי ס\"פ תולדות</b>: כ\"ה גם באוה\"ת כאן. ראה שם ס\"פ ח\"ש (כה, ח)."],["1808","495","<b>שהיא</b>: בהמשך הנדפס: לפי שהיא. בבחיי ואוה\"ת כבפנים."],["1809","496","<b>וכתי'</b>: בבחיי ואוה\"ת: ולא ידום, וזהו."],["1810","497","<b>וכבוד ה' יאספך</b>: ישעי' נח, ה [ושם: כבוד — וכ\"ה בבחיי ואוה\"ת כאן — ראה תו\"ח משפטים ח\"ב שב, ב הערה 498]."],["1811","498","<b>פי' הבחיי. . כי תשא</b>: ראה שם לא, יח בסופו."],["1812","499","<b>של סנפירין היו</b>: בבחיי: היו של סנפירינון. באוה\"ת כאן: הי' של סנפירון. ראה גם לקו\"ש עקב כרך יט ע' 106 הערה 9."],["1813","500","<b>דכתי'</b>: שם: ליתא."],["1814","501","<b>כמראה אבן ספיר</b>: יחזקאל א, כו."],["1815","502","<b>כסא</b>: באוה\"ת ניתוסף: כו'."],["1816","503","<b>שהתו' לוקחה</b>: בבחיי ואוה\"ת: שהלוחות לוקחו."],["1817","504","<b>לשרשו</b>: שם: לשרשה."],["1818","505","<b>תורת ה' תמימה</b>: תהלים יט, ח."],["1819","506","<b>נפש</b>: באוה\"ת ניתוסף: כו'. בבחיי: ליתא."],["1820","507","<b>לבחי' המל' שנק'</b>: במאו\"א ובאוה\"ת: למלכות דאצילות הנק'."],["1821","508","<b>ובפרד\"ס ערך כסא</b>: ראה שער כ\"ג שער ערכי הכנויים פי\"א. הועתק — בשינוי — גם באוה\"ת נצבים ע' א'ריד."]]],[2000470246,"הבינה נק' כסא והיינו שהיא כסא לבחי' כבוד עליון כתר שהיא מל' דא\"ס שעז\"נ הראני נא את כבודך<sup data-n=\"1822\">509</sup>, ובינה נק' ג\"כ קדה\"ק<sup data-n=\"1823\">510</sup>, והלוחות חרות<sup data-n=\"1824\">511</sup> אותיות החקיקה, שרשן מהכתר גליף גליפו בטה\"ע<sup data-n=\"1825\">512</sup>, ומשם שרש הנשמות ג\"כ כמ\"ש בד\"ה אם בחקתי<sup data-n=\"1826\">513</sup> ובביאור ע\"פ זאת חקת התורה<sup data-n=\"1827\">514</sup>, ועז\"נ ג\"כ<sup data-n=\"1828\">515</sup> למען יזמרך כבוד וכנ\"ל<sup data-n=\"1829\">516</sup> בענין הרשימו שהניח הא\"ס שז\"ע אותיות החקיקה שרש התו' כו'<sup data-n=\"1830\">517</sup>.\n<b></b>קיצור. ע\"י גן נעול נעשה פתחי לי, ופי' נעול מדב\"ט לעסוק בג\"ן סדרים דאורייתא, והתו' נק' כבוד, והנפש חצובה מכסה\"כ, כסה\"כ היכל קד\"ק דבריאה, וכן באצי', חרות חקיקה גליף גליפו בטה\"ע ע\"ד הרשימו<sup data-n=\"1831\">518</sup>. ",[["1822","509","<b>כתר. . הראני נא את כבודך</b>: תשא לג, יח. ראה זהר רע\"מ פינחס רנה, ב. אוה\"ת נצבים שם."],["1823","510","<b>ובינה נק' ג\"כ קדה\"ק</b>: ראה ביאוה\"ז להצ\"צ כרך ב פ' יתרו ע' תשפד. לעיל מאמר ד\"ה כמגדל דוד צוארך על יד הערה 66."],["1824","511","<b>והלוחות חרות</b>: ראה תשא לב, טז."],["1825","512","<b>גליף גליפו בטה\"ע</b>: ראה זהר בראשית טו, א."],["1826","513","<b>בד\"ה אם בחקתי</b>: לקו\"ת שם מה, א ואילך. מז, א."],["1827","514","<b>ובביאור ע\"פ זאת חקת התורה</b>: אוה\"ת חוקת ע' תשעג."],["1828","515","<b>ג\"כ</b>: בהמשך הנדפס: ליתא. באוה\"ת כאן כבפנים."],["1829","516","<b>וכנ\"ל</b>: פ\"ו."],["1830","517","<b>כו'</b>: וכ\"ה באוה\"ת. בהמשך הנדפס: כנ\"ל."],["1831","518","<b>והנפש חצובה. . הרשימו</b>: ראה הקיצור באוה\"ת כאן ע' תלב."]]],[2000470247,"<h3>גל נעול מעין חתום</h3>\n<b>פ' אחו\"ק</b>\n(יז) <b>גל</b> נעול<sup data-n=\"1832\">519</sup> מעיין חתום<sup data-n=\"1833\">520</sup>, פרש\"י יש לפרשו לשון מעיין כמו גולת עילית<sup data-n=\"1834\">521</sup> ביהושע סי'<sup data-n=\"1835\">522</sup> ויש לפרשו לשון שער והוא ל' ארמי בתלמוד טרוקי<sup data-n=\"1836\">523</sup> גלי",[["1832","519","<b>גל נעול</b>: מכאן מתחיל מאמר הה' מהמשך מצה זו (הכולל פרקים יז-יט).\nפי\"ז — לשון אוה\"ת שה\"ש כאן ע' תלה בשינויים והוספות.\nנזכר בסה\"מ מלוקט ד' ע' רמ.\nפי\"ח — לשון לקו\"ת תצא לה, ג ואילך בשינויים והוספות. ראה גם אוה\"ת נצבים כרך ה ע' ב'נד ואילך.\nפי\"ט — לשון לקו\"ת שם לה, ד ואילך בשינויים והוספות. ראה גם אוה\"ת נצבים שם ע' ב'נה ואילך. סה\"מ מלוקט ג' ע' רפה ואילך.\nנזכר בסה\"מ תרמ\"ד ע' רעא.\nהנחת<sup data-n=\"e100\">*</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן (בחלק הנחותיו)."],["1833","520","<b>גל נעול מעיין חתום</b>: שה\"ש ד, יב. לשון אוה\"ת שה\"ש ח\"ב כאן ע' תלה בשינויים והוספות."],["1834","521","<b>גולת עילית</b>: ברש\"י ובאוה\"ת: גולות עיליות."],["1835","522","<b>סי'</b>: באוה\"ת: סי' ט\"ו, יט."],["1836","523","<b>טרוקי</b>: כ\"ה גם באוה\"ת שה\"ש ח\"ב ע' תמז. לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן. ברש\"י ובאוה\"ת כאן: טרוקו."],["e100","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470248,"בפ\"ד דברכות דך\"ח ע\"א, ובתרגום פי' לשון מעיין, וז\"ל כמבועי דמיין חיין דנפיק מתחות אילנא ומתפרש לארבעת רישי נהרין עכ\"ל. ונראה שהוא ענין ונהר יוצא מעדן כו' ופי' שיוצא מתחת עה\"ח להשקות כו' ואח\"כ ומשם יפרד והי' לד' ראשים שהם ד' מחנות שכינה<sup data-n=\"1837\">524</sup> כו', אך הנה המעיין צ\"ל חתום, והיינו כמו שא' ברישא דקרא גן נעול, וכאן קורא אותו גל נעול ומפרש שפעולת הגל הוא בכדי שיהי' מעיין חתום, וצ\"ל מהו\"ע שקורא אותו גל, אך הענין הוא שבחי' הגל הוא הפסק ומחיצה וכמו שנת\"ל<sup data-n=\"1838\">525</sup> בענין עד הגל הזה שעשו יעקב &lt;23&gt;\nּ ולבן גל להפסק שלא יעברו זל\"ז לרעה, וכמ\"כ יובן כאן ג\"כ שענין הגל הוא ענין ההפסק שלא יקרבו להגן, וזהו נעילת הגן שע\"י מה יהי' נעול שלא יכנס זר להגן זהו ע\"י הגל שהוא המפסיק כו', וקאי על ז' מצות<sup data-n=\"1839\">527</sup> דרבנן<sup data-n=\"1840\">526</sup> שהם הם מה שהוסיפו חכמים בכדי לגדור ולנעול את הגן עד שיהי' המעיין חתום כו', ויובן זה בהקדם מ\"ש ויבן ה' אלקים את הצלע<sup data-n=\"1841\">528</sup>, ודרשו רז\"ל ויבן לשון בינה וארז\"ל בגמ' פ\"ה דנדה<sup data-n=\"1842\">529</sup> ובמד\"ר בראשית ר\"פ י\"ח בינה יתירה ניתנה באשה יותר מבאיש כו', וצ\"ל מהו הבינה היתירה ולמה באשה דוקא כו', הנה ידוע דבחי' דבור נק' אשה, והקול נק'<sup data-n=\"1843\">530</sup> איש<sup data-n=\"1844\">531</sup> לפי שהדיבור הוא בחי' מקבל מקול הבל הלב הפשוט כו', וגם יראה נק' אשה<sup data-n=\"1845\">532</sup> כמ\"ש אשה יראת ה' היא תתהלל<sup data-n=\"1846\">533</sup> כו'<sup data-n=\"1847\">534</sup>, וגם תושבע\"פ נק' אשה כי מאיש לוקחה זאת<sup data-n=\"1848\">536</sup> כו' דהיינו מתושב\"כ שנק' איש<sup data-n=\"1849\">535</sup> כידוע בספרי הקבלה.\n<b>והנה</b> כשאמרו בינה יתירה ניתנה באשה כו' הכוונה על ג' דברים הנ\"ל שנמשל לאשה דבור ויראה ותושבע\"פ כו', וביאור הדברים הנה בדבור ויראה אנו רואים שיש בינה יתירה כו' בהיות נראה בחוש שע\"י הדיבור<sup data-n=\"1850\">537</sup> בלמדו איזה הלכה",[["1837","524","<b>ומשם יפרד. . ד' מחנות שכינה</b>: בראשית ב, י. ראה זהר בראשית כו, ב. אוה\"ת בראשית כרך ג ע' 1108. סה\"מ תרל\"ח ע' צא. ע' קו. ע' קי."],["1838","525","<b>שנת\"ל</b>: פי\"א ד\"ה ועוי\"ל."],["1839","527","<b>ז' מצות דרבנן</b>: ראה אגה\"ק סכ\"ט. דרך חיים פנ\"ו. פס\"ד. לקו\"ש שופטים כרך כט ע' 104 ואילך. וש\"נ."],["1840","526","<b>ז' מצות דרבנן</b>: וסימנם: נ\"ע בשמח\"ה — ראה לקו\"ש יתרו כרך כא ע' 401. אג\"ק שלו ח\"ב ע' שכ."],["1841","528","<b>ויבן ה' אלקים את הצלע</b>: בראשית ב, כב. לשון מאמרי אדה\"ז תקס\"ד ס\"ע מט ואילך בשינויים והוספות (הועתק באוה\"ת כאן). ונו\"א במאמרי אדה\"ז על פרשיות התורה ח\"א ע' נה ואילך. ראה הנסמן בהנ\"ל."],["1842","529","<b>פ\"ה דנדה</b>: מה, ב."],["1843","530","<b>דבור נק' אשה והקול נק' איש</b>: ראה זהר שמות ג, א. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 16."],["1844","531","<b>איש</b>: בהמשך הנדפס אשה. והוא כנראה שגגת המעתיק."],["1845","532","<b>יראה נק' אשה</b>: ראה זהר ח\"ש קכב, א. פקודי רלט, ב."],["1846","533","<b>אשה יראת ה' היא תתהלל</b>: משלי לא, ל."],["1847","534","<b>כו'</b>: כ\"ה גם במאמרי אדה\"ז תקס\"ד ובאוה\"ת כאן."],["1848","536","<b>כי מאיש לוקחה זאת</b>: בראשית ב, כג."],["1849","535","<b>תושבע\"פ נק אשה. . מתושב\"כ שנק' איש</b>: ראה (בנוסף להערה 528) תו\"ח ויקהל ח\"ב תטז, ג ובהנסמן שם. לעיל רפ\"ב. המשך זאת חנוכת פכ\"א ובהערות 569-570."],["1850","537","<b>שע\"י הדיבור</b>: ראה אוה\"ת שה\"ש ע' תנ ואילך. פלח הרמון שה\"ש ע' קלד. לעיל מאמר ד\"ה כמגדל דוד צוארך ובהערה 42. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 24."]]],[2000470249,"משכיל בה שכל עמוק מה שלא יוכל להשיגו כלל במחשבת עיון בלבד, וכמארז\"ל ומתלמידי יותר מכולם<sup data-n=\"1851\">538</sup>, הרי נולד ונמשך שכל חדש ממקור השכל ע\"י הדבור, ונמצא הדבור שמוליד שכל שיש בינה יתירה בכח הדבור שלמעלה מן השכל, והיינו לפי שהדבור שרשו מקדמות השכל כמ\"ש באגה\"ק בד\"ה ויעש דוד שם<sup data-n=\"1852\">539</sup> וכנ\"ל<sup data-n=\"1853\">540</sup>, ולכן עיקר עסק התורה להוציא הדברים בדבור בפה<sup data-n=\"1854\">541</sup>, וכן אנו רואים בקול הדבור שהוא מעורר כוונת הלב<sup data-n=\"1855\">542</sup> בהתפעלות גדולה יותר מכפי ערך ההתפעלות המדות עצמן כמו שנולדו מן השכל ע\"י מחשבה וההתבוננות שהרי אנו רואים כשיחשוב האדם ויתבונן בתפלה ויוליד אהוי\"ר כו' אינו מתפעל כ\"כ כמו שמתפעל כאשר הקול שבדבור מעורר הכוונה שבלב כו' ומזה מוכח ומוכרח לומר שבינה יתירה יש בדבור שמעורר מה שבנקודת הלב שלמעלה מהשכל המוליד את המדות כו' וע\"ד ז\"א בעתיקא אחיד ותלי'<sup data-n=\"1856\">543</sup> למעלה מאו\"א.\n<b></b>קיצור. גל נעול ל' מעיין או שער, והוא מעיין מקור הנהר היוצא מעדן וזהו ע\"י הגל מחיצה שעי\"ז הוא מעיין חתום, ויובן בהקדם מארז\"ל ע\"פ ויבן בינה יתירה ניתנה באשה היא דבור ויראה ותושבע\"פ, כי מתלמידי יותר מכולם, שהדבור שרשו מקדמות השכל ומעורר הכוונה כו'.\n(יח) <b>וביאור</b><sup data-n=\"1857\">544</sup> ענין בחי' נקודת הלב, הנה ברתא דמלכא<sup data-n=\"1858\">545</sup> הוא בחי' נקודת ציון וכנס\"י שכונסת ואוספת לתוכה<sup data-n=\"1859\">546</sup> הארת ישראל דלעילא<sup data-n=\"1860\">547</sup>, והוא בחי' נקודת הלב ופנימיותו המתגלה בכללות נש\"י בבחי' רעו\"ד, וכמ\"ש בכל לבבך שיש ב' לבבות<sup data-n=\"1861\">548</sup> חיצוני' הלב ופנימיות הלב, חיצוניות הלב הוא למטה מן הדעת שממנה לוקחה והיא בחי' התגברות הנפש בכח &lt;24&gt;\nּ השגתה והשכלתה שמשכלת",[["1851","538","<b>ומתלמידי יותר מכולם</b>: תענית ז, א. ראה גם לעיל בהמאמר שם על יד הערה 41 ואילך. שע\"ת ק, ד ובהנסמן לשם. פלח הרמון שם. וראה גם לקמן פ\"ל. פרק ג\"ן בסמיכות להערה 1554. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וירא העם וינועו ובהערה 95. מאמר ד\"ה בכ\"ה בכסלו יומי דחנוכה ש\"מ טבת תשח\"י."],["1852","539","<b>באגה\"ק בד\"ה ויעש דוד שם</b>: ס\"ה (קז, ב)."],["1853","540","<b>וכנ\"ל</b>: פ\"ב."],["1854","541","<b>עיקר עסק התורה. . בדבור בפה</b>: ראה (בנוסף להערה 528) הל' ת\"ת לאדה\"ז פ\"ב, הי\"ב. מאמרי אדה\"ז תקס\"ז ע' מ ואילך. מאמרי אדה\"א דברים ח\"א ע' רמ. וש\"נ. לעיל המשך זאת חנוכת המזבח פכ\"ג ובהערה 667."],["1855","542","<b>בקול. . מעורר כוונת הלב</b>: ראה טושו\"ע או\"ח סס\"א, ס\"ד. ר\"ח שער הקדושה ספט\"ו. מאמרי אדה\"ז (שבהערה 528) ובהנסמן במ\"מ לשם. תו\"ח בא ח\"א קו, ד ובהערה 433."],["1856","543","<b>ז\"א בעתיקא אחיד ותלי'</b>: בזהר הרקיע אמור קד, א: כנזכר באד\"ר [הובא לקמן פ\"כ ובהערה 643]. ראה זהר אד\"ז האזינו רצב, א. סה\"מ תרנ\"ו ע' תכז ובהערה לשם. תרל\"ב ח\"א ס\"ע יג ואילך. וש\"נ. תו\"ח בא ח\"א קל, ב ובהערה 796. סה\"מ מלוקט ב' ס\"ע קח ואילך אות יא."],["1857","544","<b>וביאור</b>: לשון לקו\"ת תצא לה, ג ואילך בשינויים והוספות. ראה גם אוה\"ת נצבים כרך ה ע' ב'נד ואילך."],["1858","545","<b>ברתא דמלכא</b>: הובא (גם לעיל) בלקו\"ת שם. ראה ת\"ז סתי\"ג כט, ב. וראה גם תכ\"א מג, א."],["1859","546","<b>וכנס\"י שכונסת ואוספת לתוכה</b>: ראה גם תו\"א תצוה פד, ב. סה\"מ תרל\"ח ע' תיט. וש\"נ."],["1860","547","<b>ישראל דלעילא</b>: זהר שמות ה, א. יז, סע\"א. ועוד. וראה גם אוה\"ת שמות כרך ז ע' ב'תעו ממד\"ר ופדר\"א."],["1861","548","<b>בכל לבבך שיש ב' לבבות</b>: ואתחנן ו, ה. ראה גם לקו\"ת בלק סז, ד."]]],[2000470250,"ומתבוננת שאין לך עשב<sup data-n=\"1862\">549</sup> מלמטה שאין לו מזל כו', וגבוה מעל גבוה שומר<sup data-n=\"1863\">550</sup> עד רום המעלות מקור וראשית כל ההשתלשלות והתהוות החיות הוא וברוח פיו כל צבאם<sup data-n=\"1864\">551</sup> ואתה מחיה את כולם<sup data-n=\"1865\">552</sup>, וכתי' ראה נתתי לפניך<sup data-n=\"1866\">553</sup> את החיים ואת הטוב כו'<sup data-n=\"1867\">554</sup> שבכל דבר נברא יש בו<sup data-n=\"1868\">555</sup> בחי' מות וחיים, שהמות הוא גשמיות הדבר וחומריותו, והחיים היינו הרוחניות שבו שלכן ובחרת בחיים<sup data-n=\"1869\">556</sup> לאהבה את ה' כי הוא חייך כו'<sup data-n=\"1870\">557</sup>, שהוא חיי החיים ומקורא וראשיתה דכולא, והכל נגדו בחי' מות, וזהו רוממות אל בגרונם<sup data-n=\"1871\">558</sup> וחרב פפיות בידם לעשות<sup data-n=\"1872\">559</sup> כו', ור\"ל המעשים והדבורים ומחשבות אשר לא לה' המה והם נמשכים מבחי' עמלק דכתי' בי' אשר קרך בדרך שפועל הקרירות<sup data-n=\"1873\">560</sup> בד'<sup data-n=\"1874\">561</sup> ה'<sup data-n=\"1875\">562</sup> הם בחי' תומ\"צ כמ\"ש ושמרו דרך ה'<sup data-n=\"1876\">563</sup> לעשות צדקה ומשפט, וע\"י הקרירות בדרכי ה' עושה מעשים אשר לא לה' המה ומחשב ומדבר במח' ודברים אשר לא לה' המה, והנקמה שהיא ביטולם ושבירתם הוא ע\"י וחרב פפיות שמבחי' רוממות אל דהיינו כשמתבונן האדם שהוא ית' מקור וראשית ההשתלשלות וחיי החיים ב\"ה, וז\"ש בחרבי ובקשתי ות\"א בצלותא ובעותא<sup data-n=\"1877\">564</sup> שע\"י התפלה שבה נז' רוממותו ושבחו של מקום וכמארז\"ל לעולם יסדר אדם שבחו ש\"מ<sup data-n=\"1878\">565</sup> ואח\"כ יתפלל עי\"ז נעשה בחי' חרב וקשת לבטל הרע שבנפשו כו', והנה התבוננות זו היא מבחי' מלכותו ית' הממלא כל עלמין כי מלכותך מל' כ\"ע<sup data-n=\"1879\">566</sup> כתי' ושם עלו השגת הנשמות ומלאכים וכמ\"ש יוצר משרתים ואשר משרתיו כולם עומדים כו' ומקדישים<sup data-n=\"1880\">567</sup> וממליכים את שם כו' דהיינו בחי' ומדת מלכותו שאינו אלא בחי' שם לבד כי הוא ית' מרום וקדוש שמרומם ומובדל כו', וכן<sup data-n=\"1881\">568</sup> שם הוא",[["1862","549","<b>שאין לך עשב</b>: ראה אוה\"ת וארא כרך ח ע' ב'תתפג שמציין: הובא בר\"ח פ\"ה משער האהבה והוא במ\"ר בראשי' פ\"י[, ו]. מאמרי אדה\"א דברים ח\"ג ע' תתמח. וש\"נ. שם ע' תתעו ואילך. שער האמונה ע' נג. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת על יד הערה 42. (בחלק ההנחות) ד\"ה אני לדודי הב' על יד הערה 66."],["1863","550","<b>וגבוה מעל גבוה שומר</b>: קהלת ה, ז."],["1864","551","<b>וברוח פיו כל צבאם</b>: תהלים לג, ו."],["1865","552","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["1866","553","<b>ראה נתתי לפניך</b>: נצבים ל, טו [בדילוג — בלקו\"ת כאן: לפניך היום]."],["1867","554","<b>ואת הטוב כו'</b>: בלקו\"ת כאן: וגו'."],["1868","555","<b>בו</b>: בהמשך הנדפס ליתא. בלקו\"ת כבפנים."],["1869","556","<b>ובחרת בחיים</b>: נצבים ל, יט."],["1870","557","<b>כו'</b>: בלקו\"ת כאן: וגו'."],["1871","558","<b>רוממות אל בגרונם</b>: תהלים קמט, ו."],["1872","559","<b>לעשות</b>: תהלים שם, ז."],["1873","560","<b>אשר קרך. . הקרירות</b>: תצא כה, יח. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 47. הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 101. ש\"א מה, ב. מאמרי אדה\"א במדבר ח\"ג ע' תתקמט. שיחת שמחת בית השאיבה תרצ\"ב אטוואצק נדפס ברשימות חוברת ז ע' 52 חוברת קי לפ' תצא ובהנסמן שם."],["1874","561","<b>בד' ה'</b>: בדרך הוי'."],["1875","562","<b>ה'</b>: בהמשך הנדפס ליתא."],["1876","563","<b>ושמרו דרך ה'</b>: וירא יח, יט."],["1877","564","<b>בחרבי ובקשתי ות\"א בצלותא ובעותא</b>: ויחי מח, כב [בת\"א ובהמשך הנדפס: בצלותי ובבעותי. בלקו\"ת כאן (ובשה\"ש טו, א): ובעותי — וכ\"ה בשע\"ת פב, סע\"ג. אוה\"ת בלק ריש ע' תתקב. המשך תער\"ב ח\"א ס\"ע תקמח]."],["1878","565","<b>לעולם. . שבחו ש\"מ</b>: ע\"ז ז, סע\"ב. ברכות לב, א."],["1879","566","<b>מלכותך מל' כ\"ע</b>: תהלים קמה, יג. ראה גם תו\"א מקץ לז, א. ראה גם לעיל המשך זאת חנוכת המזבח פ\"ד ובהערה. 66"],["1880","567","<b>וכמ\"ש יוצר משרתים. . ומקדישים</b>: בברכת יוצר."],["1881","568","<b>וכן</b>: בהמשך הנדפס: לכן."]]],[2000470251,"דביקת הנפש המשכלת ומתבוננת בשרשה באלקים חיים ומלך עולם<sup data-n=\"1882\">569</sup> בחי' מלכותו ית' וכמאמר ברוך שם<sup data-n=\"1883\">570</sup> כבוד מל' לע\"ו<sup data-n=\"1884\">571</sup> ועי\"ז ואהבת כו'.\n<b>אך</b> בחי' פנימיות הלב היא רעותא דלבא ותעלומות לב<sup data-n=\"1885\">572</sup> אשר למעלה מעלה מן הטעם ודעת המושג ומושכל בכח השגת הנפש והשכלתה, והוא<sup data-n=\"1886\">573</sup> בחי' אלקות שבנפש המתגלה בבחי' יחידה שבה להשתפך אל חיק אבי' ממש בבחי' ביטול כו', והארה זו היא מבחי' סוכ\"ע, כי הנה ממכ\"ע היינו חיות ואוא\"ס<sup data-n=\"1887\">574</sup> ב\"ה שיורד ומשתלשל בהשתלשלות המדרגות מעילה לעילה הארה והארה דהארה כו', ובחי' סוכ\"ע היינו שהוא לבדו ית' כמו קודם שנברא כו' שאינו בגדר עלמין כלל ולא שייך לפניו ית' בחי' השתלשלות כלל, וכמ\"ש את השמים ואת הארץ אני מלא<sup data-n=\"1888\">575</sup> ששמים וארץ שניהם שוין כנגדו ית', וכמאמר והקדוש בשמים ובארץ<sup data-n=\"1889\">576</sup> שהוא קדוש ומובדל בשמים ממעל ועל הארץ מתחת שגם הרוחניות כמו בחי' הגשמיות יחשב לפניו ית', ולכן המלאכים אומרים אי' מקום כבודו<sup data-n=\"1890\">577</sup>, ואומרים מלא כל הארץ כבודו<sup data-n=\"1891\">578</sup>, והנה ארז\"ל אין מזל לישראל<sup data-n=\"1892\">579</sup>, וכדכתי' ואתם תהיו לי<sup data-n=\"1893\">580</sup> כו' שאתם מקבלים מבחי' קדוש ומובדל שאינו בגדר השתלשלות בחי' סוכ\"ע, ושם הוא שרש נקודת פנימיות הלב להיות האהבה לה' למעלה מבחי' טעם ודעת בבחי' רעו\"ד, וכמ\"ש מי לי בשמים<sup data-n=\"1894\">581</sup> ועמך לא חפצתי, כלה שארי ולבבי<sup data-n=\"1895\">582</sup> צור לבבי וחלקי אלקי' לעולם.\n<b></b>קיצור. נקודת ציון וכנס\"י היא בחי' פנימיות הלב, שיש ב' בחי' פנימיות הלב הנלקחה מהתבוננות &lt;25&gt;\nּ בחי' ממכ\"ע, ופנימיות הלב היא מבחי' סוכ\"ע שקדוש ומובדל, רק שבנש\"י כתי' ואתם תהיו לי וכמארז\"ל אין מזל לישראל לכן יש בכאו\"א בחי' נקודת פנימיות הלב בבחי' יחידה שבנפש כו'.\n(יט) <b>אך</b><sup data-n=\"1896\">583</sup> הנה אהבה זו בנפש היא מוסתרת ומכוסה בלבוש שק בבחי' גלות בתוך הגוף ונפש הבהמית וכענין מארז\"ל שכינה עמהם<sup data-n=\"1897\">584</sup>, דשכינה היא ניצוץ",[["1882","569","<b>באלקים חיים ומלך עולם</b>: ברכת יוצר. ירמי' י, י."],["1883","570","<b>ברוך שם</b>: פסחים נו, א (נוסח ק\"ש). ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וירא העם וינועו על יד הערה 76 ואילך."],["1884","571","<b>לע\"ו</b>: בהמשך הנדפס ליתא. בלקו\"ת כבפנים."],["1885","572","<b>ותעלומות לב</b>: תהלים מד, כב."],["1886","573","<b>והוא</b>: בלקו\"ת: והיא."],["1887","574","<b>ואוא\"ס</b>: וכ\"ה בלקו\"ת. בהמשך הנדפס לאוא\"ס. והוא כנראה שגגת המעתיק."],["1888","575","<b>את השמים. . מלא</b>: ירמי' כג, כד. ראה תניא פמ\"ח. תו\"ח בשלח ח\"א קסו, ג. וש\"נ."],["1889","576","<b>והקדוש בשמים ובארץ</b>: ברכת ישתבח. ראה גם לקו\"ת שלח נא, ד. מאמרי אדה\"א שמות ח\"ב ס\"ע תכב. וש\"נ. דברים ח\"א ע' קפג. וש\"נ."],["1890","577","<b>אי' מקום כבודו</b>: נוסח קדושת כתר."],["1891","578","<b>מלא כל הארץ כבודו</b>: ישעי' ו, ג."],["1892","579","<b>אין מזל לישראל</b>: שבת קנו, א. ראה מאמרי אדה\"א שמות ח\"ב ע' שפ. וש\"נ."],["1893","580","<b>ואתם תהיו לי</b>: יתרו יט, ו."],["1894","581","<b>מי לי בשמים</b>: תהלים עג, כה."],["1895","582","<b>כלה שארי ולבבי</b>: תהלים שם, כו."],["1896","583","<b>אך</b>: לשון לקו\"ת תצא לה, ד ואילך בשינויים והוספות. ראה גם אוה\"ת נצבים כרך ה ע' ב'נה ואילך. סה\"מ מלוקט ג' ע' רפה ואילך.\nפרק זה הובא בסה\"מ תרמ\"ד ע' רעא."],["1897","584","<b>שכינה עמהם</b>: מכילתא בא יב, מב. ספרי בהעלותך י, לה. מסעי לה, לד. מגילה כט, א."]]],[2000470252,"אלקי שבנפש<sup data-n=\"1898\">585</sup> שהוא בבחי' גלות ושעבוד דאגת הפרנסה שמקפת ומלבשת את בחי' פנימיות הלב והנפש, כי בנפשו יביא לחמו<sup data-n=\"1899\">586</sup>, ולבו טרוד ברבות מחשבות<sup data-n=\"1900\">587</sup> כו', וע\"ז אמרו בזהר מאן דקטיל לחויא<sup data-n=\"1901\">588</sup> בבחי' התגברות הנפש במלחמה המסורה לידה בכח שכלה והשגתה, יהבין לי' מלעילא בחי' ברתא דמלכא הוא בחי' גילוי פנימיות הלב בנפש, והוא מלחמה להוי' בעמלק<sup data-n=\"1902\">589</sup> להוציאה מהעלם אל הגילוי, ועז\"נ כי תצא למלחמה<sup data-n=\"1903\">590</sup> דהיינו מלחמת הנפש בזה לעומת זה להגביר כנ\"ל אזי תהי' על אויביך הוא בחי' גילוי נקודת הלב שהוא מבחי' סוכ\"ע למעלה מאויביך שאין לאויב שליטה ואחיזה שם, וכמ\"ש בע\"ח בשם הזהר<sup data-n=\"1904\">591</sup> הובא בסש\"ב ס\"פ ט', והיינו בהגלות נגלות אור ה' הסוכ\"ע בבחי' פנימיות נקודת הלב שהוא למעלה מאויביך דוקא.\n<b>והנה</b> גילוי זה שע\"י ניצוח המלחמה בכח הנפש שלמטה הוא גילוי הארת נקודת הלב בנפש<sup data-n=\"1905\">592</sup> להפוך לבושי מחדומ\"ע שבזלע\"ז ולקבץ כחות הנפש האלקי' המפוזרים בפיזור הנפש בלבושי' ההם שכחותי' והארותי' בלבד הם שמתפשטי' בלבושים הללו, ועז\"נ אם יהי' נדחך<sup data-n=\"1906\">593</sup> בקצה השמים משם יקבצך כו' שהנדחים הם הארת כחות הנפש המתפשטים מן הנשמה להתפשט ולהתלבש בגוף ונפש הבהמי' ברבות מחשבות הטורדות ומבלבלות ומפילות את האדם להמשך אחריהם, וכנודע מענין החלומות וכף הקלע שהם מהלבושי' המלבישים את הנפש מראשה ועד רגלה עד שהיא אסורה וקשורה בהם והקיבוץ הוא ע\"י הארת גילוי נקודת הלב שמבחי' סוכ\"ע שיהבין לי' מלעילא ע\"י דקטיל לחויא כנ\"ל.\n<b>אך</b> כדי להפוך עצמיות המדות מרע לטוב צ\"ל בחי' גילוי עצמיות נקודת הלב ממש, שכדי להוציא בחי' עצמיות שכל ומדות ממאסר וגלות הגוף ונה\"ב, שתהיינה<sup data-n=\"1907\">594</sup> לה' לבדו ולבער הרע מקרבו מכל וכל, והיינו בהתהפכות המדות של הרע לטוב ממש ולהכלל בקדושה וכמ\"ש בסש\"ב פ' יו\"ד, צריך להמשיך גילוי אלקות מבחי' מזל הוא הנשמה שלמעלה מהגוף<sup data-n=\"1908\">595</sup>, שלא כל הנשמה מלובש בגוף כמ\"ש במ\"א שהרי המלאך בשליש העולם עומד<sup data-n=\"1909\">596</sup> וכ\"ש הנשמה ששרשה",[["1898","585","<b>דשכינה היא ניצוץ אלקי שבנפש</b>: בלקו\"ת כאן: ע' ע\"ח שמ\"א פ\"ג [במהדורת שקלאב תק\"ס — ובדפו\"א שמ\"ב, פ\"א]."],["1899","586","<b>בנפשו יביא לחמו</b>: פיוט (לימים נוראים) כי כשמך."],["1900","587","<b>ברבות מחשבות</b>: משלי יט, כא."],["1901","588","<b>מאן דקטיל לחויא</b>: ראה ת\"ז סתי\"ג כט, ב. תכ\"א מג, א. תז\"ח צט, ד."],["1902","589","<b>מלחמה להוי' בעמלק</b>: בשלח טז, יז."],["1903","590","<b>כי תצא למלחמה</b>: תצא כא, י."],["1904","591","<b>בע\"ח בשם הזהר</b>: שער נ' פרק ג' (צויין בתניא שם). זהר תצא דרע\"ז, א (צויין בע\"ח שם)."],["1905","592","<b>בנפש</b>: וכ\"ה בלקו\"ת. בהמשך הנדפס: שבנפש."],["1906","593","<b>אם יהי' נדחך</b>: נצבים ל, ד."],["1907","594","<b>שתהיינה. . הגילוי</b>: לשון לקו\"ת כאן לו, ב בשינויים והוספות."],["1908","595","<b>מזל הוא הנשמה שלמעלה מהגוף</b>: ראה שעה\"ק להרח\"ו ח\"ג, ש\"ה. לקו\"ת כאן לו, ריש ע\"ב. במדבר טז, א ואילך. האזינו עא, ד. שה\"ש טז, ד. מאמרי אדה\"א דברים ח\"ד ע' א'קסט ואילך. וש\"נ. וראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה עשה צדקה ומשפט על יד הערה 8 (מתו\"א תשא פו, ב)."],["1909","596","<b>שהרי המלאך בשליש העולם עומד</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. לעיל מאמר ד\"ה ואעשך לגוי גדול הערה 44."]]],[2000470253,"מפנימיות הכלים<sup data-n=\"1910\">597</sup>, אלא שעיקר הנשמה הוא למעלה, וע\"ז אמרו אע\"ג דאיהו לא חזי מזלי' חזי<sup data-n=\"1911\">598</sup>, רק הארתה מלובשת בגוף, ואיך ממשיך מבחי' המזל שאין מזל פי' בחי' אין הוא המזל<sup data-n=\"1912\">599</sup> כו' ע\"ז אמר דהע\"ה לךכו' בקשו פני<sup data-n=\"1913\">600</sup>, פי' פנימיות שלי היינו עצמיות פנימיות נקודת הלב ברעו\"ד שהוא בבחי' הסתר והעלם וצריך לבקש ולחפש אחרי' ולהוציאה מהעלם אל הגילוי.\n<b>והנה</b> להבין קצת מהו שרש ענין גילוי עצמיות נקודת הלב, דלכאו' אינו מובן כ\"כ ההפרש &lt;26&gt;\nּ מאחר שגם הארת נקודת הלב היא מבחי' סוכ\"ע כנ\"ל, וא\"כ מנלן לעשות מדרגות כ\"כ בנקודת הלב שבאדם בין עצמיות ובין הארה כו', אך הענין כמ\"ש הרמ\"ז ר\"פ משפטים דצ\"ד ע\"ב<sup data-n=\"1914\">601</sup> בשם ספר הגלגולים שיש ג' בחי' בנשמות א' היא נר\"נ מבחי' בי\"ע, ב' נר\"נ מבחי' אצי' שבפנימיות בי\"ע, ג' מסוד אצי' בעצמו. והנה חיצוני' הלב שהוא נלקח ונמשך מן הדעת וההתבוננות זהו בחי' הא' דהיינו נר\"נ דבי\"ע עצמן כי בינה מקננא בכורסי'<sup data-n=\"1915\">602</sup> שהוא עולם הבריאה כו', ועצמיות נקודת הלב אשר למעלה מעלה מטעם ודעת המושג זהו בחי' הג' שהוא אצי' עצמו כי אצי' בכלל הוא בחי' חכ'<sup data-n=\"1916\">603</sup> ומוחין דאבא הוא למעלה מהבינה והדעת, וז\"ע רובע ישראל שנת' במ\"א שהבחי' הרביעית היא בחי' אצי'<sup data-n=\"1917\">604</sup>. ומעתה מובן היסוד לעשות מדרגות בנקודת הלב שבאדם בין עצמיות נקודת הלב ממש שזהו בחי' גילוי והמשכה ממל' דאצי' העליון עצמה, ובין הארת נקודת הלב שהיא ג\"כ מבחי' אצי' אלא שזהו מהארת אצי' שבבי\"ע וכנ\"ל בחי' אצי' שבפנימיות העשי' או שבפנימיות יצי' ובריאה, שהוא הארה מאצי' העליון ולכן נק' הארת נקודת הלב, וע\"כ פעולת גילוי הארה זו הוא להפך לבושי מחדומ\"ע שהן הן מבחי' בי\"ע<sup data-n=\"1918\">605</sup> עצמן כנודע וע\"י הארת האצי' שבשרשן דהיינו בבי\"ע מהפכם, אבל להפך עצם השכל ומדות צ\"ל מפנימיות נקודת הלב עצמה שמבחי' אצי' העליון כו'. ומעתה מובן ג\"כ איך שנקודה זו דנקודת הלב ישנו בכאו\"א מישראל שהרי גם בנפש שמבחי' עשייה",[["1910","597","<b>הנשמה ששרשה מפנימיות הכלים</b>: ראה ע\"ח שער העיבורים שכ\"ח, פ\"א. לעיל המשך זאת חנוכת המזבח ובהערה 16."],["1911","598","<b>אע\"ג דאיהו. . מזלי' חזי</b>: מגילה ג, א."],["1912","599","<b>אין הוא המזל</b>: ראה אור תורה בלק מט, ג. שה\"ש סב, סע\"ב (לקו\"א סקל\"ז וסקע\"ב). לקו\"ת שמע\"צ פג, ב (האזינו עא, ד). סידור שחרית סז, א. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשנז. תקע\"א ע' לב. אוה\"ת שמע\"צ ס\"ע א'תתג ואילך. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו בהוספות ע' קפה. סה\"מ תרכ\"ו ע' קב. תרל\"ג ח\"א ע' רלט. ע' רמז. ע' שיא. ח\"ב ע' תק. תרל\"ו ריש ע' קצב. קונט' חנוך לנער ע' 48. המשך תער\"ב ח\"א ע' תטו. סה\"ש תשנ\"ב ח\"ב ע' 386 ואילך וע' 398."],["1913","600","<b>לך כו' בקשו פני</b>: תהלים כז, ח."],["1914","601","<b>הרמ\"ז. . דצ\"ב ע\"ב</b>: ד\"ה כד אתיליד יהבינן לי'. ראה גם המשך תער\"ב ח\"א ס\"ע שפז ואילך."],["1915","602","<b>בינה מקננא בכורסי'</b>: ת\"ז ת\"ו כג, א. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["1916","603","<b>אצי'. . חכ'</b>: ראה לקו\"ת תזריע כג, ב שמציין לע\"ח שמ\"ז, פ\"ג [ובדפו\"א פ\"ב]. ראה גם הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקי. לקמן פל\"א ובהערה 1002."],["1917","604","<b>רובע ישראל. . אצי'</b>: בלק כג, י. ראה גם לקו\"ת כאן לו, א."],["1918","605","<b>מחדומ\"ע. . בי\"ע</b>: ראה לקו\"ת בלק סז, א. סט, ד. תו\"ח בשלח ח\"א קמד, ב. וש\"נ. סה\"מ תרל\"ג ח\"ב ע' תא. וש\"נ."]]],[2000470254,"מלובש בפנימיותו אצי' ממש כנ\"ל וכמ\"ש בסש\"ב<sup data-n=\"1919\">606</sup>, וכמ\"ש במ\"א שיסוד אבא ארוך<sup data-n=\"1920\">607</sup> שהארת אבא נמשך ומתפשט בכ\"א מישראל<sup data-n=\"1921\">608</sup> גם במי שאין לו בינה ודעת כלל כו', והיינו אפי' בנפש דעשיי' שאין בו הארת הבינה ודעת.\n<b>ועוי\"ל</b> דעצמיות נקודת הלב ממש נמשך מבחי' כנס\"י ממש שהוא פרצוף הפנימי דמל' דאצי' והארת נקודת הלב נמשך מבחי' פרצוף החיצון כו', וזה קרוב ג\"כ לדרך הא'.\n<b>ועפ\"ז</b> יובן מה שקול מעורר הכוונה, דעם היות שע\"י שמחשב בהתבוננות יכול לבוא לבחי' אהוי\"ר אמנם זהו רק מבחי' חיצוני' הלב לבד אך קול הדבור מעורר הכוונה היינו בחי' הארת נקודת הלב, ואפשר גם בחי' פנימיות נקודת הלב, והיינו להיות כי שרשו מקדמות השכל, וזהו ג\"כ ענין ומתלמידי יותר מכולם כו'.\n<b></b>קיצור. שהאהבה בחי' הארת נקודת הלב היא מוסתרת וצריך להוציאה מהעלם אל הגילוי ועי\"ז מהפך מחדו\"מ, ובכדי להפך שכל ומדות זהו ע\"י בחי' עצמיות נקודת הלב דוקא, כי להלבושים שהם מבי\"ע די מבחי' הארת האצי' שבבי\"ע, אבל להפוך מוחין ומדות זהו ע\"י בחי' פנימיות נקודת הלב שהיא מאצי' העליון וזהו קול מעורר הכוונה כו'.",[["1919","606","<b>בסש\"ב</b>: פי\"ח."],["1920","607","<b>שיסוד אבא ארוך</b>: ראה ע\"ח שער הכללים פ\"י. מאמרי אדה\"א דברים ח\"ב ע' שעח. וש\"נ. תו\"ח תצוה ח\"ב של, א. וש\"נ."],["1921","608","<b>שיסוד אבא. . ומתפשט בכ\"א מישראל</b>: ראה ביאוה\"ז תשא נד, רע\"ד."]]],[2000470255,"<h3>[אל יתהלל החכם] ויובן כו' בינה יתירה</h3>\n<b>ל\"ג בעומר יום ה'</b>\n(ך) <b>ויובן</b> עוד ענין בינה יתירה<sup data-n=\"1922\">609</sup> ניתנה באשה יותר מבאיש<sup data-n=\"1923\">610</sup> מענין מעלת בחי' קלא דאשתמע<sup data-n=\"1924\">611</sup> שנת' בת\"א בסד\"ה וישב יעקב<sup data-n=\"1925\">612</sup>, דהנה ארז\"ל במד\"ר",[["1922","609","<b>ויובן. . בינה יתירה</b>: מכאן מתחיל מאמר הו' מהמשך מצה זו (הכולל פרקים כ-כא).\nפ\"כ — לשון אוה\"ת וישב ח\"ב ע' 526[ednref_101_א] בשינויים והוספות. לשון לקו\"ת בלק עב, רע\"ג (בשינוי קל — צויין אליו באוה\"ת כאן).\nפכ\"א — לשון אוה\"ת וישב ח\"ב ע' רסד[ednref_102_ב] בשינויים והוספות.\nהמאמר נזכר בסה\"מ תרמ\"ד ע' רכג ושם: וע' בד\"ה גן נעול (מ\"ם) פ' כ' כ\"א.\nהנחת[ednref_103_ג] כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן (בחלק הנחותיו) ושם הפתיחא: אל יתהלל החכם.\nבהכותרת המופיע בריש המאמר הנה התיבות: ”יום ה'\" ניתוספו מהנחת כ\"ק אדמו\"ר מהורש\"ב."],["1923","610","<b>בינה יתירה. . מבאיש</b>: ראה נדה מה, ב. ב\"ר רפי\"ח."],["1924","611","<b>קלא דאשתמע</b>: נסמן בסמוך בהערה 617."],["1925","612","<b>בת\"א בסד\"ה וישב יעקב</b>: כז, ב ד\"ה והנה כתיב.\n\n[edn_101_א] נדפס גם באוה\"ת וישב כרך ה ע' 1778 ואילך.\n\n[edn_102_ב] נדפס גם באוה\"ת וישב כרך ה ע' תתצה ואילך.\n\n[edn_103_ג] ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470256,"שמות<sup data-n=\"1926\">613</sup> ר\"פ ך\"א הנחיל יצחק לשני בניו, הנחיל הקול ליעקב<sup data-n=\"1927\">614</sup> והיינו מ\"ש<sup data-n=\"1928\">615</sup> הקל קול יעקב<sup data-n=\"1929\">616</sup>, שהם בחי' קלא דלא אשתמע וקלא דאשתמע<sup data-n=\"1930\">617</sup> &lt;27&gt;\nּ כנודע, והנוגע לענינינו הוא בחי' קלא דאשתמע, ובמד\"ר פ' בלק פ\"ך<sup data-n=\"1931\">618</sup> אמרו הפה ליעקב<sup data-n=\"1932\">619</sup> שנא' הקל קול יעקב, וצ\"ל ענין בחי' יעקב ע\"פ מה שנודע שיעקב הוא בחי' יו\"ד עקב כו', דהנה יעקב הוא נמשך מיסוד אבא המלובש בז\"א ובוקע ויוצא חוץ לז\"א<sup data-n=\"1933\">621</sup> ומזה נתהוה בחי' יעקב והוא נמשך ויורד בבי\"ע לברר בירורי נוגה בכל ששת ימי המעשה, וזהו פי' יעקב יו\"ד עקב שנמשך היו\"ד שהוא בחי' יסוד אבא לבחי' עקב דהיינו בי\"ע לברר בירורי נוגה, כי בחכמה אתברירו<sup data-n=\"1934\">622</sup> וע' בת\"א פ' וישלח<sup data-n=\"1935\">623</sup> ע\"פ ויאבק איש בענין כי לא יכול לו מפני שיעקב הוא הארת יסוד אבא כו' ע\"ש. ועוד מבואר במ\"א ע\"פ ויברך יעקב<sup data-n=\"1936\">624</sup> כי יעקב לא מת<sup data-n=\"1937\">625</sup> דהיינו שלא הי' בבחי' שבירה כלל ומשם יורד הכח הזה להעלות הניצוצי' כו', וענין זה כמ\"ש בע\"ח<sup data-n=\"1938\">626</sup> ובאוצ\"ח<sup data-n=\"1939\">627</sup> שיעקב נתקן מאחוריים דאבא שלא נפלו בבריאה ולכן לא נז' בהם מיתה כו', ובזה יתרון מעלתו אפי' על בחי' ז\"א שהוא כלליות ו\"ק דאצי' שבהן הי' שבה\"כ<sup data-n=\"1940\">628</sup>, והשתא א\"ש שהבירור הוא ע\"י יעקב כו'<sup data-n=\"1941\">620</sup>.\n<b>גם</b> יש להבין עפמ\"ש בזח\"א קמ\"ו סע\"ב קמ\"ז א' ע\"פ ויצא יעקב, ועמ\"ש בבה\"ז<sup data-n=\"1942\">629</sup> בענין יעקב יסוד אבא יוצא מבאר שבע יסוד אימא וילך חרנה במל' וגם בבי\"ע",[["1926","613","<b>שמות</b>: מכאן ואילך — לשון אוה\"ת וישב כאן בשינויים והוספות."],["1927","614","<b>הקול ליעקב</b>: וכ\"ה בסה\"מ תרל\"ב ח\"ב ע' תפו. ע' תצב. במדרש ובאוה\"ת וישב כאן תולדות ח\"א ע' 290: ליעקב הקול. וראה גם אוה\"ת חוקת ע' תשסד. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 6."],["1928","615","<b>והיינו מ\"ש</b>: במדרש ובאוה\"ת חוקת. בסה\"מ תרל\"ב שם ע' תפו: וכה\"א."],["1929","616","<b>הקל קול יעקב</b>: תולדות כז, כב."],["1930","617","<b>קלא דלא אשתמע וקלא דאשתמע</b>: ראה הנסמן באוה\"ת וישב כאן."],["1931","618","<b>פ\"ך</b>: סי\"ג."],["1932","619","<b>הפה ליעקב</b>: במדרש ובאוה\"ת וישב כאן: הפה נתן ליעקב."],["1933","621","<b>יעקב. . מיסוד אבא. . חוץ לז\"א</b>: ראה ע\"ח שער הארת המוחין זו\"ן של\"ב, פ\"א."],["1934","622","<b>בחכמה אתברירו</b>: ראה אגה\"ק סכ\"ח. זהר היכלות פקודי רנד, סע\"ב. ע\"ח שער דרושי נקודות ש\"ח, פ\"ו. לעיל המשך זאת חנוכת המזבח פכ\"ג הערה 657."],["1935","623","<b>בת\"א פ' וישלח</b>: כו, ג."],["1936","624","<b>ע\"פ ויברך יעקב</b>: ויגש מו, ז. ביאוה\"ז ויגש קלז, ב. ולהצ\"צ שם כרך ב ע' תשכז. ע' תשלא. [קיצור ב] אוה\"ת ויגש כרך ו ע' תתשיג."],["1937","625","<b>יעקב לא מת</b>: תענית ה, ב. ראה גם בענין יעקב לא מת (בנוסף להנ\"ל) או\"ת צ, ג. [נמצא גם ב] לקו\"א סקכ\"ז. סקצ\"ג. סרס\"ה. תו\"א יתרו עג, א. לקו\"ת חוקת סא, ד. ביאוה\"ז ויחי לה, ג. ולהצ\"צ שם כרך ב ע' תשדמ. תו\"ח נח סד, ד ובהערה 60. שע\"ת כד, ג ובהערה 40. אוה\"ת וישלח כרך ה ע' 1752. חנוכה כרך ב ס\"ע רפ. וארא ע' קנו. שבועות ע' קעג. חוקת ס\"ע תשפט. ע' תתט. ובכרך ה ע' תרלו. מטות ע' א'רצג (בשם הה\"מ). ובכרך ה ע' א'תרפג (בשם הה\"מ). עקב תקמה. סה\"מ תר\"ל ע' קנה. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 13."],["1938","626","<b>כמ\"ש בע\"ח</b>: ראה שם שער המלכים שי\"א, פ\"ח."],["1939","627","<b>כמ\"ש. . ובאוצ\"ח</b>: ראה שם שער המלכים פ\"ד."],["1940","628","<b>ז\"א. . שבהן הי' שבה\"כ</b>: ראה ע\"ח שער דרושי הנקודות ש\"ח, פ\"ב. מאמרי אדה\"א דברים ח\"א ע' ח. וש\"נ."],["1941","620","<b>דהנה. . כו'</b>: לשון לקו\"ת בלק עב, רע\"ג (בשינוי קל — צויין אליו באוה\"ת כאן)."],["1942","629","<b>בבה\"ז</b>: ויצא טז. ג ואילך. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערות 22. 21."]]],[2000470257,"כו', וע\"ש שממשיך ג\"כ מהכתר, וז\"ע שמבריח מן הקצה אל הקצה וכמ\"ש בזח\"ב קע\"ה ב'.\n<b>והנה</b> רבינו ז\"ל א' בד\"ה וישב יעקב הנ\"ל שיש בחי' יעקב בכל עולם ועולם לפי ערכו, א\"כ י\"ל שיש בחי' יעקב גם למעלה מאצי' שגם למעלה מאצי' שייך לומר בחי' יעקב יו\"ד עקב, וכמ\"ש בלק\"ת בפ' ויצא<sup data-n=\"1943\">630</sup> גבי והכשבים הפריד יעקב<sup data-n=\"1944\">631</sup>, ועוד שהרי בחי' ועמדו רגליו<sup data-n=\"1945\">632</sup> איתא בע\"ח הובא בהרמ\"ז<sup data-n=\"1946\">633</sup> תולדות קל\"ה<sup data-n=\"1947\">634</sup> דהיינו שני עקבי א\"ק א\"כ גם שם שייך ההמשכה מבחי' יו\"ד ח\"ע שהוא חכמה דא\"ק לבחי' עקב בשגם כי רגלי א\"ק מסתיימי' בתחתית העשיי'<sup data-n=\"1948\">635</sup>, וגם נכלל בפי' בכל עולם ועולם לפי ערכו היינו גם בבי\"ע וכדפי' רשב\"י בפ' ויצא שם בענין וילך חרנה<sup data-n=\"1949\">636</sup> וכנ\"ל, ועמ\"ש<sup data-n=\"1950\">637</sup> בלק\"ת בד\"ה ענין משמח חתן<sup data-n=\"1951\">638</sup> יעקב אותיות יבקע<sup data-n=\"1952\">639</sup>, אז יבקע כשחר אורך<sup data-n=\"1953\">640</sup>, וע' מזה בזח\"ג ק\"ד א', ובזהר\"ק<sup data-n=\"1954\">641</sup> שם פי' ויעקב שהוא ת\"ת ממשיך לו שפע מא\"א דז\"א בעתיקא<sup data-n=\"1955\">642</sup> אחיד ותליא כנז' באד\"ר<sup data-n=\"1956\">643</sup> ואומר אז יבקע כשחר<sup data-n=\"1957\">644</sup>, יבקע אותיות יעקב בסוד בקיעת האורות, וארוכתך דהיינו הארת א\"א שנק' אריך דאסי' לכל מרעין וכאיבין<sup data-n=\"1958\">645</sup>, וע' מענין אז יבקע בקיעת האורות בסידור שער הסוכות<sup data-n=\"1959\">646</sup> על המאמר הנ\"ל, ועמ\"ש סוף הביאור שע\"פ מי מנה<sup data-n=\"1960\">647</sup> עפר יעקב, כי שרשו של יעקב גבוה מז\"א הנק' ישראל כי הוא נמשך מיסוד אבא ממש שלמעלה מז\"א רק שנשפל ונמשך למטה מז\"א, וזהו פי' יו\"ד עקב עכ\"ל. וי\"ל ע\"ז כמשל הראי' שנמשך למטה מהשמיעה כמ\"ש במ\"א ע\"פ הראני את מראיך<sup data-n=\"1961\">648</sup>.\n<b></b>קיצור. הנחיל את הקול, יעקב יו\"ד יסוד אבא נמשך בעקב מל' וגם בבי\"ע וכן יש יעקב ז\"ת דע\"י, וכן בא\"ק, וענין אז יבקע, ויש ביעקב בחי' שלמעלה מישראל כמ\"ש ע\"פ מי מנה עפר יעקב.",[["1943","630","<b>בלק\"ת פ' ויצא</b>: להאריז\"ל בסופו."],["1944","631","<b>והכשבים הפריד יעקב</b>: ויצא ל, מ."],["1945","632","<b>ועמדו רגליו</b>: זכרי' יד, ד."],["1946","633","<b>בע\"ח הובא בהרמ\"ז</b>: כ\"ה גם באוה\"ת כאן. ברמ\"ז שם: בא\"י [ באדם ישר]."],["1947","634","<b>בהרמ\"ז תולדות קל\"ה</b>: ע\"א ד\"ה ודע שבהוד דעתיק."],["1948","635","<b>רגלי א\"ק. . העשיי'</b>: ראה ע\"ח דרוש עגו\"י ש\"א ענף ד. מאמרי אדה\"א ויקרא ח\"א ע' טו. וש\"נ. לקמן ספנ\"ו."],["1949","636","<b>רשב\"י. . חרנה</b>: ראה ביאוה\"ז שם יז, ד."],["1950","637","<b>ועמ\"ש</b>: השווה אוה\"ת במדבר ע' מד[ednref_104_ד]. ביאוה\"ז כרך ב ע' תשדמ."],["1951","638","<b>בלק\"ת בד\"ה ענין משמח חתן</b>: צו ח, סע\"ד [ושם הד\"ה הוא: להבין ענין משמח חתן]."],["1952","639","<b>יעקב אותיות יבקע</b>: נסמן לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת הא' הערה 21."],["1953","640","<b>אז יבקע כשחר אורך</b>: ישעי' נח, ח."],["1954","641","<b>ובזהר\"ק</b>: באוה\"ת במדבר [שבהערה 637]: ובזוהר. וכנשצ\"ל כבפנים."],["1955","642","<b>בעתיקא</b>: בזהר\"ק: בע\"ק."],["1956","643","<b>באד\"ר</b>: כ\"ה בזהר\"ק באוה\"ת כאן בהמובא בהערה 637. ראה לעיל הערה 543."],["1957","644","<b>כשחר</b>: בזהר\"ק ניתוסף: אורך וגו'. באוה\"ת במדבר ניתוסף: אורך כו'."],["1958","645","<b>וכאיבין</b>: בזהר\"ק: וכאבים כנז' באדר\"ז."],["1959","646","<b>בסידור שער הסוכות</b>: רנז, ד ואילך."],["1960","647","<b>ועמ\"ש. . מי מנה</b>: לקו\"ת בלק ע, ב (בשינוי קל)."],["1961","648","<b>כמ\"ש. . הראני את מראיך</b>: שה\"ש ב, יד. ראה מאמרי אדה\"ז תקס\"ט ע' פט ואילך. ע' קא.\n\n[edn_104_ד] במהדורת תשנ\"ה ס\"ע מג ואילך."]]],[2000470258,"&lt;28&gt;\nּ (ךא) והנה<sup data-n=\"1962\">649</sup> בחי' קלא דאשתמע הוא בחי' התורה כן ביאר בזח\"א ד\"ן ע\"ב, והיינו כי בענין הנסתרות להוי' אלקינו והנגלות לנו<sup data-n=\"1963\">650</sup> פי' דאו\"א נק' הנסתרות עלמא דאתכסיא, ובחי' זו\"נ זהו ו\"ה נק' נגלות וזהו והנגלות ו\"ה נגלות, ועיקר הגילוי הוא ע\"י שנמשך הקול בדבור שהוא מל' עלמא דאתגלי'<sup data-n=\"1964\">651</sup> ומקור דבי\"ע, ולכן נא' ויאהב יעקב את רחל<sup data-n=\"1965\">652</sup> כדי להמשיך גילוי אור א\"ס ב\"ה, כנז' בזח\"א ויצא קנ\"ד ב', וע' בזח\"ב וארא דך\"ה סע\"ב מענין התחברות קול ודבור ע\"י עסק התורה, ודך\"ו א' ובפי' הרמ\"ז שם, וד\"ג ע\"א גבי קול אמר לדבור אתי, ונת'<sup data-n=\"1966\">653</sup> מזה במ\"א בדרוש מחצית השקל<sup data-n=\"1967\">654</sup>, ועמ\"ש בד\"ה כה אמר ה' אל יתהלל החכם<sup data-n=\"1968\">655</sup> כו' כ\"א בזאת יתהלל כו' ותוכן הענין דיש בחכ' ב' בחי', א' בחי' החכמה בעצמה, ב' בחי' כח התפשטותה למטה לברר בירורים, ובחי' זו הב' שרשה נמשך ממקום עליון יותר וכמו ענין הכח דוידבר<sup data-n=\"1969\">656</sup> שלמה שלשת אלפים<sup data-n=\"1970\">658</sup> משל<sup data-n=\"1971\">657</sup> כו', לפ\"ז יש מעלה יתירה בבחי' ו\"ד דמילוי יו\"ד שהם שרש קלא דאשתמע ודבור שכח ההתפשטות זו להמשיך האור למטה צ\"ל נמשך ממקום עליון, ועמ\"ש כה\"ג בענין לך לך מארצך<sup data-n=\"1972\">659</sup>, ועמ\"ש בביאור ע\"פ ועתה יגדל נא<sup data-n=\"1973\">661</sup> כח אד', כח הוא מילוי המילוי שבחי' זו נמשך מבחי' גבוה יותר כו', ובד\"ת נאמר הרחב פיך ואמלאהו<sup data-n=\"1974\">662</sup>, ואפ\"ל<sup data-n=\"1975\">660</sup>",[["1962","649","<b>והנה</b>: לשון אוה\"ת וישב ח\"ב ע' רסדב בשינויים והוספות."],["1963","650","<b>הנסתרות להוי' אלקינו והנגלות לנו</b>: נצבים כט, כח. ראה ת\"ז ת\"ע קכט, א. לקו\"ת פקודי ג, ב ובהנסמן במ\"מ לשם."],["1964","651","<b>עלמא דאתכסיא. . עלמא דאתגלי'</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. תניא פכ\"ו."],["1965","652","<b>ויאהב יעקב את רחל</b>: ויצא כט, יח."],["1966","653","<b>אתי ונת'</b>: וכ\"ה גם בהמשך הנדפס. באוה\"ת כאן: ”אתי כו' ובמק\"מ שם בשם נ\"ב[ednref_105_ה] מהרח\"ו[ednref_106_ו] ששרשן מן ו\"ד דמילוי יו\"ד ונת'\". ולכאורה תיבות אלו נשמטו כאן בשגגת המעתיק — שע\"ז קאי ציון הבא בפנים. וכן ההמשך שבא לאח\"ז."],["1967","654","<b>בדרוש מחצית השקל</b>: ביאוה\"ז תשא נב, סע\"ד ואילך."],["1968","655","<b>בד\"ה כה אמר ה' אל יתהלל החכם</b>: ירמי' ט, כב. ראה מאמרי אדה\"ז הנחות הר\"פ ע' עט. תקס\"ח ח\"א ס\"ע מב ואילך. ח\"ב ס\"ע תשכו ואילך. אוה\"ת ויצא רז, ב. ירמי' כרך ב ע' תתעח (ס\"ג). ע' תתפ. — והפתיחה היא אל יתהלל."],["1969","656","<b>דוידבר שלמה</b>: מל\"א ה, יב [בהוספת תיבת: שלמה — באוה\"ת וישב כאן ליתא — ראה מאמרי אדה\"א בראשית ע' קלב. וש\"נ. תו\"ח וישב רו, ב. בשלח ח\"א רכד, ג. סה\"מ תרל\"ח ע' תסא]."],["1970","658","<b>דוידבר שלמה שלשת אלפים משל</b>: ראה תו\"ח לך פא, ד ובהערה 31. וארא ח\"א פג, ב. וש\"נ. סה\"מ תרל\"ח ע' רכח. וש\"נ."],["1971","657","<b>דוידבר שלמה שלשת אלפים משל</b>: כתוב זה [בהשמטת תיבת שלמה] הובא במאמרי אדה\"ז הנחות הר\"פ שם."],["1972","659","<b>בענין לך לך מארצך</b>: ראה תו\"א לך יא, ב ואילך."],["1973","661","<b>בביאור ע\"פ ועתה יגדל נא</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תקצה ואילך (ב' הנוסחאות). אוה\"ת שלח ע' תקב ואילך."],["1974","662","<b>הרחב פיך ואמלאהו</b>: תהלים פא, יא. ברכות נ, א."],["1975","660","<b>מארצך. . ואפ\"ל</b>: באוה\"ת וישב כאן כרך ה ע' תתצה: כו'. אבל מובא באוה\"ת וישב כאן כרך ב ע' רסד.\n\n[edn_105_ה] <b>ושם ד\"ה דעיקרא דתרווייהו מלבנון קא אתיין</b>: נ\"ב מטיפת אבא ור\"ל זו\"ן שרשה הראשון מטיפת אבא בסוד ו\"ד דיו\"ד.\n\n[edn_106_ו] <b>בהגהות מהרח\"ו שנדפסו על גליון הזהר כותב</b>: מטיפת אבא."]]],[2000470259,"קלא דלא אשתמע שרשו ממו\"ס וז\"א שרשו מעתיקא גלגלתא דא\"א כמו ראי' לגבי שמיעה וכנ\"ל, כך קלא דאשתמע לגבי קלא דלא אשתמע כו'.\n<b>והנה</b> כמו הקול המחבר וממשיך מצפוני כוונת הלב לבוא לידי גילוי בדבור, כך התורה היא בחי' קול והמשכה של יעקב יו\"ד עקב דהיינו מבחי' יו\"ד שהוא חכמה עילאה עד עקב והוא עשייה, וז\"ש בזח\"א ד\"ן ע\"ב וקול דיעקב דאיהו אורייתא כו' אחיד בההוא<sup data-n=\"1976\">663</sup> פנימאה דלא אשתמע ואחיד בההיא<sup data-n=\"1977\">664</sup> דלבר דאשתמע, תרין אלין<sup data-n=\"1978\">665</sup> דלא אשתמעו ותרין אלין דאשתמעו, תרין דלא אשתמעון דא הוא חכ' עילאה סתימאה דקיימא במחשבה דלא אתגלייא, והיינו ח\"ס כשנמשך ממנה בח\"ע דאצי' שנק' מחשבה דלא אתגליא וז\"ע היו\"ד דש' הוי' ואח\"כ נמשך משם קול דלא אשתמע והיא בינה שנק' קול דממה דקה<sup data-n=\"1979\">666</sup> כמ\"ש בזח\"ג ד\"ל ע\"ב ודקצ\"ג ע\"ב<sup data-n=\"1980\">667</sup>, ואח\"כ תרין דאשתמעו קול דיעקב ודבור דאתאחיד בהדי', נמצא קול התורה ממשיך מחו\"ב עילאין שבהם מלובש אור דמו\"ס לידי גילוי בבחי' דבור שהוא מל' מקור דבי\"ע, וז\"ש כאן והוא בחי' קול כו' מבחי' יו\"ד כו' עד עקב, ועפ\"ז יובן ענין בינה יתירה ניתנה באשה שדוקא ע\"י קול הדבור נמשך מבחי' הגבוה יותר כו'.\n<b></b>קיצור. ענין קלא דאשתמע, זו\"נ נק' והנגלות, והיינו ע\"י קול ודבור ושרשן ו\"ד דמילוי יו\"ד, ויש בחי' בהמילוי שלמעלה מעצם היו\"ד, אל יתהלל כו' כ\"א בזאת, וקול זה מחבר כח\"ב להמשיכו במל' דבור כו'.",[["1976","663","<b>בההוא</b>: בזהר: בהאי."],["1977","664","<b>בההיא</b>: בזהר ובאוה\"ת כאן: בהאי."],["1978","665","<b>אלין</b>: כ\"ה גם באוה\"ת וישב כאן כרך ה ריש ע' 1790. בזהר אוה\"ת וישב כאן כרך ב ע' רסד (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן בסופו: אינון."],["1979","666","<b>קול דממה דקה</b>: מל\"א יט, יב."],["1980","667","<b>ודקצ\"ג ע\"ב</b>: באוה\"ת וישב כאן כרך ב: ודקצ\"ב ע\"ב. וצ\"ל כבפנים. וכ\"ה גם באוה\"ת וישב כאן כרך ה."]]],[2000470260,"<h3>ויובן כו' בינה יתירה כו' חכמות בחוץ</h3>\n<b>פ' אמור</b>\n&lt;29&gt;\nּ <b>(ךב)</b> ויובן<sup data-n=\"1981\">668</sup> עוד ענין בינה יתירה ניתנה באשה יותר מבאיש, דהנה כתי' חכמות בחוץ תרונה<sup data-n=\"1982\">669</sup>, ופי' בזהר חכמות תרין חכמה עילאה וחכ' תתאה, פי' ח\"ע הוא בחי' חכים ולא בחכ' ידיעא, וחכ' תתאה הוא כמארז\"ל נובלות",[["1981","668","<b>ויובן. . בינה יתרה. . חכמות בחוץ</b>: מכאן מתחיל מאמר הז' מהמשך מצה זו (הכולל פרקים כב-כד).\nפכ\"ב — לשון תו\"א יתרו ע, א-ב בשינויים והוספות. (חלק נעתק גם בסה\"מ תרל\"ד ע' סט ואילך. תרנ\"ד ע' עו (עם הוספות). ראה מאמרי אדה\"ז תקס\"ט ע' לו ואילך. תו\"ח יתרו ח\"ב רסו, ד ואילך.\nפכ\"ד — לשון התו\"א לך יא, ג בשינויים והוספות. לשון התו\"א מג\"א צ, ד ואילך בשינויים והוספות. לשון אוה\"ת שה\"ש כאן ס\"ע תלה ואילך בשינויים."],["1982","669","<b>חכמות בחוץ תרונה</b>: משלי א, כ. ראה זהר תולדות קמא, ב."]]],[2000470261,"חכ' שלמעלה תורה<sup data-n=\"1983\">670</sup>, פי' הנובלות הוא בחי' אור ושפע מבחי' אור החכ' הנמשך למטה כדי לברר בירורים, והיינו בחי' חכ' שבתורה שנתלבשה בדברים גשמיים להבדיל בין טמא לטהור<sup data-n=\"1984\">671</sup> וכיוצא בזה בכל מל\"ת. וכמו\"כ גם במעשה המצות עשה הרי נתלבשה החכמה במצות גשמיים כמו מצות ציצית בצמר הגשמי דטלית וציצית הגשמיים, ולמעלה הטלית הוא בחי' אור מקיף וכמ\"ש לבושי' כתלג חיור<sup data-n=\"1985\">672</sup> שהוא בחי' סוכ\"ע והחוטין הם ל\"ב נתיבות החכ'<sup data-n=\"1986\">673</sup>, ועד\"ז בשאר המצות כמו אבני האפוד<sup data-n=\"1987\">674</sup> והחשן<sup data-n=\"1988\">675</sup> תרשיש ושוהם וישפה<sup data-n=\"1989\">676</sup> שהם אבנים גשמיים ונחקק בהם שמות י\"ב השבטים, וכתי' ונשא אותם אהרן לפני ה' לזכרון<sup data-n=\"1990\">677</sup>, ולמעלה רומזים לבחי' אורות עליונים שממשיך אהרן כהנא רבא בחי' חסדים עליונים שלפני האצי', ולמטה נתלבשה חכמה זו באבנים גשמיים ובמעשה גשמיות דחשן ואפוד, וכה\"ג יובן בכל מעשה המצות, וע\"כ נק' חכ' זו שנתלבשה למטה במעשה המצות בשם חכ' תתאה שמתלבשת בעשייה גשמיות לאהפכא חשוכא לנהורא כו', וזהו חכמות בחוץ תרונה, בחוץ דוקא כשנתלבשה ח\"ת הנמשכת מח\"ע וזהו חכמות בחוץ, שהארת ח\"ע נמשכת בח\"ת ומתלבשת בחוץ דהיינו בבי\"ע עד שנמשכים בעשייה גשמיות במעשה המצות שלפנינו אז דוקא תרונה פי' שיהי' עי\"ז תוס' וגילוי אוא\"ס ב\"ה שלמעלה מעלה אפי' מבחי' ח\"ע, וע\"י מעשה המצות יומשך ויתגלה בח\"ע, נמצא דוקא ע\"י התלבשות החכמות בחוץ אז דוקא תרונה כו'.\n<b>וביאור</b> הדבר הוא, דהנה כתי' ראשית חכמה<sup data-n=\"1991\">678</sup>, והיינו בחי' חכמה עילאה שנק' ראשית, כי ח\"ת<sup data-n=\"1992\">679</sup> נק' סופא דכל דרגין כנודע שהיא בחי' מל'<sup data-n=\"1993\">680</sup>, וח\"ע נק' ראשית, והנה ראשית בתי\"ו מורה על לשון נקבה, כי ראש הוא לשון דכר, וראשית הוא לשון נוקבא<sup data-n=\"1994\">681</sup>, והיינו כי החכמה היא בחי' מקבל שמקבלת מבחי' ראש, וכמ\"ש והחכ' מאין תמצא<sup data-n=\"1995\">682</sup> שנמשכת מבחי' אין דהיינו שלא בדרך השתלשלות",[["1983","670","<b>נובלות חכ' שלמעלה תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["1984","671","<b>להבדיל בין טמא לטהור</b>: ע\"פ שמיני יא, מז. ראה גם סה\"מ תרנ\"ד כאן ע' עו."],["1985","672","<b>לבושי' כתלג חיור</b>: דניאל ז, ט."],["1986","673","<b>והחוטין הם ל\"ב נתיבות החכ'</b>: ראה זח\"ג תוספת שא, א. בחיי שלח טו, לח ד\"ה וע\"ד הקבלה (ירושלים תשל\"ב ס\"ע קא). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקטז ובהנסמן במ\"מ לשם. לקו\"ת קרח נב, ב. ד."],["1987","674","<b>אבני האפוד. . ושוהם</b>: תצוה כח, ט."],["1988","675","<b>אבני. . והחשן תרשיש ושוהם וישפה</b>: תצוה שם, כ."],["1989","676","<b>וישפה</b>: כ\"ה גם במאמרי אדה\"ז תקס\"ט כאן ריש ע' לז. בתו\"א וסה\"מ תרל\"ד ליתא."],["1990","677","<b>ונשא אותם אהרן לפני ה' לזכרון</b>: כ\"ה גם בתו\"א וסה\"מ תרל\"ד. במאמרי אדה\"ז תקס\"ט כאן: ה' כו' לזכרון. ראה תצוה שם, יב [ונשא אהרן את שמותם לפני ה'. . לזכרון]. כט [ונשא אהרן את שמות בנ\"י. . לזכרון לפני ה']."],["1991","678","<b>ראשית חכמה</b>: תהלים קיא, י."],["1992","679","<b>ח\"ת. . מל'</b>: ראה לקוטי הש\"ס להאריז\"ל חולין כ, ב ד\"ה לכי."],["1993","680","<b>סופא דכל דרגין. . בחי' מל'</b>: ראה זהר בשלח נו, א. פקודי רכו, סע\"א."],["1994","681","<b>ראש. . דכר וראשית. . נוקבא</b>: ראה גם (בנוסף לתו\"א מאמרי אדה\"ז תקס\"ט תו\"ח יתרו ח\"ב כאן רסז, רע\"ג). סה\"מ תרכ\"ט ע' קמז. המשך תער\"ב ח\"ג ע' א'תז. וראה גם מאמרי אדה\"א קונטרסים ע' שיב."],["1995","682","<b>והחכ' מאין תמצא</b>: איוב כח, יב. ראה גם (בנוסף לתו\"א ומאמרי אדה\"ז תקס\"ט) מאמרי אדה\"א בראשית ס\"ע רלח. קונטרסים ע' תכה ואילך. לקמן הערה 685. לקמן ספ\"ל."]]],[2000470262,"עילה ועלול<sup data-n=\"1996\">683</sup> רק כמו בחי' יש מאין, כי בחי' האין שממנו תמצא החכ' הוא למעלה ממדריגת החכ' והוא כמו<sup data-n=\"1997\">684</sup> עד\"מ באדם כשנופל לו איזה המצאה וסברא חדשה אזי מתמלא תענוג, ומזה אנו רואים שבחי' תענוג הוא למעלה מבחי' חכמה דהיינו שהוא מקור החכמה<sup data-n=\"1998\">685</sup> ולכן בתחלת התחדשות הסברא יהי' הענג גדול להיות כי רגע זו יצאה ונמשכה החכ' ממקורה התענוג, לכן מאיר בה אור התענוג, משא\"כ כשמתיישן אח\"כ אינו מתענג כ\"כ מהסברא שכבר נתרחקה ממקורה שהוא התענוג, וכמו\"כ למעלה בחי' תענוג העליון הוא מקור החכמה, וזהו מאין תמצא, מאין הוא בחי' ענג, וזהו שנק' חכמה ראשית שהוא בחי' מקבל מבחי' ראש הוא &lt;30&gt;\nּ התענוג עליון שנק' ראש אותיות אשר<sup data-n=\"1999\">686</sup> שהוא לשון אושר ותענוג<sup data-n=\"2000\">687</sup> וכמו באשרי כי אשרוני בנות<sup data-n=\"2001\">688</sup>, אשרי יושבי<sup data-n=\"2002\">689</sup> כו'.\n<b>והנה</b> בברכת המצות אנו מברכים אשר קב\"ו, שע\"י המצה אנו ממשיכים מבחי' אשר שהוא בחי' ענג העליון, וההמשכה היא בח\"ע וח\"ת שהם בחי' יחו\"ע ויחו\"ת<sup data-n=\"2003\">690</sup> שנמשך בהם מבחי' ענג העליון, וזהו פי' הברכה בא\"י אלקינו הוא בחי' יחו\"ע דחו\"ב דאצי', ואח\"כ מלך העולם הוא בחי' יחו\"ת, וממשיכים להם מבחי' אשר בחי' ענג העליון והוא ע\"י שקדשנו במצותיו דהיינו ע\"י קיום מעשה המצות הגשמיי' בבחי' אתכפי' ואתהפכא לברר בירורי נוגה, שעי\"ז דוקא ממשיכים גילוי התענוג העליון, וזהו חכמות כשנתלבשו בחוץ דוקא אזי תרונה מחמת גילוי התענוג עליון בחכמה כו', ונמצא מובן כי בינה יתירה ניתנה באשה בחי' ח\"ת שעם היות שזהו הארה מבחי' ח\"ע עכ\"ז עי\"ז נמשך תוס' אור בח\"ע שהרי עי\"ז דוקא תרונה כו'.\n<b></b>קיצור. חכמות תרין ח\"ע וח\"ת, חכ' תתאה היא הארת ח\"ע שנתלבשה במעהמ\"צ לברר בירורי נוגה ועי\"ז תרונה, כי ח\"ע דאצי' היא ראשית שמקבל מראש אותיות אשר, ובברכת המצות מברכים אשר בחי' תענוג שנמשך בחו\"ב יחו\"ע ויחו\"ת כו', ונמצא כי בינה יתירה באשה דוקא יותר מבאיש כו'.\n(ךג) <b>והנה</b> בזח\"א קמ\"א ב' ע\"פ חכמות בחוץ תרונה, ת\"ח חכמה עילאה איהי סתימא דכל סתימין, ויש לפרש דמיירי בח\"ס ובחכ' דאצי'<sup data-n=\"2004\">691</sup> ע' מק\"מ",[["1996","683","<b>עילה ועלול</b>: ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו. לקו\"ת ברכה צה, ב (הנזכר בספרים). שה\"ש א, ב (כמ\"ש בספרים)."],["1997","684","<b>כמו</b>: בהמשך הנדפס ליתא. בתו\"א כבפנים."],["1998","685","<b>תענוג. . מקור החכמה</b>: ראה גם (בנוסף לתו\"א מאמרי אדה\"ז תקס\"ט תו\"ח יתרו ח\"ב כאן רסז, ג). שע\"ת קכז, א ובהערה 1. מאמרי אדה\"א שמות ח\"ב ע' תנד. פלח הרמון בחוקותי ע' תצג. וש\"נ. לעיל הערה 682."],["1999","686","<b>ראש אותיות אשר</b>: ראה זהר בראשית טו, סע\"א. ע\"ח שער הולדת או\"א וזו\"ן שט\"ז, פ\"ב. (בנוסף לתו\"א מאמרי אדה\"ז תקס\"ט תו\"ח) מאמרי אדה\"א הנחות תקע\"ז ע' ה. וש\"נ."],["2000","687","<b>אשר שהוא לשון אושר ותענוג</b>: ראה גם לעיל המשך זאת חנוכת פי\"א ובהערה 211."],["2001","688","<b>באשרי כי אשרוני בנות</b>: ויצא ל, יג. נסמן לעיל שם הערה 212."],["2002","689","<b>אשרי יושבי</b>: תהלים פד, ה."],["2003","690","<b>יחו\"ע ויחו\"ת</b>: זהר בהקדמה יב, א."],["2004","691","<b>דמיירי בח\"ס ובחכ' דאצי'</b>: ראה גם לעיל המשך זאת חנוכת המזבח פכ\"ב ובהערה 632."]]],[2000470263,"שם, והיינו כמ\"ש בד\"ן הנ\"ל ח\"ע סתימאה דקיימי<sup data-n=\"2005\">692</sup> במחשבה כו' וכנ\"ל, וכד אתפשטת לאנהרא ואתנהרא<sup data-n=\"2006\">693</sup> ברזא דעלמא דאתי כו', וכולא בחשאי דלא אשתמע לבר, וכמ\"ש במ\"א בענין לויתן ושור הבר<sup data-n=\"2007\">694</sup>, לויתן נשמות דאצי' הנמשכים מיחוד או\"א, אכן שור הבר נשמות הנמשכי' מיחוד זו\"נ שהן בבריאה וכמ\"ש בזח\"ג ע\"ח ע\"א גבי מולדת בית או מולדת חוץ, מאתר דז\"א אשתכיח<sup data-n=\"2008\">695</sup> כו' שנק' לבר ולחוץ, לפי שהמדות והדבור הם הגילוי לזולתו דהיינו לבי\"ע כו', תו בעיא לאתפשטא כו' ואתעביד חד קלא דנפקא לבר ואשתמע כדין מתמן ולהלן איהו חוץ, מכאן בעי בר נש לאתקנא בעבידתיה, כי כמו זו\"נ יורדים בבי\"ע לברר בירורים כן באדם בחי' עבודה ולעבדו בכל לבבכם<sup data-n=\"2009\">696</sup> היינו הבירורים שמתעלים ע\"י התפלה, וכן ענין התשובה כמ\"ש בד\"ה מי יתנך<sup data-n=\"2010\">697</sup>, בענין אמצאך בחוץ שקאי על בעלי תשובה, וכן יש לפרש זה על התורה כמ\"ש בת\"א בד\"ה קול דודי שבפ' שמות<sup data-n=\"2011\">698</sup> גבי ובכל עבודה בשדה כו' ברייתא לבר מגופא, וע\"ש שאילפא ששמו מוכח עליו מל' אאלפך חכ'<sup data-n=\"2012\">699</sup> הי' יכול לפשוט דיני הברייתא ממתניתין, וכמו שא' מי איכא מידי בברייתא<sup data-n=\"2013\">700</sup> דלא\n&lt;31&gt;\nּ פשיטנא לי' ממתניתין כו', אבל אנו מוכרחים ללמוד הברייתות שהם לבר מגופא, כמו שבענין צמיחת התבואה מוכרחי' להוביל התבואות לזורעם בשדה שהם מחוץ לעיר כו', וז\"ע הבירורי' שמתבררים ע\"י בחי' התורה מבחי' חוץ כו', והיינו ע\"י הברייתא שנק' לבר מגופא כו'.\n<b>ויובן</b> עוד ענין קלא פנימאה וקלא דנפקא לבר ע\"ד שנז' בלק\"ת בד\"ה כי תשמע בקול<sup data-n=\"2014\">701</sup> בענין מפתחות הפנימיות ומפתחות החיצוני', דמפתחות החיצוני' הו\"ע מלכותו ית' שהיא מל' כל עולמים שנק' חיצוני' זיו והארה, ומפתחות הפנימיות היא ההמשכה מאוא\"ס הנמשך ומאיר בח\"ע כו', וכמו\"כ יובן עד\"ז ענין קלא פנימאה קול היינו ההמשכה<sup data-n=\"2015\">702</sup> להיות חו\"ב קדש מלה בגרמה<sup data-n=\"2016\">703</sup> כו', וקלא דנפקא לבר הוא ההמשכה בהמדות והדבור, וכה\"ג נת' בענין לבבתיני<sup data-n=\"2017\">704</sup> ובד\"ה שה\"ש<sup data-n=\"2018\">705</sup> בענין ב'",[["2005","692","<b>דקיימי</b>: בזהר קאפוסט תקס\"ט: דקיימ' [ דקיימא]."],["2006","693","<b>לאנהרא ואתנהרא</b>: בזהר: לאתנהרא אתנהרא."],["2007","694","<b>לויתן ושור הבר</b>: ראה לקו\"ת שמיני יח, ד ואילך."],["2008","695","<b>אשתכיח</b>: בזהר: אשתכח."],["2009","696","<b>ולעבדו בכל לבבכם</b>: עקב יא, יג."],["2010","697","<b>בד\"ה מי יתנך</b>: לקו\"ת שה\"ש מד, ד."],["2011","698","<b>בת\"א. . שבפ' שמות</b>: נא, ג."],["2012","699","<b>אאלפך חכ'</b>: איוב לג, לג [ושם: ואאלפך]."],["2013","700","<b>מי איכא מידי בברייתא</b>: כ\"ה בכ\"מ בדא\"ח ומהם: לקו\"ת שה\"ש מא, ב. ספר המצות להצ\"צ ס\"ע קע [ושם: תענית י\"ט!]. אוה\"ת ענינים ע' רנו. סה\"מ תרכ\"ז ע' עט. ע' שב (ומציין: תענית דכ\"א, א'). המשך תער\"ב ח\"ב ע' תתכז. ח\"ג ע' א'שעא. סה\"מ מלוקט ג' ע' קסג הערה 7. וראה תו\"א כאן. לקו\"ת ויקרא בהוספות נג, ג."],["2014","701","<b>בלק\"ת בד\"ה כי תשמע בקול</b>: פ' ראה כג, א ואילך."],["2015","702","<b>קול היינו ההמשכה</b>: ראה גם תו\"א וישב כז, ב. יתרו סט, ב. ויקהל פז, א. ב. סה\"מ תרל\"ח ע' קמו. וש\"נ."],["2016","703","<b>קדש מלה בגרמה</b>: זהר אמור צד, ב. ראה גם לקמן פ\"ל."],["2017","704","<b>בענין לבבתיני</b>: ראה לקו\"ת שה\"ש כט, ב ואילך. לא, א."],["2018","705","<b>ובד\"ה שה\"ש</b>: ראה לקו\"ת שם ב, סע\"ג ואילך."]]],[2000470264,"בחי' חתן כו', אך א\"א לומר דהתורה הוא מפתחות החיצוני', דבאמת התורה היא בחי' מפתחות הפנימיות, אלא שי\"ל דהיינו שנמשך מבחי' מפתחות הפנימיות ונמשך כ\"כ למטה שנתלבש גם בחיצוני', וכמ\"ש במ\"א מענין מ\"ש האריז\"ל בענין ועל תורתך שלמדתנו<sup data-n=\"2019\">706</sup> שהיא תורת הבריאה, ועמש\"ש בפי' בקול<sup data-n=\"2020\">707</sup> היינו במה שמלובש בתוך הקול, דהיינו הגם שהקול הוא קלא דאשתמע שהוא ז\"א מ\"מ בתוכו מלובש אוא\"ס דהיינו מכח\"ב כו'.\n<b></b>קיצור. חכמות בחוץ, שלזה צ\"ל כח מלמעלה יותר, מולדת חוץ, אמצאך בחוץ, ברייתא, מפתחות הפנימיות ומפתחות החיצוני', אך תורה היא מפתחות הפנימיות ונמשך בחוץ זהו ע\"י בחי' הגבוה יותר כמשנ\"ת לעיל וית' לקמן בסמוך.\n(ךד) <b>אך</b><sup data-n=\"2021\">708</sup> אע\"פ שהוא בחי' נובלות וקלא דאשתמע שלמטה ממדריגת חכמה שלמעלה וקלא דלא אשתמע עכ\"ז כח הירידה זו נמשך ממקום עליון יותר, והיינו מבחי' הכתר שלמעלה גם מהחכמה עילאה כמבואר במ\"א<sup data-n=\"2022\">709</sup>. והענין הוא כי הנה<sup data-n=\"2023\">710</sup> אמרו נובלות חכמה שלמעלה תורה שהתורה שנתלבשה<sup data-n=\"2024\">711</sup> בדברים גשמיים היא נובלות<sup data-n=\"2025\">712</sup> מבחי' חכים ולא בחכ' ידיעא, כי הנה חכ' עליונה אין לה השגה רק דוקא בהתלבשותה בדברים גשמיים שאזי בלקיחת האתרוג עד\"מ מאחר שהחכ' מלובשת בו ה\"ז כאלו אוחז בחכ' העליונה, ועד\"מ אותיות החקוקי' על האבן טוב מחמת רוב בהירות האבן טוב א\"א לקרוא אותם, כ\"א דוקא כשחותמים על השעוה אז יכולים לקרות אותם<sup data-n=\"2026\">713</sup>, והנה המשכת חכ' עליונה בדברים גשמיים הוא ע\"י אור הכתר כי אורייתא מחכ' נפקת בבחי' גילוי אבל מקורה הוא למעלה שתרי\"ג מצות דאורייתא וז' דרבנן הם תר\"ך<sup data-n=\"2027\">714</sup> עמודי אור והוא מארחין לבנונית דגלגלתא<sup data-n=\"2028\">715</sup> בחי' כתר שהוא מל' דא\"ס ועי\"ז נמשך למטה כ\"כ, ולכן גילוי חכ' העליונה המלובשת בפ' קדש עד\"מ &lt;32&gt;\nּ הוא יותר מגילוי החכ'<sup data-n=\"2029\">716</sup> במקומה העליון לפי שנמשך ע\"י הכתר שלמעלה מהחכ', ולכן נעשה יחוד עליון ע\"י דברים גשמיים כמו ע\"י צדקה נעשה יחוד עליון באצי' למעלה מג\"ע תענוג הנשמות שהוא בבריאה<sup data-n=\"2030\">717</sup>",[["2019","706","<b>מ\"ש האריז\"ל בענין ועל תורתך שלמדתנו</b>: ראה גם סה\"מ תרל\"ח ע' קנג. וש\"נ. תרל\"ג ח\"ב ע' תכח."],["2020","707","<b>ועמש\"ש בפי' בקול</b>: ראה לקו\"ת פ' ראה כג, ב."],["2021","708","<b>אך</b>: לשון התו\"א לך יא, ג בשינויים והוספות."],["2022","709","<b>כמבואר במ\"א</b>: ראה גם בסמוך בפנים."],["2023","710","<b>הנה</b>: מכאן לשון התו\"א הנ\"ל — וצויין בהערות דבסמוך השינויים."],["2024","711","<b>שנתלבשה</b>: שם: שהיא."],["2025","712","<b>נובלות</b>: שם: ליתא."],["2026","713","<b>ועד\"מ. . אותם</b>: שם: ליתא. השוה מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' נו. סה\"מ תרכ\"ז ע' קנח. תרכ\"ט ע' ריד. תרל\"ב ח\"א ס\"ע רסז ואילך."],["2027","714","<b>שתרי\"ג. . וז'. . תר\"ך</b>: ראה גם לעיל מאמר ד\"ה סמכוני באשישות ובהערות 60-64."],["2028","715","<b>מארחין לבנונית דגלגלתא</b>: ראה גם לעיל המשך זאת חנוכת המזבח פי\"א ובהערה 219."],["2029","716","<b>החכ'</b>: בתו\"א שם: החכמה עצמה."],["2030","717","<b>מג\"ע. . בבריאה</b>: ראה גם לעיל מאמר ד\"ה כמגדל דוד צוארך ובהערה 10."]]],[2000470265,"ומל' דאצי' נעשה עתיק לבריאה<sup data-n=\"2031\">718</sup> כו', שע\"י צדקה נעשה מצדק<sup data-n=\"2032\">719</sup> צדקה ד' נעשה ה'<sup data-n=\"2033\">720</sup> כמ\"ש בזהר עד לא קבילת דכר<sup data-n=\"2034\">721</sup>, ולא נאמר בתורה מעלת אברהם שהי' מאכיל אורחים כו' עד שיצא מארצו ובא כו'<sup data-n=\"2035\">722</sup> הגם שכבר הי' בן ע\"ה שנים<sup data-n=\"2036\">723</sup>, אלא שמתחילה הגם<sup data-n=\"2037\">724</sup> שהי' עושה לא הי' ממשיך כלום<sup data-n=\"2038\">725</sup> ולא הי' נוגע ליחוד עליון עד שאמר ה' אל אברם<sup data-n=\"2039\">726</sup> במאמר זה ויאמר ה' מאציל עליון<sup data-n=\"2040\">727</sup> המשיך אל א\"ב ר\"ם<sup data-n=\"2041\">728</sup> בחי' שכל הנעלם מכל רעיון<sup data-n=\"2042\">729</sup> לך לך כו' להיות ירידה והשתלשלות כו' ואז נמשך להיות יחוד עליון תלוי במעשה התחתונים, ועיקר גילוי היחוד הוא ע\"י התורה, אך האבות עשו הכנה לבחי' התורה כמ\"ש ותורה שם בישראל<sup data-n=\"2043\">730</sup> ע\"י בחי' ישראל, וע' במד\"ר שכל האבות נק' ישראל<sup data-n=\"2044\">732</sup>, ומביא פסוקי' ע\"ז<sup data-n=\"2045\">731</sup>, כי ע\"י אברהם נמשך קו הימין חסד, וע\"י יצחק בחי' גבורה, וע\"י<sup data-n=\"2046\">735</sup> יעקב<sup data-n=\"2047\">733</sup> ת\"ת<sup data-n=\"2048\">734</sup>, וז\"ע ס' בראשית שאין בו מצות<sup data-n=\"2049\">736</sup> התורה רק פ' אברהם ופ' יצחק ופ' יעקב<sup data-n=\"2050\">737</sup> שהם קודם התורה והם הם שהמשיכו להיות בחי' התורה כו'<sup data-n=\"2051\">738</sup>.\n<b>ויובן</b> למשכיל ממ\"ש בענין חכמות בחוץ באד\"ר קל\"א ב' ק\"מ א' ובפ' ואתחנן דרס\"ב א', דעם היות ששם מבואר שמקור כח והמשכה זו היא ממו\"ס, וכאן ביארנו דקלא א' דלא אשתמע הוא ממו\"ס, מ\"מ היינו שלפי מש\"ש י\"ל קלא דלא אשתמע הוא חו\"ב דאצי' כו', או י\"ל דאו\"א במזלא אתכלילן וז\"א בעתיקא אחיד ותליא",[["2031","718","<b>ומל' דאצי' נעשה עתיק לבריאה</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"ב."],["2032","719","<b>שע\"י. . מצדק</b>: בתו\"א שם: שמצדק נעשה."],["2033","720","<b>מצדק. . ה'</b>: ראה גם לעיל מאמר ד\"ה ואעשך לגוי גדול ובהערה 86."],["2034","721","<b>עד לא קבילת דכר </b>[בתו\"א שם ניתוסף: כו']: זהר בא לח, ב."],["2035","722","<b>שיצא מארצו ובא כו'</b>: בתו\"א שם: שבא לא\"י ולא בחו\"ל."],["2036","723","<b>בן ע\"ה שנים</b>: שם: בן ע\"ה כו' — לך יב, ד. ראה גם הנסמן במ\"מ לתו\"א כאן (יא, ג)."],["2037","724","<b>הגם</b>: בתו\"א: אף."],["2038","725","<b>לא הי' ממשיך כלום</b>: ראה גם הנסמן במ\"מ לתו\"א כאן."],["2039","726","<b>שאמר </b>[בתו\"א שם: שויאמר]<b> ה' אל אברם</b>: לך יב, א."],["2040","727","<b>עליון</b>: בהמשך הנדפס: העליון. בתו\"א כבפנים."],["2041","728","<b>א\"ב רם</b>: ראה זהר ס\"ת לך עט, ב. אוה\"ת לך כרך ד ע' תרפה."],["2042","729","<b>בחי' שכל הנעלם מכל רעיון</b>: בתו\"א שם: ליתא. באוה\"ת שם: הוא נז' ברע\"מ. ראה פיוט אל מסתתר. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' עתר ובהנסמן במ\"מ לשם. מאמרי אדה\"א בראשית ע' ח. וש\"נ."],["2043","730","<b>ותורה שם בישראל</b>: תהלים עח, ה."],["2044","732","<b>שכל האבות נק' ישראל</b>: ב\"ר פס\"ג, ג."],["2045","731","<b>וע'. . ע\"ז</b>: בתו\"א שם: ליתא."],["2046","735","<b>וע\"י. . ת\"ת</b>: בתו\"א שם: כו'."],["2047","733","<b>אברהם נמשך קו הימין. . יצחק. . וע\"י יעקב</b>: ראה אוה\"ת לך כרך ד ע' תרצב."],["2048","734","<b>אברהם. . חסד. . יצחק. . יעקב ת\"ת</b>: ראה מאו\"א מערכת אבות סכ\"ז. תו\"ח וארא ח\"א סא, ד. וש\"נ."],["2049","736","<b>ס' בראשית. . מצות</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א בהוספות ע' 10 ובהנסמן במ\"מ לשם."],["2050","737","<b>ופ' יעקב</b>: בתו\"א שם: כו'."],["2051","738","<b>כו'</b>: ע\"כ לשון התו\"א — ראה לעיל הערה 710."]]],[2000470266,"ויובן עוד ממ\"ש במ\"א בענין הלכות אינם בטלים לע\"ל<sup data-n=\"2052\">739</sup> שהלכות<sup data-n=\"2053\">740</sup> הם בחי' מרדכי, כי מרדכי מן התורה מנין<sup data-n=\"2054\">741</sup> מר דרור מתרגמינן מירא דכיא<sup data-n=\"2055\">742</sup>, ופי' מירא דכיא מרירות שבמקום טהור דהיינו הלכות שהם דבר ה'<sup data-n=\"2056\">743</sup> ושרשן ומקורן בח\"ע המלובשת בבחי' מרירות שהוא גשמיות גסות העוה\"ז וחומרתן כתרומות ומעשרות, ואפי' בדברים טמאים כגון שקצים ורמשים אשר הבדלנו<sup data-n=\"2057\">744</sup> מהם, ועז\"נ ששה חדשים בשמן המור<sup data-n=\"2058\">745</sup> שמן הוא בחי' ח\"ע<sup data-n=\"2059\">746</sup> המלובשת בבחי' מרירות שהן הלכות שמלובשות בגשמיות, ופסוק זה מדבר על ענין ביאת הנשמה לג\"ע שצ\"ל בשמן המור וכמארז\"ל אשרי מי שבא לכאן<sup data-n=\"2060\">747</sup> ותלמודו בידו, ומה שההלכות מלובשות בגשמיות הוא כמשל האבוקה שמאירה למרחוק מאד, וכן חביות שנתמלאה על כל גדותיה בשפע רב ועצום עד שנשפך לחוץ, וכן בחי' ההולדה אינו בקטן<sup data-n=\"2061\">748</sup> עד שיהי' גדול ויכנסו בו מוחין דגדלות, ועי\"ז ניתוסף בו כח להוליד בדומה לו, כך הנה ההלכות המלובשות בגשמיות היינו שבאו מאור האבוקה המאירה למרחוק ומחביות שנתמלאה על כל גדותיה בשפע &lt;33&gt;\nּ רב ועצום עד שנשפך לחוץ, וזהו סי' ברכה בית שנשפך בו יין כמים<sup data-n=\"2062\">749</sup>, ואדרבה מקור<sup data-n=\"2063\">*750</sup> וגילוי זה שבגשמיות מובן מקור האור ושרשו שהוא בבחי' האבוקה הגדולה<sup data-n=\"2064\">750</sup>, שענין הארתו למרחוק כ\"כ מובן על עוצם מעלתו ורוממותו, ולכן גם לע\"ל לא יבטלו, וגם בזה י\"ל ששרש ירידת האור למטה כ\"כ זהו מהכתר כו'.\n<b>וז\"ע</b> יעקב אותיות יבקע שבוקע יסוד אימא מחמת ריבוי האור ביותר כו', ועד\"ז נת' בענין שור הבר שיש בו בחי' יתירה בצד אחד מנוני ימא כו', גם כמ\"ש במ\"א ע\"פ המאמר זח\"א דך\"ז ע\"ב בענין אעשה לו עזר<sup data-n=\"2065\">751</sup> שהתומ\"צ שנתלבשו בגשמיות הם כעין בחי' הטפה בחי' זווג גופני ששרשה גבוה יותר מנשיקין אף שהם רוחנים כו', ועד\"ז הוא קלא דאשתמע לגבי קלא דלא אשתמע כו', והעיקר מטעם הנ\"ל שהתורה היא ג\"כ מבחי' הפנימיות רק שירדה ונמשכה",[["2052","739","<b>הלכות אינם בטלים לע\"ל</b>: ירושלמי מגילה פ\"א, ה\"ה. רמב\"ם הל' מגילה ספ\"ב. ראה תו\"א מג\"א קיט, ב. מאמרי אדה\"ז תקס\"ח ח\"א ע' צט. ח\"ב ע' תרצה. מאמרי אדה\"א נ\"ך ע' תא ואילך."],["2053","740","<b>שהלכות</b>: לשון התו\"א מג\"א צ, ד ואילך בשינויים והוספות."],["2054","741","<b>מרדכי מן התורה מנין</b>: ראה חולין קלט, ב."],["2055","742","<b>מר דרור. . דכיא</b>: תשא ל, כג ובת\"א."],["2056","743","<b>הלכות שהם דבר ה'</b>: שבת קלח, ב. עמוס ח, יב."],["2057","744","<b>הבדלנו</b>: בתו\"א הבדילנו."],["2058","745","<b>ששה חדשים בשמן המור</b>: אסתר ב, יב."],["2059","746","<b>שמן. . ח\"ע</b>: ראה גם לעיל המשך זאת חנוכת המזבח פ\"ט ובהערה 159."],["2060","747","<b>אשרי מי שבא לכאן</b>: פסחים נ, א."],["2061","748","<b>ההולדה אינו בקטן</b>: ראה סנהדרין סח, ב ואילך. וראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תפח. וש\"נ. תו\"ח בא ח\"א קלג, סע\"ב. וש\"נ."],["2062","749","<b>בית שנשפך בו יין כמים</b>: ראה ערובין סה, סע\"א."],["2063","*750","<b>מקור</b>: בתו\"א כאן: מאור."],["2064","750","<b>הגדולה</b>: ע\"כ לשון התו\"א — כנ\"ל הערה 740."],["2065","751","<b>כמ\"ש. . בענין אעשה לו עזר</b>: בראשית ב, יח. ראה ביאוה\"ז בראשית ב, ג ואילך. ולהצ\"צ שם כרך ב ע' תריז ואילך."]]],[2000470267,"בחוץ, וזהו ע\"ד המגביהי לשבת המשפילי לראות<sup data-n=\"2066\">752</sup> כו', וע' בבה\"ז פ' חיי<sup data-n=\"2067\">753</sup> גבי קוב\"ה דאתכליל מאתר עילאה סדכ\"ס כו' שביאר שם שהקו מאוא\"ס מאיר בז\"א יותר מבחו\"ב.\n<b>וע'</b> עוד מעלת האותיות הדבור בד\"ה מזוזה מימין<sup data-n=\"2068\">755</sup> בענין קושר כתרים<sup data-n=\"2069\">756</sup> לקונו מתפלותיהן של ישראל שזה נעשה מאותיות הדבור דוקא, ומ\"ש מענין האותיות שנק' סוסים שהם מעלים את הרוכב למקום שלא יוכל להגיע בעצמו וזהו לסוסתי ברכבי פרעה, וזהו ג\"כ מ\"ש אבן כו' היתה לראש<sup data-n=\"2070\">757</sup>, וזהו ויבן בינה יתירה ע\"ד יתר שאת ויתר עז<sup data-n=\"2071\">759</sup>, גם לשון בנין<sup data-n=\"2072\">758</sup> שהאבנים עושים מהם בית שעליו שורה מקיף למקיף<sup data-n=\"2073\">760</sup> כו'<sup data-n=\"2074\">754</sup>.\n<b></b>קיצור. אע\"פ שהיא נובלות חכ', וירדה למטה מקלא פנימאה שהיא חו\"ב מ\"מ שרשה גבוה יותר היינו מהכתר כמ\"ש בזח\"ג ק\"מ א' ובפ' ואתחנן דרס\"ב א' בענין חכ' בחוץ וכמשל החביות שנתמלאה, יעקב יבקע, וכמו זיווג גופני לגבי זיווג נשיקין והעיקר ששרשה מהפנימיות שבעליון רק שירדה בבחי' חוץ, גם ויבן ל' בנין אבנים אותיות שעליהם שורה מקיף למקיף כו'<sup data-n=\"e3\">*</sup>.",[["2066","752","<b>המגביהי לשבת המשפילי לראות</b>: תהלים קיג, ה. ו. ראה גם לעיל מאמר ד\"ה לה\"ע ר\"ח הערה 26."],["2067","753","<b>בבה\"ז פ' חיי</b>: יב, ד."],["2068","755","<b>מעלת האותיות הדבור בד\"ה מזוזה מימין</b>: תו\"א מקץ מב, ב."],["2069","756","<b>קושר כתרים</b>: בתו\"א מהדורת תקצ\"ז: ”כותר קשרים\". במהדורת תרכ\"ב וקה\"ת תשט\"ו: ”קושר כתרים\". במהדורות תרנ\"ט תש\"ח תשל\"ב תשל\"ו תשל\"ח תשל\"ט תשמ\"ה תשמ\"ז תשמ\"ט תשנ\"א תשנ\"ב תשנ\"ז תשס\"א: ”קושר קשרים\". וצ\"ל כבפנים."],["2070","757","<b>אבן כו' היתה לראש</b>: תהלים קיח, כב. ראה סידור שער התפלה כא, סע\"ג ואילך."],["2071","759","<b>יתר שאת ויתר עז</b>: ויחי מט, ג."],["2072","758","<b>ויבן. . לשון בנין</b>: בראשית ב, כב. ראה רש\"י שם מברכות סא, א."],["2073","760","<b>בית. . מקיף דמקיף</b>: ראה לקו\"ת ברכה צט, א ואילך. סידור שער התפלה כ, ב. כא, א. מאמרי אדה\"א קונטרסים ע' יב. וש\"נ."],["2074","754","<b>וע'. . כו'</b>: לשון אוה\"ת שה\"ש כאן ס\"ע תלה ואילך בשינויים."],["e3","*","_<b>לערך בסיום הפיסקא בשולי היריעה נרשם</b>: וגם בזה י\"ל שהירידה נמשך מהכתר."]]],[2000470268,"<h3>צאינה וראינה כו' וע\"ד שנת\"ל בבחי' הדבור</h3>\n<b>פ' בהוב\"ח</b>\n<b>(צאינה</b> וראינה<sup data-n=\"2075\">761</sup> כו' ביום חתונתו<sup data-n=\"2076\">762</sup> כו' וארז\"ל ביום חתונתו זו מ\"ת<sup data-n=\"2077\">763</sup>, ונמצא מובן שהקב\"ה נק' בשם חתן וכנס\"י כלה<sup data-n=\"2078\">764</sup>, ופעם ארז\"ל ע\"פ תורה צוה כו' מורשה<sup data-n=\"2079\">765</sup> א\"ת מורשה אלא מאורסה<sup data-n=\"2080\">766</sup>, משמע שכנס\"י נק' חתן והתורה נק' כלה, מאורסה, והענין הוא דהנה ארז\"ל בינה יתירה ניתנה באשה כו' הוא בחי' אשה יראת ה' ).\n(ךה) <b>וע\"ד</b><sup data-n=\"2081\">767</sup> שנת\"ל בבחי' הדבור, כן יובן ג\"כ בבחי' היראה שנק' אשה כמ\"ש אשה יראת ה', שיש גם בבחי' היראה בינה יתירה יותר מבמדת האהבה עד\"מ כו'. דהנה &lt;34&gt;\nּ כתיב בזאת יבא אהרן<sup data-n=\"2082\">768</sup> אל הקדש, פי' במדת היראה שנק' זאת<sup data-n=\"2083\">769</sup> כידוע שזה השער לה'<sup data-n=\"2084\">770</sup> יוכל לבוא לידי בחי' ומדריגת קדש העליון<sup data-n=\"2085\">771</sup>, ויובן בהקדם ענין ההפרש בין מ\"ע ומל\"ת, כי אהבה הוא מקור ושרש לכל רמ\"ח מ\"ע, ויראה היא מקור ושרש לכל שס\"ה ל\"ת<sup data-n=\"2086\">772</sup>, כמ\"ש במ\"א",[["2075","761","<b>צאינה וראינה</b>: מכאן מתחיל מאמר הח' מהמשך מצה זו (הכולל פרקים כה-כז).\nהפתיחה וכן סיום המאמר באים בסוגרים — אולי ניתוספו לאחרי כתיבת המאמר.\nלהפתיחה — ראה גם לקו\"ת ברכה צג, סע\"ד ואילך.\nפכ\"ה — לשון מאמרי אדה\"ז תקס\"ד ע' נ (הועתק באוה\"ת שה\"ש ח\"ב כאן ע' תלו — וראה שם ע' תנא) בהוספות ושינויים. ונו\"א במאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע נה ואילך. לשון לקו\"ת שה\"ש מו, ב בהוספות ושינויים — צויין אליו באוה\"ת שה\"ש ח\"ב כאן ע' תלו.\nפכ\"ו — ראה תו\"א מג\"א צו, ג. לשון התו\"א שם צט, א ואילך בהוספות ושינויים.\nפכ\"ז — לשון התו\"א מג\"א שם צט, ב ואילך בהוספות ושינויים. לשון אוה\"ת שה\"ש כאן ע' תלו.\nהנחת<sup data-n=\"e107\">*</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן (בחלק הנחותיו)."],["2076","762","<b>צאינה וראינה. . חתונתו</b>: שה\"ש ג, יא."],["2077","763","<b>ביום חתונתו זו מתן תורה</b>: תענית כו, ב (במשנה). ראה מאמרי אדמור מהר\"ש דרושי חתונה ע' לד. מאמרי אדה\"א דברים ח\"ג ע' תתמז בהערה."],["2078","764","<b>שהקב\"ה נק' בשם חתן וכנ\"י כלה</b>: וכל שה\"ש מיוסד ע\"ז כידוע במדרשי רז\"ל. ראה גם מאמרי אדה\"א נ\"ך ע' רלא. וש\"נ. תו\"ח וארא ח\"א עב, ג ובהערה 7."],["2079","765","<b>תורה צוה כו' מורשה</b>: ברכה לג, ד."],["2080","766","<b>א\"ת מורשה אלא מאורסה</b>: ברכות נז, א. ראה גם שער האמונה סט, א הערה 12. סה\"מ תרל\"ח ע' קנה."],["2081","767","<b>וע\"ד</b>: לפרק זה — לשון מאמרי אדה\"ז תקס\"ד ע' נ (הועתק באוה\"ת שה\"ש ח\"ב כאן ע' תלו — וראה שם ע' תנא) בהוספות ושינויים. ונו\"א במאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע נה ואילך. לשון לקו\"ת שה\"ש מו, ב בהוספות ושינויים — צויין אליו באוה\"ת שה\"ש ח\"ב כאן ע' תלו."],["2082","768","<b>בזאת יבא אהרן</b>: אחרי טז, ג."],["2083","769","<b>במדת היראה שנק' זאת</b>: ראה זהר אחרי נו, ב. בהר קח, א. מאמרי אדה\"א ויקרא ח\"א ע' סב. וש\"נ."],["2084","770","<b>שזה השער לה'</b>: תהלים קיח, כ."],["2085","771","<b>העליון</b>: ע\"כ לשון מאמרי אדה\"ז — ראה לעיל הערה 767."],["2086","772","<b>אהבה. . רמ\"ח מ\"ע ויראה. . שס\"ה ל\"ת</b>: ראה תניא פ\"ד ובמ\"מ, הגהות והע\"ק לשם. של\"ה מאמר ג ומאמר ד נא, ב. מאמרי אדה\"א קונטרסים ע' פז, וש\"נ."],["e107","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470269,"שע\"י<sup data-n=\"2087\">773</sup> בחי' קיום מל\"ת וביטול היש שעבודה זו נק' בחי' שקיעה שמלמטה, נמשך מזה מלמעלה שלא בדרך השתלשלות להיות בבחי' גילוי ובליטה, וכמו שמבואר בע\"ח שיש ב' בחי' העלאות היינו עליית העולמות בשבת<sup data-n=\"2088\">774</sup> הוא שפנימיות עולם התחתון עולה ומלביש עולם העליון, וחיצוני' עולם העליון נמשך לפנימיות עולם התחתון, והיינו מפני<sup data-n=\"2089\">775</sup> כי ההעלאה מעולם התחתון הוא ע\"י אהבה שהיא<sup data-n=\"2090\">776</sup> בחי' בליטה ולא בבחי' ביטול ממש, לכן נמשך מלמעלה בבחי' שקיעה להתלבש בבחי' פנימיות עולם התחתון בבחי' צמצום, אבל יש עוד העלאת מ\"ן שבחי' זו נק' בשם<sup data-n=\"2091\">777</sup> עיבור בבטן אימא תלת כלילן גו תלת<sup data-n=\"2092\">778</sup> היינו שנתבטל ממהותו לגמרי בחי' שקיעה ונכלל בעליון ממש ונמשך מזה מ\"ד המשכת מוחין חדשים, וז\"ע יצ\"מ כי<sup data-n=\"2093\">779</sup> גלות מצרים הי' בחי'<sup data-n=\"2094\">780</sup> עיבור ונעשה הגאולה ויצ\"מ מוחין חדשים, וע' בפע\"ח שער ך\"א פ\"א שהם מוחין עליונים מאד מאד כו', וגם באו שלא במדריגה, משא\"כ בשום פעם אחרת רק במדריגה כו' ע\"ש, ועמ\"ש בלק\"ת בד\"ה קול דודי<sup data-n=\"2095\">781</sup> בפי' שנגלה עליהם ממה\"מ הקב\"ה, ועוד שיצ\"מ וקרי\"ס גילוי פנימי'<sup data-n=\"2096\">782</sup> בשינוי הטבע לגמרי בשמים ובארץ ה\"ז בחי'<sup data-n=\"2097\">783</sup> חותם בולט שהוא ההיפך מבחי' אותותינו לא ראינו<sup data-n=\"2098\">784</sup> כו', וזהו אשה מזרעת תחלה<sup data-n=\"2099\">785</sup> יולדת זכר היינו כשההעלאה ממטה למעלה הוא בבחי' שקיעה כנודע שיסוד דנוק' שוקע אז יולדת זכר שנמשך מלמעלה בחי' בליטה וע\"י<sup data-n=\"2100\">786</sup> אהבה יולדת נקבה שנמשך<sup data-n=\"2101\">787</sup> מלמעלה בחי' שקיעה היינו<sup data-n=\"2102\">788</sup> אורות בכלים.\n<b>ויובן</b><sup data-n=\"2103\">789</sup> ענין חותם שוקע וחותם בולט שמלמעלה, כי הנה ע\"י בחי' תרי\"ג מצות דאורייתא וז' דרבנן ממשיכים מבחי' כתר, אך מ\"ע שהם מבחי' ו\"ה<sup data-n=\"2104\">790</sup>",[["2087","773","<b>שע\"י</b>: לשון לקו\"ת שה\"ש[ednref_108_א] מו, ב[ednref_109_ב] ואילך בהוספות ושינויים — צויין אליו באוה\"ת שה\"ש ח\"ב כאן ע' תלו. ונו\"א בסידור[ednref_110_ג] שער התפילין יז, ב ואילך."],["2088","774","<b>בע\"ח. . עליית העולמות בשבת</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ג. ח. טו. תו\"ח בא ח\"א קכז, א הערה 667. לקמן פל\"א."],["2089","775","<b>מפני</b>: בלקו\"ת כאן: מחמת."],["2090","776","<b>שהיא</b>: בלקו\"ת כאן ליתא."],["2091","777","<b>מ\"ן. . בשם</b>: שם: בחי' מ\"ן בבחי'."],["2092","778","<b>תלת כלילן גו תלת</b>: ראה זהר תוספתא בשלח נ, סע\"א. ע\"ח שער הכללים פ\"ג. שער הולדת או\"א וזו\"ן שט\"ז, פ\"ה. ביאוה\"ז בשלח מז, ג ואילך. שעה\"י קל, ב הערה 18."],["2093","779","<b>כי</b>: בהמשך הנדפס ליתא. בלקו\"ת כאן כבפנים."],["2094","780","<b>בחי'</b>: בלקו\"ת: בבחי'."],["2095","781","<b>בלק\"ת </b>[שם: לעיל]<b> בד\"ה קול דודי</b>: שה\"ש יד, ד."],["2096","782","<b>פנימי'</b>: בהמשך הנדפס ובלקו\"ת: הנסים."],["2097","783","<b>ה\"ז בחי'</b>: בלקו\"ת: בחי'."],["2098","784","<b>אותותינו לא ראינו</b>: תהלים עד, ט."],["2099","785","<b>אשה מזרעת תחלה</b>: נדה לא, א."],["2100","786","<b>וע\"י</b>: בלקו\"ת: ולהיפך איש מזריע תחלה ממטה למעלה בחי' בליטה ע\"י."],["2101","787","<b>שנמשך</b>: שם ליתא."],["2102","788","<b>היינו</b>: שם: המשכת."],["2103","789","<b>ויובן</b>: ראה לעיל הערה 773."],["2104","790","<b>מ\"ע. . ו\"ה</b>: ראה בסמוך הערה 792.\n\n[edn_108_א] לשון מאמרי אדה\"ז הנחות הר\"פ ע' פג בשינויים.\n\n[edn_109_ב] ועם הגהות וכו' באוה\"ת שה\"ש ח\"ב ע' תשלט. ע' תשלח. עקב ע' תרכז. וראה גם סהמ\"צ להצ\"צ ס\"ע 40 ואילך.\n\n[edn_110_ג] ובארוכה באמ\"ב שער התפילין קג, א ואילך."]]],[2000470270,"היינו ז\"ת דא\"א לפי שהן מתלבשים באצי' כי או\"א מלבישים חו\"ג דא\"א<sup data-n=\"2105\">791</sup> כו', לכן נק' חותם שוקע, אמנם הל\"ת שהם מבחי' י\"ה<sup data-n=\"2106\">792</sup> ג\"ר דא\"א שאינם מתלבשים כלל לכן נק' חותם בולט כו', ועמ\"ש בלק\"ת בביאור ע\"פ שחורה אני ונאוה<sup data-n=\"2107\">793</sup> בענין מ\"ע ומל\"ת ששם נת' שע\"י מ\"ע ממשיכים האור מז\"ת דע\"י, וע\"י מל\"ת ממשיכים מג\"ר דע\"י, ואיתא בע\"ח שער א\"א פ' א\"ב שז\"ת דע\"י מתלבשין תוך א\"א<sup data-n=\"2108\">794</sup>, והוא מושג ונודע אצלינו ע\"י א\"א, אך ג\"ר דעת\"י א\"א שיתלבשו תוך א\"א, וז\"ע רישא דלא אתיידע כי אפי' א\"א עצמו לא ידע לי' ע\"ש, ונודע שבחי' עתיק הוא מבחי' מל' דא\"ס, ובחי' א\"א הוא שרש<sup data-n=\"2109\">795</sup> הנאצלים, וא\"כ ז\"ת דעתיק הוא ההארה מא\"ס המתלבש ונמשך עכשיו בשרש הנאצלים, אכן ג\"ר דעתיק שא\"א שיתלבשו תוך א\"א &lt;35&gt;\nּ היינו האור מהא\"ס מה שאינו נמשך ומתלבש עכשיו אפי' בשרש האצי'<sup data-n=\"2110\">796</sup>, ולע\"ל יהי' גילוי<sup data-n=\"2111\">797</sup> בחי' זו, וזהו הנק' חותם בולט. ועוי\"ל ועיקר עפמ\"ש בפע\"ח בכוונת ק\"ש שהמדריגה היותר עצומה שאפשר להמשיך מוחין עכשיו הוא מחיצוני' עתיק כו', משא\"כ פנימיות עתיק<sup data-n=\"2112\">798</sup> הוא סתום וגנוז, ולכן פנימיות יסוד<sup data-n=\"2113\">799</sup> עת\"י זהו בחי' חותם בולט וזהו שיתגלה רק לעתיד ועז\"נ וברית שלומי לא תמוט<sup data-n=\"2114\">800</sup>, וע' בהרמ\"ז ח\"א בד\"ד סע\"ב בד\"ה<sup data-n=\"2115\">801</sup> ועאלת<sup data-n=\"2116\">802</sup> בחי'<sup data-n=\"2117\">803</sup> עלמין כו' ובפ' בא בדף מ\"ם ע\"ב<sup data-n=\"2118\">804</sup>.\n<b></b>קיצור. בינה יתירה ניתנה באשה יראת ה' יותר מאהבה שיראה היא מקור שס\"ה ל\"ת, וע\"י ביטול ל\"ת זהו כענין עיבור, ועי\"ז נמשך בחי' חותם בולט שלמעלה, והוא מבחי' ג\"ר דעת\"י שאינו מתגלה עכשיו אפי' בא\"א, וזהו רדל\"א כו', או פנימי' יסוד דעתיק.",[["2105","791","<b>או\"א מלבישים לחו\"ג דא\"א</b>: ראה ע\"ח שער או\"א שי\"ד, פ\"א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שנד."],["2106","792","<b>הל\"ת. . י\"ה</b>: ראה גם לקמן רפ\"מ ובהנסמן שם."],["2107","793","<b>בלק\"ת </b>[בהמשך הנדפס ליתא]<b>. . שחורה אני ונאוה</b>: שה\"ש י, ב."],["2108","794","<b>א\"א</b>: כ\"ה בלקו\"ת ובהמשך הנדפס. ובכת\"י זה: או\"א — וכנראה טעות המעתיק."],["2109","795","<b>הוא שרש</b>: כ\"ה שם. ובכת\"י זה הניח מקום פנוי."],["2110","796","<b>האצי'</b>: בהמשך הנדפס: הנאצלים. בלקו\"ת כבפנים."],["2111","797","<b>גילוי</b>: בהמשך הנדפס: ג\"כ. בלקו\"ת כבפנים."],["2112","798","<b>בפע\"ח. . מחיצוני' עתיק. . פנימיות עתיק</b>: שער הק\"ש ש\"ח, רפט\"ו. שער הכוונות שם דרוש ב. וראה גם רמ\"ז לזהר בראשית ד, ד (יא, א) נעתק בלקו\"ת שה\"ש ט, רע\"ג. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 31 מציין: לע\"ח."],["2113","799","<b>יסוד</b>: בהמשך הנדפס כתב עוה\"פ עתיק הוא. . יסוד."],["2114","800","<b>וברית שלומי לא תמוט</b>: ישעי' נד, י. ראה גם אוה\"ת בראשית כרך ו ע' תתרמט. המשך תער\"ב ח\"ב ע' א'ל."],["2115","801","<b>בהרמ\"ז ח\"א בד\"ד סע\"ב בד\"ה ועאלת</b>: לזהר (יא, ריש ע\"ב בדפי הספר — ד\"ה עאלת)."],["2116","802","<b>בד\"ה ועאלת</b>: בהמשך הנדפס: בד\"ה מזוזה ועאלת — וכנראה טעות המעתיק. בזהר רמ\"ז ובלקו\"ת כבפנים."],["2117","803","<b>בחי'</b>: כ\"ה גם בהמשך הנדפס — וכנראה טעות המעתיק. ברמ\"ז ובלקו\"ת: בח\"י. ובזהר: בתמניסר."],["2118","804","<b>בדף מ\"ם ע\"ב</b>: ד\"ה זמין איהו למחדי (קמז, ב בדפי הספר). בהמשך הנדפס: מ\"ב ע\"ב — וכנראה טעות המעתיק. בלקו\"ת כבפנים."]]],[2000470271,"(ךו) <b>ויובן</b><sup data-n=\"2119\">805</sup> זה גם בבחי' תורה ג\"כ, דהנה ארז\"ל ע\"פ וקבל היהודים את אשר החלו לעשות<sup data-n=\"2120\">806</sup> שבמ\"ת הי' רק החלו לעשות אך הדר קבלוה בימי אחשורש שזה הי' קבלה גמורה, ולכאו' יפלא איך כל ענין קבלת התורה ומעמד הר סיני נק' רק בשם התחלה לבד ובימי אחשורש הי' קבלה גמורה, ויובן זה<sup data-n=\"2121\">807</sup> ע\"פ מ\"ש איש יהודי כו' ושמו מרדכי כו' איש ימיני<sup data-n=\"2122\">808</sup>, ופי' רש\"י איש ימיני שהי' משבט בנימין, וא\"כ צ\"ל למה קרי לי' איש יהודי דמשמע שהי' משבט יהודה, גם צ\"ל שבגזירת המן נא' להשמיד להרוג כו' כל היהודים<sup data-n=\"2123\">809</sup>, והרי בשבע ועשרים ומאה מדינה<sup data-n=\"2124\">810</sup> מל' אחשורש הי' גם מכל השבטים אפרים ומנשה, אלא שנקראו כולם יהודים מפני בחי' הביטול שיש בהם לאוא\"ס ב\"ה, כמו שאנו אומרים בש\"ע מודים אנחנו לך, שעש\"ז נק' יהודי כמו שאמרה לאה הפעם אודה את ה'<sup data-n=\"2125\">811</sup>, ע\"כ קראה שמו יהודה, ויש בכאו\"א מישראל בחי' ביטול זה וכמ\"ש בת\"א ויחי ע\"פ יהודה אתה<sup data-n=\"2126\">813</sup> שזהו בחי' ומדריגת ש\"ע שהוא כריעות והשתחוואות, וכמאמר ואנחנו כורעים<sup data-n=\"2127\">814</sup> ומשתחוים<sup data-n=\"2128\">812</sup>, ולכן נק' מרדכי ג\"כ איש יהודי, פי' שר ליהודים כמו איש הר הבית<sup data-n=\"2129\">815</sup>, כי הוא הי' מקור הביטול כמארז\"ל מרדכי מן התורה מנין דכתי' מר דרור ומתרגמינן מירא דכיא, ומור זה לדעת הרמב\"ם ושארי מפרשים<sup data-n=\"2130\">818</sup>, רק",[["2119","805","<b>ויובן</b>: לפרק זה ראה תו\"א מג\"א צו, ג. לשון התו\"א שם צט, א ואילך בהוספות ושינויים."],["2120","806","<b>וקבל היהודים. . לעשות</b>: אסתר ט, כג. ראה שבת פח, א. תו\"א מג\"א צו, ג. וראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויהי בימי אחשורוש בסופה. וש\"נ."],["2121","807","<b>ויובן זה</b>: לשון תו\"א מג\"א צט, א ואילך בהוספות ושינויים."],["2122","808","<b>איש יהודי. . איש ימיני</b>: אסתר ב, ה."],["2123","809","<b>להשמיד. . כל היהודים</b>: אסתר ג, יג."],["2124","810","<b>בשבע ועשרים ומאה מדינה</b>: שם א, א."],["2125","811","<b>הפעם אודה את ה'</b>: ויצא כט, לה."],["2126","813","<b>בת\"א. . יהודה אתה</b>: מה, ג."],["2127","814","<b>ואנחנו כורעים ומשתחוים</b>: תפלת עלינו לשבח."],["2128","812","<b>ויש. . ומשתחוים</b>: בתו\"א כאן: (ויש. . ומשתחוים ומודים)"],["2129","815","<b>איש הר הבית</b>: מדות פ\"א, מ\"ב ובתוי\"ט שם. ראה גם אוה\"ת בראשית כרך ג ע' תקמה ואילך."],["2130","818","<b>ושארי מפרשים</b>: ראה רס\"ג הובא באב\"ע תשא ל, כג. סמ\"ג מ\"ע קסז."]]],[2000470272,"הראב\"ד<sup data-n=\"2131\">820</sup> והרמב\"ן<sup data-n=\"2132\">821</sup> פי' בא\"א<sup data-n=\"2133\">819</sup>, הוא מושק<sup data-n=\"2134\">816</sup> הנז' בגמ' פ' כיצד מברכין<sup data-n=\"2135\">823</sup> שהוא דם חי' ידוע<sup data-n=\"2136\">817</sup> שנקרש בחטוטרות שבצוארה<sup data-n=\"2137\">822</sup> ונעשה בושם הנק' מור, ובעבודה בנה\"א<sup data-n=\"2138\">824</sup> היינו בחי' אתכפיא ואתהפכא ממרירו למיתקא<sup data-n=\"2139\">825</sup> כי הדם הוא נפש<sup data-n=\"2140\">826</sup> החיונית נפש המתאוה, וכשמהפך תאוותיו הבהמית מתענוגי עוה\"ז להיות כל חפצו ותענוגיו בה' ז\"ע שנעשה ממנו בושם, ועד\"ז יש לפרש מחלוקת הפוסקים במור הנ\"ל, שרבינו יונה<sup data-n=\"2141\">828</sup> מתירו אפי' באכילה<sup data-n=\"2142\">827</sup> ויש אוסרים אותו באכילה<sup data-n=\"2143\">829</sup>, מפני דס\"ל שלא נתהפך רק ריחו אבל גופו אסור באכילה, והרר\"י ס\"ל &lt;36&gt;\nּ שחזר לגמרי להיות היתר, וכמ\"ש בטוא\"ח סי' רי\"ו, ומחלוקת<sup data-n=\"2144\">*830</sup> ע\"פ חסידות י\"ל שתלוי בענין הנז' בגמ' יומא דפ\"ו ע\"ב גבי תשובה אם זדונות נעשו כשגגות או כזכיות, ושניהם ענינם אחד הוא שהרע נהפך לטוב, והנה חי' הנק' ידוע הוא ידעוני<sup data-n=\"2145\">830</sup> הנז' בתורה שהוא מחיות הטמאות<sup data-n=\"2146\">831</sup> שהם מגקה\"ט<sup data-n=\"2147\">832</sup> ועז\"נ<sup data-n=\"2148\">833</sup> ושואל אוב וידעוני<sup data-n=\"2149\">834</sup> ודורש אל המתים, ולכן זה שיהי'<sup data-n=\"2150\">835</sup> הבשם הלז מותר אפי' באכילה זהו ע\"ד כמו שבתשובה מאהבה הזדונות נעשו כזכיות שהרע נהפך לגמרי להיות טוב ממש, וע\"ז אמרו מקום שבע\"ת עומדי'<sup data-n=\"2151\">836</sup> אין צדיקים גמורים יכולים לעמוד שם, אבל בתשובה",[["2131","820","<b>הראב\"ד</b>: ראה הל' כלי המקדש פ\"א, ה\"ג. ראה גם תור\"י לברכות שם ד\"ה חוץ. בהערה הבאה."],["2132","821","<b>הרמב\"ן</b>: תשא ל, כג."],["2133","819","<b>רק. . בא\"א</b>: בתו\"א כאן: (רק. . בע\"א)."],["2134","816","<b>ומור זה לדעת הרמב\"ם. . הוא מושק</b>: ראה שם הל' כלי המקדש פ\"ב, ה\"ד: ומוסק (ובכס\"מ שם). פ\"א, ה\"ג: המור הוא הדם הצרור בחי' שבהודו (ובכס\"מ ורדב\"ז שם). הל' ברכות פ\"ט, ה\"א (ובכס\"מ שם). פיה\"מ כריתות פ\"א, מ\"א (מהדורת קאפח). רמב\"ן שנסמן בהערה 821."],["2135","823","<b>פ' כיצד מברכין</b>: ברכות מג, א. וראה שו\"ע אדה\"ז דיני בשמים להבדלה סרצ\"ז, ס\"ג. סידור סדר ברה\"נ פי\"א, ס\"ה."],["2136","817","<b>ומור זה. . דם חי' ידוע</b>: ראה (בנוסף לתו\"א כאן) לקו\"ת נשא כא, א. כב, ד[ednref_111_א]. שה\"ש לב, סע\"א. מאמרי אדה\"ז הנחות הר\"פ ס\"ע מז.\n(הנחות ודרושי כ\"ק אדה\"א) סידור שער התפלה כז, ב. מאמרי אדה\"ז תקס\"ז ע' קצה וס\"ע רא[ednref_112_ב] ואילך. תקע\"א ע' קלד[ednref_113_ג]. מאמרי אדה\"א במדבר ח\"ב ע' תפח. נ\"ך ע' שפו. תו\"ח ויקהל ח\"ב תה, ג: מדם חי' ששמה ידו\"ע שנק' מו\"ר.\n(גוכתי\"ק כ\"ק אדמו\"ר הצ\"צ) מאמרי אדה\"ז תקע\"א ע' קלטג וע' קמג. אוה\"ת נח ע' 120. (וראה גם תשא ס\"ע א'תתקמג ואילך). מג\"א ע' רצא[ednref_114_ד] ביאוה\"ז נח כרך א' ע' יח. סה\"מ מלוקט ב' ע' קכג."],["2137","822","<b>מושק. . דם חי' ידוע. . בחטוטרות שבצוארה</b>: ראה תור\"י לברכות שם ד\"ה חוץ. אבל באב\"ע שם (לדעת רס\"ג): נעשה בגרון הצבי. וברמב\"ן שם: נצרר בבטן החי' הדומה לצבי הידועה בארץ הודו. ובאבודרהם שער השביעי ברכת הריח (ע' שלח): והמוסק. . בצואר חי' צורתה כצורת הצבי. . ויש לו כמו כיס בצוארה. . תחילה כעין דם ואח\"כ חוזר ונעשה מוסק. ובחומר בקדש — תפא\"י — פ\"ב אות סה: מור. . המוסק הוא משוס. . מיץ המתקבץ בכיס שבין ירכי החי' הנקרא משוס טהיער. . ראיתי אותה. . ככלב בינוני והיא חי' טמאה."],["2138","824","<b>בנה\"א</b>: בהמשך הנדפס: בנפש האדם."],["2139","825","<b>ואתהפכא ממרירו למיתקא</b>: ראה זהר בהקדמה ד, א."],["2140","826","<b>כי הדם הוא נפש</b>: פ' ראה יב, כג."],["2141","828","<b>יונה</b>: בהמשך הנדפס ליתא — וכנראה טעות המעתיק (ראה בסמוך בפנים). בתו\"א כבפנים."],["2142","827","<b>שרבינו יונה. . באכילה</b>: לברכות שם ד\"ה ורבינו מאיר הלוי. וראה גם רמב\"ן תשא שם. מאמרי אדה\"ז תקע\"א ע' קלד."],["2143","829","<b>ויש אוסרים אותו באכילה</b>: רמ\"ה[ednref_115_ה] ברבינו יונה שם. מאמרי אדה\"ז תקע\"א שם."],["2144","*830","<b>ומחלוקת</b>: בתו\"א שם: ומחלקותם."],["2145","830","<b>ידוע הוא ידעוני</b>: ראה רש\"י קדושים יט, לא. פ' שופטים יח, יא. פרישה לטור שם אותיות ה-ו."],["2146","831","<b>ידעוני. . מחיות הטמאות</b>: ראה חינוך מצוה תקיד. אנציק' תלמודית מערכת ידעוני ס\"ע כ ואילך ובהערות 11-10. ברמב\"ם הל' ע\"ז פ\"ו, ה\"ב: עוף ששמו ידוע. ראה אנציק' שם ע' כא ובהערה 12. לקו\"ת שה\"ש סידור הנחת הר\"מ הנחות הר\"פ תקס\"ז ע' רב שנסמנו בהערה 817. בתו\"א כאן: מקליפות הטמאות. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 58."],["2147","832","<b>מחיות הטמאות שהם מגקה\"ט</b>: ראה תניא ספ\"ו."],["2148","833","<b>ועז\"נ</b>: בהמשך הנדפס: ועד\"ז — וכנראה טעות המעתיק. בתו\"א: וכמ\"ש."],["2149","834","<b>ושואל אוב וידעוני</b>: פ' שופטים יח, יא."],["2150","835","<b>שיהי'</b>: בהמשך הנדפס: שהי'. בתו\"א כבפנים."],["2151","836","<b>מקום שבע\"ת עומדי'</b>: ראה ברכות לד, ב. לקו\"ש נצבים כרך יד ע' 361 וע' 363. תו\"ח שמות ח\"א מא, א. וש\"נ. סה\"מ מלוקט ד' ס\"ע יח.\n\n[edn_111_א] <b>ובהנחת הר\"מ בן כ\"ק אדה\"ז בבוך 1066 ע' פז</b>: הדם חי' טמאה ששמה ידוע.\n\n[edn_112_ב] <b>ושם ע' רב</b>: מחי' הנק' ידועה. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 56.\n\n[edn_113_ג] וכן צ\"ל ברשימת המאמרים שם ע' שיב בהערות.\n\n[edn_114_ד] <b>ושם</b>: דם חי' ידוע שנק' רש [וצ\"ל: שנקרש].\n\n[edn_115_ה] <b>ברא\"ש לברכות שם הובא גם בשלטי הגבורים שם</b>: הרז\"ה."]]],[2000470273,"שלא מאהבה רבה הזדונות הם כשגגות אבל לא נתהפכו לגמרי להיות טוב, וזהו דעת האוסרים המור באכילה דעם היות שנתהפך וריחו טוב מ\"מ לא חזר להיות הוא עצמו מותר באכילה והרר\"י סובר שנתהפך לגמרי ע\"ד זדונות נעשו כזכיות ממש.\n<b>והנה</b> מרדכי שנק' ע\"ש מירא דכיא היינו שהוא<sup data-n=\"2152\">837</sup> מקור הביטול שהוא בחי' יסוד אבא<sup data-n=\"2153\">838</sup> שבחכמה<sup data-n=\"2154\">839</sup> כח מ\"ה<sup data-n=\"2155\">840</sup> ובחכ' אתברירו, ולכן נק' איש יהודי ע\"ש הביטול דחכמה כח מ\"ה, ולעו\"ז דמרדכי הי' המן שהי' יש גדול מאד היפך ממש הביטול דחכמה, ולכן אמר בלבו למי יחפוץ המלך<sup data-n=\"2156\">841</sup> לעשות יקר יותר ממני שלא מצא מציאות נכבד יותר ממנו מפני עוצם ישותו וגסותו שהי' יש ודבר נפרד גם בעיני עצמו, ונפרד מאחדותו ית' לומר אני ואפסי עוד<sup data-n=\"2157\">842</sup>, כי הי' מזרע עמלק<sup data-n=\"2158\">843</sup> דכתי' בו ראשית גוים עמלק<sup data-n=\"2159\">844</sup> כי הז' שבפסוק הכנעני והחתי<sup data-n=\"2160\">846</sup> כו' בעבודה הם ז\"מ הרעות<sup data-n=\"2161\">845</sup> תאוות<sup data-n=\"2162\">847</sup> ורציחה<sup data-n=\"2163\">848</sup> כו', ועמלק הוא גסות הרוח<sup data-n=\"2164\">849</sup> שהוא המקור לכל מיני רע, כי גה\"ר הוא מקור לכל זמה\"ר<sup data-n=\"2165\">850</sup>, ולכן להיותו לעו\"ז",[["2152","837","<b>שהוא</b>: בהמשך הנדפס ליתא. בתו\"א כבפנים."],["2153","838","<b>מרדכי. . יסוד אבא</b>: ראה פע\"ח שער הפורים שי\"ט, פ\"ה."],["2154","839","<b>שבחכמה</b>: כ\"ה גם בהמשך הנדפס ובתו\"א: שחכמה היא."],["2155","840","<b>שבחכמה כח מ\"ה</b>: זהר רע\"מ צו כח, א. לד, א. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 39. הנחה ד\"ה וירא העם וינועו על יד הערה 66."],["2156","841","<b>המן. . בלבו למי יחפוץ המלך</b>: אסתר ו, ו."],["2157","842","<b>אני ואפסי עוד</b>: ישעי' מז, ח. י. צפני' ב, טו."],["2158","843","<b>מזרע עמלק</b>: אסתר ג, א ובתרגום שם. ראה לקו\"ש פ' זכור כרך ג ע' 913 הערות 1-2."],["2159","844","<b>ראשית גוים עמלק</b>: בלק כד, כ. ראה (בנוסף לתו\"א כאן. מאמרי אדה\"ז תקע\"א ע' קלא). מאמרי אדה\"א קונטרסים ע' רמא. וש\"נ. תו\"ח תצוה ח\"ב שנו, ג. וש\"נ. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 68 ואילך."],["2160","846","<b>שבפסוק הכנעני והחתי</b>: מהנסמן בסמוך משמע הכוונה להכתוב נחמי' ט, ח [ושם נמנו ו אומות. (ועד\"ז הוא בשמות ג, ח. יז)]. ביהושע ג, י [נמנו ז' אומות — אבל שם: הכנעני ואת החתי].\nראה גם תו\"א צה, א. (כאן) צט, סע\"א. קיט, ד[ednref_116_ו]. מאמרי אדה\"ז תקס\"ב ח\"א ע' קסח. סהמ\"צ להצ\"צ ע' צה. אוה\"ת מג\"א ע' נד. סה\"מ (תרל\"ה ח\"א ע' קנג) פר\"ת ע' רצב. מאמר ד\"ה ראשית גוים פורים תשט\"ו פ\"ו ע' יב נדפס בתורת מנחם התוועדויות חי\"ג ע' 292[ednref_117_ז]."],["2161","845","<b>כי הז'. . הם ז\"מ הרעות</b>: ראה תו\"א מג\"א צה, א. (כאן) צט, סע\"א. מאמרי אדה\"א קונטרסים ע' רמא. וש\"נ. ש\"א סא, ב ובהערה 20. תו\"ח יתרו ח\"ב ער, ג. וש\"נ. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 69."],["2162","847","<b>הכנעני. . תאוות</b>: ראה (בנוסף לתו\"א כאן. מאמרי אדה\"ז תקע\"א ע' קמ). מאמרי אדה\"א קונטרסים ע' רמא. וש\"נ."],["2163","848","<b>והחתי. . רציחה</b>: ראה גם תו\"א כאן. מאמרי אדה\"ז תקע\"א ע' קמ."],["2164","849","<b>גסות הרוח</b>: ראה גם מאמרי אדה\"א קונטרסים ע' רמו. וש\"נ."],["2165","850","<b>זמה\"ר</b>: בהמשך הנדפס ליתא.\n\n[edn_116_ו] <b>ושם מקדים</b>: וכרות. . הכנעני. ועד\"ז בהבא לקמן.\n\n[edn_117_ז] <b>ושם</b>: וכרות. . וגו' (ומנה בכתוב כל השבעה! עממין, שבע מדות). החצע\"ג היא הוספת המהדיר, ובמאמר המקורי ליתא — ראה סה\"מ תשט\"ו מהדורת תשמ\"ח (ע' 258)."]]],[2000470274,"נגד בחי' הביטול לאלקות בגסות רוחו רצה להשמיד ולהרוג את כל היהודים שהם בבחי' הביטול להיותם מחשיבים אותו ית' לאלקה, שזהו היפך הגסות והישות שלו, ואם היו כופרים ח\"ו לא היו עושים להם כלום<sup data-n=\"2166\">851</sup> שהרי לא גזר רק על היהודים, אך כולם כא' לא עלה על דעתם מחשבת חוץ ח\"ו ומסרו נפשם על אחדותו ית' וזהו בחי' ביטול ממש, ובחי' זו ישנו בכאו\"א אפי' בקל שבקלים<sup data-n=\"2167\">852</sup> יכול למסו\"נ<sup data-n=\"2168\">853</sup> שלא יהי' נפרד<sup data-n=\"2169\">854</sup> מאחדותו ית' בשום אופן בעולם, ומה שעובר על שארי עבירות זהו מפני הרוח שטות שמכסה על האמת ומטעה אותו כו' לחשוב שאינו נפרד מיחודו ואחדותו ע\"י עבירה ההיא כיון שלובש טלית ומניח תפילין. והנה בחי' אהבה המוסתרת שממנה נמשך מס\"נ זה היא למעלה מן הדעת, ולכן לא נז' בתורה טעם על מס\"נ<sup data-n=\"2170\">855</sup> רק על אהבה נא' טעם כמ\"ש לאהבה את ה' כי הוא חייך, והרי מס\"נ הוא היפך טעם הזה להשליך חייו מנגד, אלא הענין הוא שאינו שייך טעם ושכל על מס\"נ, להיותו נלקח מלמעלה מהשכל ולמעלה מהדעת, כי הנה פי' כי הוא חייך היינו מה שהוא ית' ממכ\"ע וסוכ\"ע שעי\"ז מחי' ומהוה כל עולמים, ונת' במ\"א דבחי' ממכ\"ע &lt;37&gt;\nּ וסוכ\"ע<sup data-n=\"2171\">857</sup> הוא רק הארה<sup data-n=\"2172\">856</sup> לבד, וכמ\"ש כי נשגב שמו לבדו<sup data-n=\"2173\">858</sup>, אבל מהותו ועצמותו אינו בגדר עלמין כלל אפי' להיות סובב וממלא לעלמין, כי לא זה הוא עיקר האלקות מה שהעולמות מתהוים ממנו<sup data-n=\"2174\">859</sup> ומקבלים חיותם ממנו ית', שהרי אתה הוא קודם שנבה\"ע<sup data-n=\"2175\">860</sup> ואתה הוא לאחר שנבה\"ע<sup data-n=\"2176\">861</sup> בשוה ממש, שגם אלו לא הי' בורא העולמות הי' הכל שוה לפניו ית' אלא מה שמחי' ומהוה העולמות זהו רק הארה ממנו ית', וכמ\"ש במ\"א שלכן נק' הבריאה יש מאין, שבחי' התהוות היש הוא רק ע\"י הארה לבד שנק' אין לגבי",[["2166","851","<b>ואם היו כופרים. . כלום</b>: ראה (בנוסף לתו\"א כאן צט, ב. מאמרי אדה\"ז תקע\"א ע' קלא. ע' קמ. אוה\"ת מג\"א ע' רצא). לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 72. מאמרי אדה\"א נ\"ך ע' תנב. וש\"נ. ש\"א ב, ב ובהערה 28. סה\"מ מלוקט ג' ע' סח. וש\"נ."],["2167","852","<b>בקל שבקלים</b>: ע\"פ ר\"ה כה, ב. תוספתא שם ספ\"א. קה\"ר פ\"א ד [ד]. רש\"י ויצא כט, כא."],["2168","853","<b>בקל שבקלים יכול למסו\"נ</b>: ראה תניא פי\"ח. מאמרי אדה\"א הנחות תקע\"ז ע' קלד. וש\"נ. לקו\"ש חנוכה כרך ג ע' 818 בהערה. סה\"מ מלוקט ד' ע' קפח בהערה."],["2169","854","<b>שלא יהי' נפרד</b>: ראה גם לעיל מאמר ד\"ה ואעשך לגוי גדול ובהערה 34."],["2170","855","<b>לא נז' בתורה טעם על מס\"נ</b>: ראה (בנוסף לתו\"א כאן. מאמרי אדה\"ז תקע\"א ע' קלב. ע' קמ. אוה\"ת מג\"א ע' רצא). לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 77 ואילך: ציווי. לקו\"ש אמור כרך יב ע' 212 ואילך. מאמרי אדה\"א נ\"ך ע' תמה. וש\"נ. ש\"א צ, ב ובהערה 29. לעיל המשך זאת חנוכת המזבח פכ\"א על יד הערה 585."],["2171","857","<b>ממכ\"ע וסוכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["2172","856","<b>ונת' במ\"א דבחי' ממכ\"ע וסוכ\"ע. . הארה</b>: ראה תו\"א כאן צח, ב. לקו\"ת אמור לא, ג. לעיל מאמר ד\"ה ואעשך לגוי גדול על יד הערה 49. לקמן (בחלק ההנחות) הנחה ד\"ה ויאמר משה אל העם אל תיראו על יד הערה 36."],["2173","858","<b>כי נשגב שמו לבדו</b>: תהלים קמח, יג."],["2174","859","<b>לא זה הוא עיקר האלקות מה שהעולמות מתהוים ממנו</b>: ראה תו\"א כאן ובהנסמן במ\"מ לשם."],["2175","860","<b>אתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["2176","861","<b>ואתה. . שנבה\"ע</b>: ניתוסף ע\"פ המשך הנדפס."]]],[2000470275,"מהותו ועצמותו ית', וע' בת\"א פ' בשלח<sup data-n=\"2177\">862</sup> בד\"ה<sup data-n=\"2178\">863</sup> וירא ישראל, ומ\"ש<sup data-n=\"2179\">*864</sup> ואתה מחי' את כולם, פי' ואתה היינו ך\"ב אותיות דבר ה' מא' ועד תי\"ו וה' מוצאות<sup data-n=\"2180\">864</sup> שע\"י האותיות מחי' את כולם, והאותיות הם רק הארה לבד, כמו שהאותיות באדם הם רק לבושי הנפש, וא\"כ מהותו ועצמותו הוא למעלה מעלה גם מבחינה ומדריגה זו הנז' שהוא חייך, כי זהו רק היותו ממלא וסובב, ומזה נמשך בחי' האהבה שהוא חייך, ועז\"נ נפשי אויתיך בלילה<sup data-n=\"2181\">865</sup> כמ\"ש בסש\"ב פמ\"ד, אבל מס\"נ להשליך חייו מנגד שלא ליפרד ממהותו ועצמותו ית' שהוא למעלה מעלה מחיי החיים וקמי' כלא ממש חשיבי ואתה הוא קודם שנבה\"ע<sup data-n=\"2182\">866</sup>. והנה כ\"ז הוא שיש בכח כאו\"א מישראל כי הניצוץ אלקי שבנשמה הוא ג\"כ מבחי' שלמעלה מהשכל וכמ\"ש במ\"א וע' בע\"ח שמ\"א פ\"ג<sup data-n=\"2183\">867</sup> והכוונה כי יש ניצוץ כו', ולכן בימי אחשורש הי' אז מס\"נ בפו\"מ אצל כל ישראל שלא ליפרד מאחדותו ית', וזהו ומאמר מרדכי קיים<sup data-n=\"2184\">868</sup> כי מרדכי הי' מקור הביטול איש יהודי כנ\"ל.\n<b></b>קיצור. שכ\"י גם משארי שבטים נק' יהודי ע\"ש הביטול, ומרדכי מירא דכיא מקור הביטול נק' איש יהודי, ולעו\"ז הי' המן גה\"ר ראשית כל מדה\"ר, ועמדו במס\"נ שזהו מבחי' אהבה מוסתרת שלמעלה משכל, כי ע\"פ שכל לאהבה את ה' כי הוא חייך ממכ\"ע וסוכ\"ע, אמנם זהו רק הארה לבד ואתה<sup data-n=\"2185\">869</sup> קודם שנה\"ע כו' בשוה ומזה נמשך בחי' זו, והוא מבחי' ניצוץ האלקי שבנשמה.\n(ךז) <b>ועפ\"ז</b><sup data-n=\"2186\">870</sup> יובן מה שבמ\"ת הי' רק החלו לעשות, וגמר הקבלה הי' בימי אחשורש כמ\"ש וקבלו<sup data-n=\"2187\">871</sup> היהודים את אשר החלו לעשות, שבמ\"ת שהקדימו נעשה לנשמע<sup data-n=\"2188\">872</sup> ועכדו\"ד פרחה נשמתם<sup data-n=\"2189\">873</sup> שהוא בחי' ביטול ומס\"נ שלכך",[["2177","862","<b>וכמ\"ש במ\"א. . בת\"א פ' בשלח[ednref_118_ח]</b>: סא, ד."],["2178","863","<b>בד\"ה</b>: בהמשך הנדפס: סד\"ה. וכנראה שצ\"ל כבפנים."],["2179","*864","<b>ומ\"ש</b>: בתו\"א כאן: וכמ\"ש."],["2180","864","<b>מא' ועד תי\"ו וה' מוצאות</b>: ראה שער היחוד והאמונה פ\"ב."],["2181","865","<b>נפשי אויתיך בלילה</b>: ישעי' כו, ט. ראה הנסמן במ\"מ לתו\"א כאן. מאמרי אדה\"ז על ענינים ע' כד."],["2182","866","<b>שנבה\"ע</b>: בהמשך הנדפס ניתוסף: כו'."],["2183","867","<b>בע\"ח שמ\"א פ\"ג</b>: במהדורת שקלאב תק\"ס — ובדפו\"א שמ\"ב, פ\"א. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גל נעול ובהערה 56."],["2184","868","<b>ומאמר מרדכי קיים</b>: וכ\"ה במאמרי אדה\"ז תקע\"א ע' קמ. אוה\"ת מג\"א ע' רצא. במאמרי אדה\"ז תקע\"א ע' קלג: וזהו ענין מאמר מרדכי עליהם. בתו\"א כאן: ואת מאמר מרדכי. באסתר ב, כ ואת מאמר מרדכי. שם ט, לב: ומאמר אסתר קים."],["2185","869","<b>ואתה</b>: בהמשך הנדפס: אמנם אתה."],["2186","870","<b>ועפ\"ז</b>: פרק זה לשון התו\"א מג\"א שם צט, ב ואילך בהוספות ושינויים. לשון אוה\"ת שה\"ש כאן ע' תלו."],["2187","871","<b>וקבלו</b>: ראה גם הנסמן לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויהי בימי אחשורוש בשוה\"ג להערה 35. בתו\"א כאן וכן בפנים כאן להלן בסיום פיסקא זו ולעיל בפנים על יד הערה 806: וקבל."],["2188","872","<b>שבמ\"ת שהקדימו נעשה לנשמע</b>: שבת פח, א."],["2189","873","<b>ועכדו\"ד פרחה נשמתם</b>: ראה שבת פח, ב. מאמרי אדה\"א ויקרא ח\"א ע' ג[ednref_119_א]. וש\"נ. נ\"ך ע' שפא. וש\"נ. תו\"ח בראשית יז, ב. וראה גם תו\"א מג\"א צב, ד[ednref_120_ב] צח, ד[ednref_121_ג].\n\n[edn_118_ח] במהדורת אותיות מרובעות כאן צט, ב נדפס: שלח. וצ\"ל כבפנים.\n\n[edn_119_א] וכן במדבר ח\"ב ע' תקמו ואילך. המשך תער\"ב ח\"א ע' ז. סה\"ש תש\"נ ח\"ב ע' 520 (תענוג).\n\n[edn_120_ב] אוה\"ת שם ע' ב'שלב (ובמהדורת תש\"נ ע' קלח).\n\n[edn_121_ג] מאמרי אדה\"ז תקע\"א הנחת כ\"ק אדה\"א ע' קלב. ומגוכתי\"ק הצ\"צ ע' קלט (וכן צ\"ל ברשימת המאמרים שם ע' שיב). אוה\"ת מג\"א ע' רצ."]]],[2000470276,"זכו למ\"ת התגלות אלקות, אבל בימי אחשורש הי' הביטול הזה ביתר שאת ויתר עז, כי במ\"ת הי' ביטול זה מחמת כח האתעדל\"ע שכפה עליהם הר כגיגית<sup data-n=\"2190\">875</sup>, וכמים הפנים<sup data-n=\"2191\">876</sup> כו', אבל בימי אחשורש הי' הביטול מצד עצמם בבחי' אתעדל\"ת<sup data-n=\"2192\">874</sup> תחלה, ולכן גם ההמשכה שנמשך עי\"ז הוא ממקום עליון יותר, עד שהגילוי שבמ\"ת נק' רק החלו בחי' התחלה לבד לגבי אור ההמשכה שנמשך להם בימי אחשורש שאז היתה קבלה גמורה, וכמ\"ש וקבל קבלה גמורה, וכ\"ז &lt;38&gt;\nּ הוא ע\"י היותם יהודים שעמדו ביהדותם להיות בבחי' הביטול.\n<b>והענין</b> הוא דכתי' מה ראו על ככה<sup data-n=\"2193\">877</sup> ומה הגיע אליהם, פי' מ\"ה הוא בחי' ביטול ומס\"נ כנ\"ל<sup data-n=\"2194\">878</sup> הגיע אליהם, וכנודע שיש ב' בחי' מ\"ה וב\"ן<sup data-n=\"2195\">879</sup>, ב\"ן הוא בחי' ירידה והשתלשלות להיות יש ודבר ומ\"ה הוא בחי' הביטול בבחי' כח מ\"ה, ובחי' מ\"ה וביטול זה הגיע אליהם, דהנה הגם שבימי אחשורש הי' הביטול באתעדל\"ת מצד עצמם, היינו שההתחלה הי' מהם, אבל ודאי שאלמלא עוזרו<sup data-n=\"2196\">880</sup> לא הי' יכול לו, א\"כ נמשך גם אתעדל\"ע להולדת בחי' ביטול זה<sup data-n=\"2197\">881</sup>, וזהו מ\"ה ראו כו' ומה הגיע אליהם, משא\"כ במ\"ת הי' ההתחלה באתעדל\"ע לבד, והחילוק הוא ע\"ד אשה מזרעת תחלה יולדת זכר, וכנודע שכנס\"י נק' אשה<sup data-n=\"2198\">882</sup>, וכשהתחלת ההולדה הוא ע\"י בחי' אתעדל\"ת ואח\"כ באתעדל\"ת אתעדל\"ע<sup data-n=\"2199\">883</sup> אזי יולדת זכר שהוא בחי' מ\"ה וביטול אמיתי, משא\"כ בשעת מ\"ת שהי' ההתחלה ע\"י אתעדל\"ע שכפה עליהם",[["2190","875","<b>שכפה עליהם הר כגיגית</b>: שבת פח, א. ראה תו\"א כאן צח, ד. ש\"א ב, ב הערה 33."],["2191","876","<b>וכמים הפנים</b>: משלי כז, יט."],["2192","874","<b>האתעדל\"ע. . אתעדל\"ת</b>: נסמן בסמוך הערה 883."],["2193","877","<b>מה ראו על ככה</b>: אסתר ט, כו [ושם ומה — אבל כ\"ה גם בתו\"א כאן. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה צאינה וראינה כאן על יד הערה 97. סה\"מ תרל\"ח ע' רלד. וש\"נ]."],["2194","878","<b>ומס\"נ כנ\"ל</b>: בתו\"א כאן: ומ\"נ. בהערות ותיקונים לשם מכ\"ק אדמו\"ר (ע' 274): ומ\"הד (בהוצאה הא' ומס\"נ!)."],["2195","879","<b>ב' בחי' מ\"ה וב\"ן</b>: ראה ע\"ח שער שביה\"כ ש\"ט, פ\"ז. ראה גם בענין מ\"ה וב\"ן (בנוסף לתו\"א כאן. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 98) מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקמד ואילך (ובשולי היריעה שם). מאמרי אדה\"א קונטרסים ע' רפא וע' רפח. סה\"מ תרל\"ח ע' שכ ואילך (ובהנסמן שם בריש המאמר)."],["2196","880","<b>שאלמלא עוזרו</b>: ראה קדושין ל, ב. סוכה נב, ב. תניא רפי\"ג."],["2197","881","<b>אתעדל\"ע להולדת בחי' ביטול זה</b>: ראה סידור שער התפלה יט, ב."],["2198","882","<b>שכנס\"י נק' אשה</b>: משלי לא, ל. במדב\"ר פ\"ט, מד."],["2199","883","<b>באתעדל\"ת. . אתעדל\"ע</b>: ראה זהר לך פח, א. מאמר ד\"ה לרוקע נדפס במאמרי אדה\"ז תקס\"ב ח\"א ע' קצד [ובמקביליו ובהנסמן במ\"מ לשם]. מאמרי אדה\"א דברים ח\"א ע' קצח. וש\"נ. תו\"ח שמות ח\"א מא, א ובהערה 189."]]],[2000470277,"הר כגיגית ואע\"פ שע\"י אתעדל\"ע זו נתעוררו באתעדל\"ת וביטול להקדים נעשה לנשמע מ\"מ כיון שהוא ע\"ד איש מזריע תחלה לכן יולדת נקבה שם ב\"ן כו', כי גם שם ב\"ן הוא בחי' ביטול היש, וכנודע מענין משה ואליהו שאליהו בגימ' ב\"ן והי' בו ביטול הגוף עד שעלה בסערה כו', ומ\"מ ביטול דמשה גבוה יותר שהי' בבחי' מ\"ה ממש גם בהיותו ע\"פ האדמה וכמ\"ש ונחנו מ\"ה שזה גדול יותר מביטול דאליהו כו'. ועוי\"ל החילוק שבין הביטול שהי' בשעת מ\"ת לביטול שהי' בימי אחשורש ע\"ד שנת' במ\"א גבי משה ואהרן שבשניהם נא' ונחנו מ\"ה ומ\"מ משה הי' בחי' מ\"ה דמ\"ה ואהרן ב\"ן דמ\"ה<sup data-n=\"2200\">884</sup>, ובחי' הביטול דב\"ן דמ\"ה זהו בחי' היולדת נקבה לגבי ביטול מ\"ה דמ\"ה שהוא ביטול עליון יותר כו'. והנה עכ\"פ מובן שהביטול ומס\"נ דכללות ישראל בימי אחשורש הי' גדול יותר במדריגה מבחי' הביטול שהקדימו נעשה כו', והיינו לפי שכשאשה מזרעת תחלה יולדת זכר כו'. וכמו שהוא בענין הביטול כך הוא ג\"כ בעצם גילוי האור שמלמעלה שהוא בחי' התורה נק' במ\"ת החלו לעשות נגד מה שקבלוה בימי אחשורש, שהוא גילוי עליון יותר ממקור התורה שנק' משל הקדמוני<sup data-n=\"2201\">885</sup>, והיינו מפני שכשאשה מזרעת תחלה יולדת זכר משא\"כ איש כו' יולדת נקבה, וזהו תורה צוה לנו משה מורשה א\"ת מורשה אלא מאורסה, ושייך בחי' זו גם באור התורה ע\"פ מ\"ש בע\"ח שער י\"א פ\"א<sup data-n=\"2202\">886</sup> כי עתיק יומין כו' ובחי' מ\"ה שבו כו' ע\"ש, וזהו מה ראו על ככה ומה כו' מה ראו היינו בחי' הביטול ומה הגיע אליהם הוא בחי' התורה דמחכ' נפקת כח מ\"ה שהיא בחי' משל הקדמוני<sup data-n=\"2203\">887</sup> כו'. והנה נודע כי בחי' יראה עילאה היא בחכ'<sup data-n=\"2204\">888</sup>, ויראה תתאה שרשה מבחי' יראה עילאה<sup data-n=\"2205\">889</sup> וא\"כ בינה יתירה ניתנה באשה יראת ה' דיר\"ת שעי\"ז יבא לבחי' &lt;39&gt;\nּ הגילוי דיר\"ע שבחכ' כח מ\"ה, וזהו בזאת יבא אהרן אל הקדש.\n<b>ולפי</b> משנ\"ת לעיל י\"ל פי' בינה יתירה כי ע\"י היראה שהיא בחי' חותם שוקע שמלמטה נמשך חותם בולט שמלמעלה המשכת ג\"ר דע\"י, וזהו בינה יתירה כי בינה בן י\"ה<sup data-n=\"2206\">891</sup> ובינה יתירה גילוי בחי' י\"ה שבעת\"י, ועמ\"ש בפי' אם",[["2200","884","<b>משה. . מ\"ה דמ\"ה ואהרן ב\"ן דמ\"ה</b>: ראה תו\"א כאן צט, ג. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה צאינה וראינה כאן על יד הערה 105. אוה\"ת תצוה ע' א'תרו. ע' א'תרכג. המשך תער\"ב ח\"ב ע' א'כח."],["2201","885","<b>התורה שנק' משל הקדמוני</b>: שמואל-א כד, כג וברש\"י שם. ראה תו\"א כאן צח, ב. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 106. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תב. שמות ח\"ב ע' שפג. סה\"מ תרל\"ח ע' רפז."],["2202","886","<b>בע\"ח שער י\"א פ\"א</b>: במהדורת שקלאב תק\"ס — ובדפו\"א [שער עתיק] שי\"ב, פ\"א."],["2203","887","<b>הקדמוני</b>: ע\"כ לשון התו\"א בהוספות ושינויים — ראה לעיל הערה 807."],["2204","888","<b>יראה עילאה היא בחכ'</b>: ראה תו\"א מקץ מא, ג."],["2205","889","<b>ויראה תתאה שרשה. . יראה עילאה</b>: ראה לקמן פרק ג\"ל. תו\"א ויקהל קיד, ד. מאמרי אדה\"א דברים ח\"ב ע' תרנט. וש\"נ. תו\"ח בראשית כא, ג ובהערה 22."],["2206","891","<b>בינה בן י\"ה</b>: ראה זהר רע\"מ תרומה קנח, א. נשא קכג, סע\"א. אגה\"ת פ\"ח. תו\"ח שמות ח\"א מז, א. וש\"נ."]]],[2000470278,"עוונות תשמור י\"ה או\"א אזי אד' מי יעמוד בינה דעתיק כו' בלק\"ת פ' שלח<sup data-n=\"2207\">892</sup> בביאור ע\"פ ועתה יגדל נא<sup data-n=\"2208\">890</sup> כו'.\n<b></b>קיצור. במ\"ת כפה עליהם הר אתעדל\"ע שמעורר אתעדל\"ת לכן נק' החלו לעשות נגד בימי אחשורש שהי' קבלה גמורה שהי' באתעדל\"ת תחלה, וזהו מ\"ה ראו על ככה, ועי\"ז מה הגיע אליהם שהי' הגילוי עליון יותר, וע\"ד יולדת זכר, חכמה כח מ\"ה, וז\"ע יר\"ע ויר\"ת שרשה מיר\"ע, ולכן בזאת יבא אהרן אל הקדש, וגם בינה יתירה י\"ה דעת\"י ע\"ד אד' מי בינה דעתיק כו'.\n(ועפ\"ז<sup data-n=\"2209\">893</sup> יובן מ\"ש רז\"ל א\"ת מורשה אלא מאורסה זהו כמו שכפה עליהם הר כגיגית שעי\"ז יולדת נקבה זהו מה שהתו' נק' כלה מאורסה לאיש, ומה שהדר קבלוה בימי אחשורש שעי\"ז וילדה זכר גילוי יותר עליון, והכח ע\"ז ממ\"ת (שלא הי' מ\"ת פ\"ש<sup data-n=\"2210\">894</sup> ) זהו שארז\"ל ע\"פ ביום חתונתו זו מ\"ת שזהו גילוי התורה מה שנמשך ע\"י אתעדל\"ת שקבלוה מעצמה כו' והוא כענין בחי' חותם בולט שמלמעלה כו').",[["2207","892","<b>אם עוונות תשמור </b>[בהמשך הנדפס תשמר]<b>. . בלק\"ת פ' שלח</b>: תהלים קל, ג. ראה זהר בלק קפה, ב. לקו\"ת שם מ, א. אוה\"ת קרח ע' תשא. סה\"מ תרכ\"ו ע' קמה. ע' רנט."],["2208","890","<b>וזהו. . נא</b>: לשון אוה\"ת שה\"ש כאן ע' תלו."],["2209","893","<b>(ועפ\"ז. . כו')</b>: ראה לעיל הערה 761."],["2210","894","<b>פ\"ש</b>: בהמשך הנדפס: פעם שנית."]]],[2000470279,"<h3>וירא העם וינועו כו' בינה יתירה</h3>\n<b>פ' במדבר ערב חגה\"ש</b>\n<b>(וירא</b> העם וינועו<sup data-n=\"2211\">895</sup> ויעמדו מרחוק<sup data-n=\"2212\">896</sup>, וכן כתיב ויחרד כל העם<sup data-n=\"2213\">897</sup> אשר במחנה, וצ\"ל מהו שייך יראה וחרדה למ\"ת, הנה ארז\"ל אלפים שנה קדמה תורה",[["2211","895","<b>וירא העם וינועו</b>: מכאן מתחיל מאמר הט' מהמשך מצה זו (הכולל פרקים כח-ל).\nהפתיחה וכן סיום המאמר באים בסוגרים — אולי ניתוספו לאחרי כתיבת המאמר.\nפכ\"ח — ראה לקו\"ת שה\"ש טו, סע\"ב ואילך. ומקרוב לסיום פיסקא זו הוא ע\"פ לשון לקו\"ת שה\"ש טו, ג בהוספות ושינויים (צויין אליו באוה\"ת שה\"ש כאן ח\"ב ע' תלו).\nפכ\"ט — לשון מאמרי אדה\"ז תקס\"ד ע' נ (הועתק באוה\"ת שה\"ש ח\"ב כאן ע' תלו) בהוספות ושינויים. לשון לקו\"ת שמע\"צ פח, ב בהוספות ושינוים. לשון ביאוה\"ז להצ\"צ כרך ב' ע' תתקסג בשינויים. וראה המשך וככה תרל\"ז פכ\"ו ופכ\"ז.\nפ\"ל — בתחילתו לשון ביאוה\"ז להצ\"צ כרך ב' ע' תתקסג בשינויים. ראה המשך וככה תרל\"ז פכ\"ח.\nהנחת<sup data-n=\"e122\">*</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן (בחלק הנחותיו).\nבהכותרת המופיע בריש המאמר הנה התיבות: ”ערב חגה\"ש\" ניתוסף מהנחת כ\"ק אדמו\"ר מהורש\"ב."],["2212","896","<b>וירא העם וינועו ויעמדו מרחוק</b>: יתרו כ, טו."],["2213","897","<b>ויחרד כל העם</b>: יתרו יט, טז."],["e122","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470280,"לעולם<sup data-n=\"2214\">898</sup>, והיינו למעלת העולם<sup data-n=\"2215\">899</sup> ע\"ש אאלפך חכ' אאלפך בינה<sup data-n=\"2216\">900</sup>, ויובן בהקדם מארז\"ל)\n(ךח) <b>בינה</b> יתירה ניתנה באשה יראת ה', עפמ\"ש נקבה תסובב גבר<sup data-n=\"2217\">901</sup>, שלע\"ל יתגלה בחי' זו, ועכשיו ישנה בבחי' היראה שנק' בשם אשה, דהנה כתיב כימי צאתך מאמ\"צ<sup data-n=\"2218\">902</sup> אראנו נפלאות, דעם היות שהגילוי דלע\"ל יהי' גילוי יותר מיצ\"מ שלכן אמרו וכי מזכירים יצ\"מ לע\"ל<sup data-n=\"2219\">903</sup>, עכ\"ז יהי' ע\"ד כמו ביצ\"מ, והענין הוא דביצ\"מ כתי' קול דודי הנה זה בא מדלג על ההרים, שהי' הגילוי בבחי' דילוג ולא כסדר המדרגות כן לע\"ל יהי' ג\"כ בבחי' דילוג, אבל בזאת יהי' יתרון בחי' הגילוי דלע\"ל על הגילוי דיצ\"מ, שלע\"ל יהי' הדילוג בבחי' קיפוץ וכמ\"ש מקפץ על הגבעות<sup data-n=\"2220\">904</sup>, ושרש ההפרש<sup data-n=\"2221\">905</sup> הוא שדילוג הוא ברגל א', וקיפוץ הוא בשני רגלים<sup data-n=\"2222\">906</sup>, שמקפץ בב' רגליו בב\"א ממקום למקום.\n<b>והענין</b> הוא דכל בחי' דילוג הוא הארה גדולה שבאה מלמעלה שאינה יכולה להתגלות כ\"א בבחי' רגל לבד, כי מלבד שכל בחי' הגילוי אפי' כסדר המדרגות הוא רק בחי' אחרונה שנק' נה\"י ובחי' רגל כו', הנה דעת לנבון נקל<sup data-n=\"2223\">907</sup> שבחי' הגילוי שבא בבחי' דילוג שהוא שלא כסדר המדרגות א\"א להתגלות כ\"א ע\"י בחי' רגל כו', וכמ\"ש ועמדו רגליו &lt;40&gt;\nּ כו', וכתי' והארץ הדום רגלי<sup data-n=\"2224\">908</sup>, וכתי' ויראו את אלקי ישראל<sup data-n=\"2225\">909</sup> ותחת רגליו, שהגילוי מה שהי' ומה שיהי'<sup data-n=\"2226\">910</sup> זהו מבחי' רגל, ויש ב' רגלים היינו ב' בחי' קו הימין וקו השמאל שהם אהוי\"ר, וזהו מדלג על ההרים שהוא בחי' דילוג ברגל א' היינו גילוי בבחי' אהבה, ומקפץ על הגבעות שהוא בחי' דילוג הנק' קיפוץ שהוא בשתי רגלים זהו כשנמשך גילוי בחי' יראה, וע\"ז אמרו ובמורא גדול זה גילוי שכינה<sup data-n=\"2227\">911</sup> בחי' מל' דא\"ס, והגם שגם ביצ\"מ הי' ג\"כ גילוי בחי'",[["2214","898","<b>אלפים שנה קדמה תורה לעולם</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ. מאמר ד\"ה זה תשי\"א יום ב' דחה\"ש."],["2215","899","<b>קדמה. . למעלת העולם</b>: ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ויובן כו' הני ששה ועשרים הודו על יד הערה 51. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 56. פיה\"מ יב, ג ואילך. מאמרי אדה\"א תקע\"ז ע' קלו. סה\"מ תרל\"ח ע' טז. וש\"נ."],["2216","900","<b>אאלפך חכ' אאלפך בינה</b>: ע\"פ איוב לג, ג. שבת קד, א."],["2217","901","<b>נקבה תסובב גבר</b>: ירמי' לא, כא."],["2218","902","<b>כימי צאתך מאמ\"צ</b>: מיכה ז, טו."],["2219","903","<b>וכי מזכירים יצי\"מ לע\"ל</b>: ראה ברכות יב, סע\"ב. מכילתא בא יג, ג."],["2220","904","<b>קול דודי. . ההרים. . מקפץ על הגבעות</b>: שה\"ש ב, ח."],["2221","905","<b>ההפרש</b>: להבא לקמן ראה לקו\"ת שה\"ש טו, סע\"ב ואילך. ומקרוב לסיום פיסקא זו הוא ע\"פ לשון לקו\"ת שם טו, ג בהוספות ושינויים (צויין אליו באוה\"ת שה\"ש כאן ח\"ב ע' תלו)."],["2222","906","<b>שדילוג הוא ברגל א' וקיפוץ הוא בשני רגלים</b>: אהלות פ\"ח, מ\"ה ובפיה\"מ ורע\"ב שם. ראה (בנוסף ללקו\"ת כאן) גם הנסמן במאמרי אדה\"א ויקרא ח\"א ע' רצב. במדבר ח\"א ע' מו. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 18 כותב: וע' בד\"ה ששים המה מלכות [לקו\"ת שה\"ש מב, ב] וצ\"ע."],["2223","907","<b>דעת לנבון נקל</b>: משלי יד, ו."],["2224","908","<b>והארץ הדום רגלי</b>: ישעי' סו, א."],["2225","909","<b>ויראו את אלקי ישראל</b>: משפטים כד, י."],["2226","910","<b>שיהי'</b>: בהמשך הנדפס ליתא. וכנראה שזהו טעות המעתיק."],["2227","911","<b>ובמורא גדול זה גילוי שכינה</b>: תבוא כו, ח ובספרי שם. הגדה של פסח."]]],[2000470281,"מורא גדול זהו מפני שיצ\"מ הי' הכנה למ\"ת, וית' לקמן שב' רגלים אלו הם בחי' תומ\"צ, לכן הי' לפי שעה הי'<sup data-n=\"2228\">912</sup> הגילוי מבחי' מורא גדול, ועיקר הגילוי יהי' לע\"ל כדכתי' ועמדו רגליו כו', וגם יהי' מבחי' עליונה יותר כנודע. והנה לבחי' אהבה בנקל יותר לבוא מכמו לבוא לידי גילוי בחי' היראה, כנראה בחוש שכל אדם יכול להתפעל בבחי' אהבה בזמן קטן, ולבוא לידי יראה אינו בנקל כ\"כ, והיינו מפני כי בחי' יר\"ע הוא למעלה במדריגה מבחי' אהבה כו', שאה\"ר הוא בחי' ה' עילאה ובחי' יר\"ע הוא יו\"ד<sup data-n=\"2229\">913</sup> של שם כו'.\n<b>והנה</b> נודע כי האבות נק' בשם הרים<sup data-n=\"2230\">914</sup>, והאמהות נקראו בשם גבעות<sup data-n=\"2231\">915</sup> כו', ולכאו' יפלא מפני מה מדלג על ההרים שרומז לאבות שהוא הגילוי בבחי' רגל א' לבד והיינו בחי' אהבה, ועל הגבעות שהם האמהות מקפץ שהוא הגילוי בשני הבחי' דאוי\"ר כו', ולכאו' האבות גבוהים במדריגה שהם היו משפיעים בחי' דכר, והאמהות נוק' מקבלים כו'. אך הענין דעם היות שהיו מקבלים עכ\"ז בבחי' א' היו גבוהים מהאבות והם היו משפיעים בבחי' זו, דהנה באברהם כתי' כל אשר תאמר אליך שרה שמע בקולה<sup data-n=\"2232\">916</sup> שנצטוה אברהם לקבל משרה כל אשר תשפיע לו באמרה לו כך וכך עשה וכמארז\"ל שהי' אברהם טפל לשרה בנביאות<sup data-n=\"2233\">917</sup>, וברבקה נא' טובת מראה מאד<sup data-n=\"2234\">918</sup> פי' מאד בלי גבול וכמשנ\"ת מזה לעיל<sup data-n=\"2235\">919</sup>, וכתי'<sup data-n=\"2236\">920</sup> ותרד העיינה ותמלא כדה ותעל<sup data-n=\"2237\">921</sup> ותאמר שתה וגם לגמליך<sup data-n=\"2238\">923</sup> כו' שהיתה ג\"כ משפיע, ותרד העיינה ותמלא כדה<sup data-n=\"2239\">922</sup> הוא בחי' ך\"ד ספרין דאורייתא<sup data-n=\"2240\">924</sup> שזה הי' בחי' ירידה לפניה, ויובן כ\"ז ע\"פ מארז\"ל שלשה הטעימן הקב\"ה<sup data-n=\"2241\">925</sup> מעין עוה\"ב אברהם יצחק ויעקב שנא' בהם בכל מכל כל<sup data-n=\"2242\">926</sup>, ולע\"ל כתי' נקבה תסובב גבר היינו שתתעלה בחי' המקבל למעלה מעלה מבחי' דכר המשפיע עכשיו, ותהי' א\"ח בחי' עטרה לבעלה<sup data-n=\"2243\">927</sup> כו' והיינו מפני כי סוף מעשה עלה במח' תחלה<sup data-n=\"2244\">928</sup>, ונעוץ",[["2228","912","<b>הי'. . הי'</b>: כ\"ה בכת\"י."],["2229","913","<b>שאה\"ר. . ה'. . יר\"ע הוא יו\"ד</b>: ראה זהר רע\"מ נשא קכג, סע\"א. תו\"א מקץ מ, ד ואילך. מא, סע\"ג (צויין אליו בלקו\"ת כאן). ש\"א מ, א ואילך."],["2230","914","<b>שהאבות. . הרים</b>: ראה ר\"ה יא, א. תו\"ח וארא ח\"א עז, ג. וש\"נ."],["2231","915","<b>והאמהות. . גבעות</b>: ראה ר\"ה שם. מכילתא בשלח יז, ט."],["2232","916","<b>כל אשר תאמר.. בקולה</b>: וירא כא, יב."],["2233","917","<b>שהי' אברהם טפל לשרה בנביאות</b>: תנחומא ושמו\"ר ר\"פ שמות. מדרש אגדה ורש\"י עה\"פ. ראה (בנוסף ללקו\"ת כאן) ביאוה\"ז ח\"ש יג, ב. אוה\"ת שם ע' קכא. וראה גם לקו\"ש לך כרך כה ע' 66 ואילך ובהנסמן שם."],["2234","918","<b>טובת מראה מאד</b>: ח\"ש כד, טז."],["2235","919","<b>וכמשנ\"ת מזה לעיל</b>: פט\"ו."],["2236","920","<b>וכתי'</b>: בהמשך הנדפס: וכמ\"ש."],["2237","921","<b>ותרד העיינה ותמלא כדה ותעל</b>: ח\"ש שם."],["2238","923","<b>ותאמר שתה וגם לגמלך</b>: ח\"ש שם, יח. יט [ושם: ותאמר גם]."],["2239","922","<b>ותעל. . כדה</b>: כ\"ה גם בלקו\"ת כאן בשינוי. בהמשך הנדפס ליתא. ואולי נשמט מפני תיבות הדומות: כדה. . כדה."],["2240","924","<b>ותמלא כדה. . ך\"ד ספרין דאורייתא</b>: ראה ת\"ז תכ\"א (מו, ב). תו\"א תולדות יז, ד. תו\"ח וארא פ, א. וש\"נ."],["2241","925","<b>שלשה הטעימן הקב\"ה</b>: ב\"ב טז, סע\"ב ואילך."],["2242","926","<b>בכל מכל כל</b>: ח\"ש כד, א. תולדות כז, לג. וישלח לג, יא."],["2243","927","<b>א\"ח בחי' עטרה לבעלה</b>: משלי יב, ד."],["2244","928","<b>סוף מעשה עלה במח' תחלה</b>: ע\"פ פיוט לכה דודי."]]],[2000470282,"תחלתן בסופן<sup data-n=\"2245\">929</sup> שבסוף דוקא יש כוונת נעיצת התחילה יותר מבבחי' ראש המתפשט כמ\"ש מזה במ\"א בד\"ה ועמדו רגליו על הר הזתים<sup data-n=\"2246\">930</sup> ובכ\"ד, והיינו כי שם ב\"ן שרשו למעלה משם מ\"ה<sup data-n=\"2247\">931</sup>, ומפני כי האבות הטעימן מעין עוה\"ב לכן הי' אצלם גם בחי' זו שקיבלו מהאמהות כו', והגם כי בודאי האמהות היו מקבלים מהאבות, עכ\"ז גם האבות קיבלו מהם, וכנודע שיש ב' בחי' מלמטלמ\"ע ומלמעלמ\"ט, &lt;41&gt;\nּ שמלמעלמ\"ט היינו האבות משפיעים, אבל מלמטלמ\"ע היו האמהות משפיעים בדרך או\"ח והאבות היו מקבלים כו', כי כן מדות דקדושה הם<sup data-n=\"2248\">932</sup> בבחי' נתב\"ס וסוב\"ת, ושני בחי' אלו למטה הם תורה ומצות שבבחי' א' תורה גדולה יותר וכמארז\"ל גדול תלמוד<sup data-n=\"2249\">933</sup> שמביא לידי מעשה, והיינו שע\"י בחי' חכמת התורה יודעים האיך לעשות המצוה כידוע, ואם אין עושים כן רק באופן אחר אין זו מצוה כלל, ובבחי' אחרת המצות גדולות יותר שהרי מזה עצמו מוכח ממה שאמרו גדול תלמוד שמביא לידי מעשה, שכל מעלת התלמוד הוא מפני שמביא לידי עשיית המצות, א\"כ מובן שלבסוף בחי' מעשה המצות גדול יותר<sup data-n=\"2250\">934</sup> כו', ולא המדרש עיקר אלא המעשה<sup data-n=\"2251\">935</sup>, והיינו מפני ששרש המצות הם בבחי' כת\"ר תר\"ך עמודי אור כידוע שתרי\"ג מצות דאורייתא וז' דרבנן הם תר\"ך ששרשם בבחי' הכתר, וכתי' והחכ' תחי' בעליה שעם היות שהחכ' תחי' היינו שע\"י החכ' יודעים האיך לעשות המצוה עכ\"ז המצות הם בעליה דחכ'<sup data-n=\"2252\">936</sup>, והיינו מפני כי שרשם גבוה יותר וכנ\"ל, והנה התורה נק' הר דכתי' ישאו הרים שלום, ושלום הוא בחי' תורה כמ\"ש או יחזיק במעוזי<sup data-n=\"2253\">938</sup> יעשה שלום כו' וארז\"ל כל העוסק בתורה משים שלום<sup data-n=\"2254\">939</sup> כו', וזהו מדלג על ההרים בזכות התורה, ועכ\"ז הוא רק דילוג ברגל א' בחי' אהבה לבד, מקפץ על הגבעות הם בחי' המצות כמ\"ש וגבעות בצדקה<sup data-n=\"2255\">937</sup>, וע\"י בחי' המצות מקפץ בשתי רגליו היינו ב' הבחי' דאהוי\"ר כו', והיינו מפני שהמצות שרשם למעלה יותר לכן ע\"י יוכל להיות גם גילוי בחי' היראה<sup data-n=\"2256\">940</sup> כו', ונמצא מובן כי בזאת דוקא יבא אל הקדש בחי' יר\"ע, שזהו ע\"י זאת בחי' מל'",[["2245","929","<b>ונעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז."],["2246","930","<b>שבסוף. . נעיצת התחילה. . בד\"ה ועמדו רגליו על הר הזתים</b>: סה\"מ תר\"ל ע' שכ. ראה גם סה\"מ תרל\"ח ע' רלב ובהערה 56."],["2247","931","<b>ב\"ן שרשו למעלה משם מ\"ה</b>: ראה ע\"ח שער פנימיות וחצוניות ש\"מ, ד\"ד. לקו\"ת בחוקותי מז, ג ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ו ע' קעט ואילך. מאמרי אדה\"א דברים ח\"ב ע' תקעג ואילך."],["2248","932","<b>היינו. . כן. . הם</b>: בהמשך הנדפס: היו. ֿ. כל. . הן."],["2249","933","<b>גדול תלמוד</b>: ראה קדושין מ, ב."],["2250","934","<b>מעשה המצות גדול יותר</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' שצג. וש\"נ. ש\"א נד, א."],["2251","935","<b>ולא המדרש. . המעשה</b>: אבות פ\"א, מי\"ז (כגי' אדה\"ז בסידורו)."],["2252","936","<b>המצות הם בעליה דחכ'</b>: ראה גם לקו\"ת בהעלותך לד, ד (פ\"ה)."],["2253","938","<b>או יחזיק במעוזי</b>: ישעי כז, ה."],["2254","939","<b>כל העוסק בתורה משים שלום</b>: כ\"ה בכ\"מ בדא\"ח ומהם: תו\"א בראשית ח, ב. לקו\"ת בלק עד, א (ושם מציין: סנהדרין צ\"ט ב'). שמע\"צ פד, ב (ושם מציין כנ\"ל). סהמ\"צ להצ\"צ פז, סע\"ב. אוה\"ת שמע\"צ ע' א'תשפ. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 59."],["2255","937","<b>ישאו הרים שלום. . וגבעות בצדקה</b>: תהלים עב, ג."],["2256","940","<b>היראה</b>: ע\"כ הוא ע\"פ לשון הלקו\"ת — ראה לעיל הערה 905."]]],[2000470283,"מצות המלך, ושרשם בבחי' הכתר ולכן בינה יתירה ניתנה באשה יראת ה' שעי\"ז יבא אל הקדש בחי' יר\"ע כו'.\n<b></b>קיצור. לע\"ל נקבה תסובב גבר, דילוג וקפיצה, דילוג ברגל א' אהבה, על ההרים אבות, מקפץ בשני רגלים אהוי\"ר על הגבעות אמהות, והאבות הטעימן מעין עוה\"ב לכן הי' אברהם טפל לשרה בנביאות, שמע בקולה, ובעבודה ז\"ע תורה ומצות כו'.\n(ךט) <b>ולהבין</b> מעלת ענין בחי' הקדש, וגם איך ע\"י בזאת יבא אל הקדש, דפי' קדש<sup data-n=\"2257\">941</sup> ידוע שהוא למעלה מן בחי' החכ' הנגלית בהשגה שנק' קדוש בוא\"ו<sup data-n=\"2258\">942</sup> ע\"ש ההמשכה וההתפשטות גילוי החכ' בבינה בחי' השגה והבנה, אבל בחי' קדש עילאה היינו בחי' פנימיות החכ' כח מ\"ה כלומר מה פשפשת<sup data-n=\"2259\">943</sup> כו', וע\"י היראה דוקא בא לידי מדריגת קדש עילאה בחי' ביטול במציאות ולא ע\"י האהבה כו'.\n&lt;42&gt;\nּ <b>וביאור</b> הענין יובן ע\"פ מ\"ש בזהר ח\"ג ד\"ק ע\"ב<sup data-n=\"2260\">944</sup> דזיווגא דכנס\"י במלכא קדישא הוא בזמנא דנטלא מבי אבא וכדין קרינן לה קדש, דהא מבי אבא נטלא שמא דא, וכמ\"ש אחותי בת אבי כו' ותהי לי לאשה, והענין הוא דשרש בחי' היחוד והזווג ע\"ד עבודת ה' ז\"ע שיומשך מבחי' קוב\"ה מה שהוא קדוש ומובדל ואני ה' לא שניתי<sup data-n=\"2261\">945</sup> יומשך בגילוי תוך עלמין, בנקודת הלב הגשמי שיהי' הלב הגשמי מתפעל ונמשך לדבקה בו ית', וז\"ע<sup data-n=\"2262\">946</sup> היחוד דק\"ש שאומרים שמע כו' ה' אחד<sup data-n=\"2263\">947</sup>, פי' שמע הוא לשון השמעה בלב שישים אל לבו איך שהשם אחד הוא א' ח\"ד והיינו א' בח' וד' שהם ז\"ר וארץ וד\"ר העולם<sup data-n=\"2264\">948</sup>, שהם בטלים לבחי' האלף בחי' אלופו של עולם<sup data-n=\"2265\">949</sup> ואינם תופסים מקום כלל לפי שבשכמל\"ו פי' שכל העולמות מעולם ועד עולם הם מבחי' מלכותו ית' שאינו אלא בחי' שם בלבד, כמשל השם באדם שאינו אלא לזולתו שיקראהו בשמו משא\"כ כשהוא לבדו בפ\"ע הרי השם בטל וטפל אליו ואין לו מהות בפ\"ע, כך החיות המתפשט בעולמות אינה אלא ממדת מלכותו שהוא בחי' שם להיות התפשטות מדת מלכותו על העולמות",[["2257","941","<b>דפי' קדש. . ע\"י האהבה</b>: לשון מאמרי אדה\"ז תקס\"ד ע' נ (הועתק באוה\"ת שה\"ש ח\"ב כאן ע' תלו) בהוספות ושינויים."],["2258","942","<b>קדש. . קדוש בוא\"ו</b>: ראה ביאוה\"ז אמור פ, ג. לקמן רפל\"א. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה הנה אנכי כורת ברית הערה 30."],["2259","943","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["2260","944","<b>בזהר ח\"ג ד\"ק ע\"ב</b>: בשינוי לשון[ednref_123_א]. ראה (ולהבא לקמן) גם המשך וככה תרל\"ז פכ\"ו."],["2261","945","<b>ואני ה' לא שניתי</b>: מלאכי ג, ו."],["2262","946","<b>וז\"ע</b>: לשון לקו\"ת שמע\"צ פח, ב בהוספות ושינוים."],["2263","947","<b>שמע. . אחד</b>: ואתחנן ו, ד."],["2264","948","<b>בח' וד' שהם ז\"ר וארץ וד\"ר העולם</b>: נסמן לעיל במאמר ד\"ה סמוכים לעד הערה 50."],["2265","949","<b>אלופו של עולם</b>: לשון ב\"ר פ\"כ, ב.\n\n[edn_123_א] ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וביום הביכורים ובהערות 37-38."]]],[2000470284,"שיהי' מלך שמו נקרא עליהם<sup data-n=\"2266\">950</sup>, אבל לגבי אוא\"ס ב\"ה בכבודו ובעצמו אינו תופס מקום כלל וכמו קודם שנבה\"ע שהי' הוא ושמו בלבד<sup data-n=\"2267\">952</sup>, ולפיכך ואהבת את ה' שיהי' בבחי' אלקיך שיהי'<sup data-n=\"2268\">951</sup> אלקה שלך<sup data-n=\"2269\">953</sup> שתהא בטל אליו בכל לבבך פי' שיהי' המשכת בחי' גילוי אלקותו ית' בתוך לבבך<sup data-n=\"2270\">954</sup>, כי ב' השימוש של בכל לבבך הוא פי' בתוך דהיינו להיות בטל רצונך מפני רצונו<sup data-n=\"2271\">955</sup>, ופי' לבבך ביצ\"ט וביצה\"ר<sup data-n=\"2272\">956</sup> לאכפיי' לסט\"א ולהיות את הטפל להוי'<sup data-n=\"2273\">957</sup> כו', וזה כל האדם<sup data-n=\"2274\">958</sup> שלא נברא אלא בשביל זה, וכל ימי שנותינו בהם<sup data-n=\"2275\">959</sup> שבעים שנה ושמונים שנה ואח\"כ כיון דאיפלג איפלג<sup data-n=\"2276\">960</sup>, הוא כדי להמשיך גילוי אלקותו ית' למטה בתוך לבבינו בכ\"י מעט מעט עד שיתהפך מן הקצה אל הקצה, להטות לבבינו אליו ית' שיהי' הלב הגשמי דוקא מתפעל ונמשך לדבקה בו כי הנשמה א\"צ תיקון<sup data-n=\"2277\">961</sup> כלל, ולא ירדה אלא לתקן הנה\"ב והגוף, וזהו שא' ימי שנותינו בהם, בהם אותיות בהמה<sup data-n=\"2278\">962</sup> היינו בשביל בירור נה\"ב והגוף שיהי' לבי ובשרי ירננו<sup data-n=\"2279\">963</sup> אל אל חי, וז\"ע יחוד קוב\"ה ושכינתי'<sup data-n=\"2280\">964</sup> קוב\"ה הוא קדוש ומובדל, ושכינתי' היינו הארתו שמאיר ומתלבש בעולמות והיינו שיהי' השראת קדושתו שהוא קדוש ומובדל כו' ואני ה' לא שניתי בגילוי תוך עלמין בנקודת הלב הגשמי<sup data-n=\"2281\">965</sup>, וע\"י אתעדל\"ת זו נמשך אתעדל\"ע להיות ברכה והמשכה בגילוי כמ\"ש בלק\"ת בד\"ה ואתחנן ספ\"ב ובקיצור אות הנ\"ל, וע' בביאור\n&lt;43&gt;\nּ כ\"י אאזמו\"ר ז\"ל<sup data-n=\"2282\">967</sup> ע\"פ הוי' לי בעוזרי שכ' כי הארת הקו וחוט נק' שכינה לגבי עצמיות אוא\"ס עכ\"ל<sup data-n=\"2283\">966</sup>, ונמצא כי עי\"ז נמשך תוס' וריבוי אור מאוא\"ס שלפני הצמצום בבחי' הקו וחוט כו'.",[["2266","950","<b>מלך שמו נקרא עליהם</b>: ראה פיוט אדון עולם. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 16."],["2267","952","<b>קודם. . ושמו בלבד</b>: ראה פדר\"א פ\"ג. תו\"ח וארא ח\"א נג, ב הערה 6."],["2268","951","<b>מקום. . שיהי'</b>: תיבת ”מקום\" הנה בהמשך הנדפס ליתא. וכנראה טעות המעתיק. ובלקו\"ת כבפנים. תיבת ”שיהי'\" בלקו\"ת ובהמשך הנדפס: שיהא."],["2269","953","<b>ה'. . אלקיך שיהי' אלוקה שלך</b>: ראה גם תו\"א תצוה פב, רע\"ג. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמכוני ובהערה 11."],["2270","954","<b>בכל לבבך. . בתוך לבבך</b>: ראה גם לקו\"ת כאן פח, ג. מאמרי אדה\"ז תקס\"ד ע' רל. מאמרי אדה\"א הנחות תקע\"ז ע' שסד. דברים ח\"ד ע' א'תקו. המשך וככה תרל\"ז פכ\"ו ע' לג."],["2271","955","<b>בטל רצונך מפני רצונו</b>: אבות פ\"ב, מ\"ד."],["2272","956","<b>לבבך ביצ\"ט וביצה\"ר</b>: נסמן לעיל בהמשך זאת חנוכת המזבח הערה 18."],["2273","957","<b>את הטפל להוי'</b>: ראה ברכות לו, ב. ועוד. ראה גם לקו\"ת ואתחנן ז, ד."],["2274","958","<b>וזה כל האדם</b>: ע\"פ קהלת יב, יג."],["2275","959","<b>ימי שנותינו בהם</b>: ע\"פ תהלים צ, י. ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי רפכ\"ג. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ובחודש השביעי הב' על יד הערה 68. סה\"מ תרל\"ח ע' רכב. וש\"נ."],["2276","960","<b>כיון דאיפלג איפלג</b>: גיטין כח, א."],["2277","961","<b>הנשמה א\"צ תיקון</b>: ראה תניא פל\"ז (מח, ב). ש\"א ט, א הערה 4."],["2278","962","<b>בהם אותיות בהמה</b>: ראה גם סה\"מ תרל\"ח ע' רכב וע' תלג."],["2279","963","<b>לבי ובשרי ירננו</b>: תהלים פד, ג."],["2280","964","<b>יחוד קוב\"ה ושכינתי'</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה הנה אנכי כורת ברית ובהערה 26."],["2281","965","<b>הגשמי</b>: ע\"כ לשון הלקו\"ת בהוספות ושינוים — ראה לעיל הערה 946."],["2282","967","<b>בביאור כ\"י אאזמו\"ר ז\"ל</b>: מאמרי אדה\"ז תקס\"ד ע' רלה. ראה המשך וככה תרל\"ז פכ\"ז."],["2283","966","<b>וע\"י. . עכ\"ל</b>: לשון ביאוה\"ז להצ\"צ כרך ב' ע' תתקסג בשינויים."]]],[2000470285,"<b></b>קיצור. ענין היחוד בעבודה שיומשך מבחי' קוב\"ה מה שהוא קדוש ומובדל יומשך בגילוי תוך הלב הגשמי, וע\"י אתעדל\"ת זו נמשך יחוד קוב\"ה ושכינתי', ובחי' הארת הק\"ו נק' שכינה לגבי עצמיות אוא\"ס.\n(למ\"ד) והנה נודע כי בחי' החכמה נק' קדש, וכמ\"ש בזח\"ג אמור דצ\"ד ע\"ב בענין קדש מלה בגרמה היא, והיינו שאפי' אם לא הי' בורא כל העולמות כלל הי' שייך בחי' חכים ולא בחכ' ידיעא, משא\"כ בחי' המדות דחו\"ג אינם שייך אא\"כ יש זולת<sup data-n=\"2284\">969</sup>, והיינו ענין הנבראים, וכעין זה כמדומה שפי' בפרד\"ס<sup data-n=\"2285\">970</sup> במעלת ג\"ר על ז\"ת<sup data-n=\"2286\">968</sup>, ומבשרי אחזה שענין היות האדם חסדן או רחמן לא יתכן כ\"א כשיש על מי להתחסד או להתרחם, ובלתי זאת מתבטל כל ענין מדות אלו, שלא יתכן לומר שמתחסד על עצמו או שמרחם על עצמו, והגם כי ענין השפעת החסד או הרחמים ה\"ז פעולת המדה ולא עצם המדה כו', מ\"מ כאשר לא יש פעולת המדה עם היות שיכול להיות עצם המדה, אמנם מפני העדר פעולתה איננה ניכרת כלל, שהרי בלתי ההשפעה או מה שמדבר בעניני השפעה שג\"ז מוכרח להיות לזולת בשביל זולתו, אינו ניכר כלל בין מי שהוא ותרן גדול, ובין מי שהוא כילי ביותר, ונמצא שבהעדר הזולת שלא יש פעולת המדות ה\"ז כאלו המדה עצמה לא הי' ולא נברא כלל, משא\"כ בבחי' החכ' שאינו מוכרח כלל לומר שכשלא יש למי להשפיע אזי אינו משכיל כלל, שלא כן הוא שהרי יכול לישב בדד יחידי ולהשכיל השכלות גדולות ועצומות, ועם היות שמתלמידי יותר מכולם, באמת א\"ז דבר חדש לגמרי כ\"א שע\"י הדבור מאיר ממקור השכל יתרון בגילוי השכל שז\"ע בינה יתירה שיש באשה בחי' הדבור כנ\"ל<sup data-n=\"2287\">*971</sup>, אבל בענין ההשכלה הלא מצינו בגדולי הראשונים שהיו מתבודדי'<sup data-n=\"2288\">971</sup> בכדי להשכיל ולהתבונן בהתבוננות בגדולת ה', וכמו שהשבטים היו רועי צאן<sup data-n=\"2289\">972</sup> והיו יושבין בשדות בכדי שלא יבלבלו להם התקשרות השכל ורעו\"ד לאלקות כו', וכמו שמצינו ברשב\"י שבהיותו יושב יחידי רק עם בנו ר\"א<sup data-n=\"2290\">973</sup> במערה ניתוסף לו חכמה על חכמתו בלימוד תורתו עד שמתחלה כשהי'",[["2284","969","<b>המדות. . אא\"כ יש זולת</b>: ראה גם אוצרות חיים בתחלתו. הובא בלקו\"ת מסעי צג, רע\"א. סה\"מ תרל\"ב ח\"א ע' צ. וש\"נ. תרל\"ח ס\"ע שצ. וש\"נ. המשך וככה תרל\"ז פכ\"ח. לקמן ח\"ב (בחלק המאמרים) המשך יונתי הערה 261."],["2285","970","<b>כמדומה שפי' בפרד\"ס</b>: כ\"ה גם בביאוה\"ז כאן. באוה\"ת שבועות ע' פו[ednref_124_ב] מציין: בספר אור נערב להרמ\"ק בחלק ששי רפ\"ג (ומעתיק לשונו בשינוי). בהמשך וככה כאן: כמבואר בפרד\"ס. בסה\"מ תרל\"ב ח\"א ריש ע' קלה מציין: ופי' בפרד\"ס ש\"ח פט\"ו. תרע\"ח ע' רעו."],["2286","968","<b>והנה. . ז\"ת</b>: לשון ביאוה\"ז להצ\"צ כרך ב' ע' תתקסג בשינויים."],["2287","*971","<b>בחי' הדיבור כנ\"ל</b>: פי\"ז."],["2288","971","<b>בגדולי הראשונים שהיו מתבודדי'</b>: ראה גם לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה לכל תכלה ראיתי קץ ובהערה 25."],["2289","972","<b>שהשבטים היו רועי צאן</b>: וישב לז, ב. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' קצב. תקע\"א ע' פח. סה\"מ תרכ\"ט ע' קעב. וש\"נ. ע' רפא. וש\"נ."],["2290","973","<b>ברשב\"י. . עם בנו ר\"א</b>: ראה שבת לג, ב. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 30. סה\"מ תרל\"ח ע' יד וע' תקיח. וש\"נ. עטר\"ת ע' תז. ש\"ת ע' 82. מאמר ד\"ה בכ\"ה בכסלו יומי דחנוכה ש\"מ טבת תשח\"י.\n\n[edn_124_ב] נדפס גם באוה\"ת פינחס ע' א'קצג."]]],[2000470286,"מקשה מרפב\"י הי' רפב\"י מתרץ כו', ואחר ישיבתו במערה כשהי' רפב\"י מקשה הי' רשב\"י מתרץ כו', הרי ניתוסף לו חכ' יתירה גם כשלא הי' לו לפני מי להשפיע, וכמו שמצינו בסנהדרין כשהיו נושאים ונותנים יש<sup data-n=\"2291\">975</sup> בזה מחלוקת &lt;44&gt;\nּ רש\"י והרמב\"ם<sup data-n=\"2292\">974</sup> אם כל א' לעצמו או עם בן זוגו ולא ע\"ד השפעה לזולתו, אלא שבחי' החכ' אינו מוכרח כשיש זולת דוקא כ\"א גם בינו לבין עצמו הוא ג\"כ שייך, ועד\"ז יובן למעלה שבחי' המדות הוא כשיש זולת דהיינו כשנבראו הנבראים, וכמ\"ש בע\"ח כשעלה ברצונו<sup data-n=\"2293\">976</sup> כו' מצד טבע הטוב<sup data-n=\"2294\">977</sup> להטיב<sup data-n=\"2295\">978</sup> שבשביל השפעת המדה נאצלו הנאצלים ונבראו הנבראים ונוצרו היצורים ונעשו הנעשים, כי מבלעדי אבי\"ע לא יתכן כלל ענין מדת הטוב כו', אבל חכ' קדש מלה בגרמי' גם כשלא היו הנבראים כלל, וכמארז\"ל אלפים שנה קדמה תורה לעולם שגם כשלא נבה\"ע כלל הי' חכמת התורה כו', ונמצא שקריאת החכ' בשם קדש להיותה מובדל לגמרי מבחי' הזולת, וכמו שקדש פירושו מובדל<sup data-n=\"2296\">979</sup> כמ\"ש ויבדל אהרן להקדישו<sup data-n=\"2297\">980</sup> קדש קדשים כך החכ' היא למעלה מהשגה אשר אין נתפס ואין מושג כלל רק מאיר למעלה משכלו ובינתו ומאין תמצא כו' ועש\"ז נק' החכ' ג\"כ אין<sup data-n=\"2298\">981</sup> כמ\"ש בכ\"ד, ולכאו' צ\"ל שממ\"ש מאין תמצא יובן שהחכ' אינו אין אלא שהיא תמצא מאין, אך הענין הוא שלשון תמצא אינו נופל כ\"א כשלא נשתנית כלל מהמקור, ועד\"מ המוצא מציאה שחייב להכריז<sup data-n=\"2299\">982</sup> שענין ההכרזה הוא בכדי שמי שנאבד אצלו דבר זה יאמר סימנים<sup data-n=\"2300\">983</sup> שהוא שלו שהסימנים מוכיחים שדבר זה הי' אצלו תחילה והיא שלו שאל\"כ לא הי' חייב להחזיר לו כלל, ועד\"ז הוא בענין החכ' שאומרו שהיא מאין תמצא לשון מציאה מובן שלא נשתנית כלל מכמו היותה תחילה בבחי' האין הממציא החכ' אלא שנתגלה ויצא מאין שאינו מושג כלל כמו שלא נודע מחפץ המציאה קודם שנאבדה אצל בעל האבידה ובאה לידי גילוי המוצא המציאה ע\"י שאבדה, רק שבמשל הרי בא זה לידי",[["2291","975","<b>יש</b>: בהמשך הנדפס: אי'."],["2292","974","<b>בסנהדרין. . מחלוקת רש\"י והרמב\"ם</b>: רש\"י סנהדרין מ, א ד\"ה כל הלילה: איש איש לעצמו. רמב\"ם הל' סנהדרין פי\"ב ה\"ג: כל אחד ואחד עם זוג שלו או עם עצמו בביתו. ראה גם סה\"מ תרל\"ח ע' יד. וש\"נ."],["2293","976","<b>וכמ\"ש בע\"ח כשעלה ברצונו</b>: שער הכללים בתחילתו. ראה דרוש עגו\"י ש\"א, ענף ב."],["2294","977","<b>וכמ\"ש בע\"ח. . טבע הטוב להטיב</b>: כ\"ה בכ\"מ ומהם: לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וירא העם וינועו כאן על יד הערה 99. מאמרי אדה\"א קונטרסים ע' ה. וש\"נ. תורת חיים שמות ח\"א לד, ג הערה 375. סה\"מ תרל\"ח ע' מח. וש\"נ."],["2295","978","<b>טבע הטוב להטיב</b>: ראה עמק המלך שער שעשועי המלך בתחילתו. שומר אמונים ויכוח שני סי\"ד. שער היחוה\"א פ\"ד ובמ\"מ הגהות והע\"ק לשם. ולהעיר משו\"ת חכם צבי סי\"ח."],["2296","979","<b>שקדש פירושו מובדל</b>: ראה תניא פמ\"ו (סו, א). תו\"ח וארא ח\"א נא, ד ובהערה 10."],["2297","980","<b>ויבדל אהרן להקדישו</b>: דבהי\"א כג, יג. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויהי הענן והחשך על יד הערה 36."],["2298","981","<b>נק' החכ' ג\"כ אין</b>: ראה ספר המאמרים תרל\"ח ע' רכז. וש\"נ. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וירא העם וינועו בסופו. ד\"ה וביום הביכורים על יד הערה 12 (בחלק ההנחות) ד\"ה וביום הביכורים על יד הערה 17."],["2299","982","<b>המוצא מציאה שחייב להכריז</b>: ב\"מ רפ\"ב."],["2300","983","<b>יאמר סימנים</b>: ראה שם כז, א ואילך."]]],[2000470287,"השגה גמורה ובבחי' החכ' היא רק בבחי' ברק המבריק<sup data-n=\"2301\">984</sup> לבד מפני שהיא עדיין למעלה מהשגה כו', ולכן היא עדיין ג\"כ בחי' אין כו'.\n<b></b>קיצור. שקדש היא בחי' חכמה כי קדש לשון מובדל וכן חכ' עילאה היא למעלה מגדר השגה, ולכן נק' אין כו'.\n(וזהו שתורה קדמה לעולם להיותה מבחי' חכ' שאינה שייכה לעולם, ולכן כאשר ניתנה תורה חרדו כל העם וינועו מפני גודל הפחד נזדעזעו, שז\"ע וירא העם<sup data-n=\"2302\">986</sup> וינועו ל' זיע<sup data-n=\"2303\">987</sup> כמו שפי' רש\"י בחומש)<sup data-n=\"2304\">985</sup>.",[["2301","984","<b>ברק המבריק</b>: ראה גם בענין ברק המבריק לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 21."],["2302","986","<b>וירא העם</b>: בהמשך הנדפס: וירא כל העם."],["2303","987","<b>זיע</b>: שם: זיעה(!). ולהעיר מלקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה (זה) וירא העם וינועו בראשו ובסופו (ללא קשר לרש\"י)."],["2304","985","<b>(וזהו. . בחומש)</b>: ראה לעיל הערה 895."]]],[2000470288,"<h3>וביום הביכורים כו' והנה כאשר נמשך</h3>\n<b></b><b>בס\"ד יום א' דחגה\"ש אחר התפלה</b>\n(לא-גל)\nא' דחה\"ש\n<b>(וביום</b> הביכורים<sup data-n=\"2305\">988</sup> בהקריבכם מנחה חדשה כו' מקרא קדש<sup data-n=\"2306\">989</sup>, מנחה חדשה זו היא מנחת ביכורי קציר חטים<sup data-n=\"2307\">990</sup> שהם שתי הלחם דכתי' בהם חמץ תאפינה<sup data-n=\"2308\">991</sup>. &lt;45&gt;\nּ וצ\"ל מפני מה מנחה זו באה חמץ דוקא וכמארז\"ל כל המנחות<sup data-n=\"2309\">992</sup> כו' חוץ מחמץ שבתודה<sup data-n=\"2310\">993</sup> ושתי הלחם שבאו חמץ, ויובן בהקדם ההפרש בין שבת",[["2305","988","<b>וביום הביכורים</b>: מכאן מתחיל מאמר היו\"ד מהמשך מצה זו (הכולל פרקים לא-גל).\nהפתיחה וכן סיום המאמר באים בסוגרים — אולי ניתוספו לאחרי כתיבת המאמר.\nפל\"א — לשון ביאוה\"ז להצ\"צ כרך ב' ע' תתקסג בהוספות ובשינויים. ראה גם ביאוה\"ז כרך א ע' תכא ואילך. המשך וככה תרל\"ז פכ\"ט ואילך.\nפל\"ב — לשון ביאוה\"ז להצ\"צ כרך ב' ע' תתקסה בהוספות ובשינויים. ראה גם ביאוה\"ז כרך א ע' תכג ואילך. המשך וככה תרל\"ז פל\"ז.\nפרק ג\"ל — לשון ביאוה\"ז להצ\"צ כרך ב' ע' תתקסה ואילך בהוספות ובשינויים. ראה גם ביאוה\"ז כרך א ע' תכד ואילך. המשך וככה תרל\"ז פל\"ז.\nהתחלת הפרק מובא בסה\"מ תרנ\"א ע' ד ואילך.\nממאמר זה ישנם עוד שני הנחות והם: א) הנחת<sup data-n=\"e125\">*</sup> כ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן (בחלק הנחותיו). ב) הנחה אחרת נדפסה לקמן (בחלק ההנחות).\nבהכותרת המופיע בריש המאמר הנה תיבת: ”בס\"ד\" נעתקה מהמשך הנדפס. והתיבות: ”יום א' ד\" ”אחר התפלה\" ניתוספו מהנחת כ\"ק אדמו\"ר מהורש\"ב."],["2306","989","<b>וביום הביכורים. . מקרא קדש</b>: פינחס כח, כו. ראה מנחות פד, ב."],["2307","990","<b>ביכורי קציר חטים</b>: תשא לד, כב."],["2308","991","<b>חמץ תאפינה</b>: אמור כג, יז."],["2309","992","<b>כל המנחות</b>: ראה מנחות נב, ב (במשנה)."],["2310","993","<b>שבתודה</b>: בהמשך הנדפס שבו תודה. וכנראה שזהו טעות המעתיק."],["e125","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470289,"ליו\"ט<sup data-n=\"2311\">994</sup>, שהשבת נק' קדש, כמ\"ש ושמרתם את השבת<sup data-n=\"2312\">995</sup> כי קדש היא, ויו\"ט נק' מקרא קדש, כמ\"ש מקרא קדש יהי' לכם<sup data-n=\"2313\">996</sup>, הנה קדש היא מלה בגרמה היא בחי' והחכ' מאין תמצא שנת\"ל שגם אחר שנמצאת מאין היא ג\"כ אין ).\n(לא) <b>והנה</b> כאשר<sup data-n=\"2314\">997</sup> נמשך הארה מועטת ע\"י חלון בחי' יסו\"א, וע' מענין חלון בפרד\"ס<sup data-n=\"2315\">998</sup> ערך חלון<sup data-n=\"2316\">999</sup> ובמאו\"א אות ח' סעי' ס\"ה כ' חלון נק' היסוד של כל ספירה<sup data-n=\"2317\">1000</sup> עכ\"ל. א\"כ מובן שהארה הנמשך מבחי' חכ' נק' בשם חלון שזהו ההשפעה הנשפע מבחי' יסו\"א, והוא בחי' יו\"ד, ואח\"כ כאשר בא שפע זו להיות בגדר המשכה ומשפיע בבינה נעשה מן יו\"ד וא\"ו, היינו שהארה מועטת הנ\"ל נמשך בבינה שיהי' מבין עצם ההשכלה כי החכ' היא בחי' אין כנ\"ל וא\"א להשיגה ולהבינה רק ההארה הנשפע בחי' יו\"ד ההשפעה שדרך חלון שזהו בגדר המשכה הנה זה בא בבינה בבחי' הרחבה, ולכן נק' בינה קדוש בוא\"ו, וכנודע שתמונת וא\"ו הוא קו שבראשו יו\"ד<sup data-n=\"2318\">1001</sup>, והוא אשר מבחי' יו\"ד נמשך איזה המשכה משם, ולא כפי עצמיות היו\"ד היינו בחי' עצם ההשכלה כמו שהוא בבחי' היו\"ד שע\"ז מורה הקו של הוא\"ו רק שבראשו יו\"ד שבא מבחי' היו\"ד כו'.\n<b>והנה</b> קוטב דרוש זה הוא לפי משנ\"ת במ\"א דבחי' אבי\"ע שבאצי' הנה החכ' היא בחי' אצי' שבאצי', והבינה היא בחי' בריאה<sup data-n=\"2319\">1002</sup> שבאצי', וז\"א הוא בחי' יצי' שבאצי' ומל' היא בחי' עשייה שבאצי', ובחי' א\"א הוא למעלה מאבי\"ע שבאצי', אלא כענין שיש ד\"י ארמ\"ע<sup data-n=\"2320\">1005</sup> ויש בחי'<sup data-n=\"2321\">1006</sup> היולי<sup data-n=\"2322\">1003</sup> שכולל כולם<sup data-n=\"2323\">1004</sup>, והוא מקור",[["2311","994","<b>ההפרש בין שבת ליו\"ט</b>: ראה פע\"ח שער מקראי קדש ש\"כ, פ\"א. לקו\"ת צו יב, א. סידור שער המועדים ריז, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשנח. המשך וככה תרל\"ז רפכ\"ו. לקו\"ש שמיני כרך לב ע' 64 ובהערה 47. ובאגרותיו ח\"ב ע' קכט ואילך. חכ\"א ע' נו."],["2312","995","<b>ושמרתם את השבת</b>: תשא לא, יד."],["2313","996","<b>מקרא קדש יהי' לכם</b>: בא יב, טז. אמור כג, ז ואילך. בריש המאמר כאן."],["2314","997","<b>והנה כאשר</b>: מכאן לשון ביאוה\"ז להצ\"צ כרך ב' ע' תתקסג בהוספות ובשינויים. ראה גם ביאוה\"ז כרך א ע' תכא ואילך. המשך וככה תרל\"ז פכ\"ט ואילך."],["2315","998","<b>חלון בחי' יסו\"א וע' מענין חלון בפרד\"ס</b>: ועד\"ז בביאוה\"ז כאן. ראה גם אוה\"ת על ענינים ס\"ע קפז ואילך. סה\"מ תרנ\"ח ע' ח. אבל בהמשך וככה כאן: חלון הוא בחי' יסו\"א כמ\"ש בפרד\"ס."],["2316","999","<b>בפרד\"ס ערך חלון</b>: ראה שם שער כ\"ג שער ערכי הכנויים פ\"ח."],["2317","1000","<b>ספירה</b>: במאו\"א שם: הספירה וכ\"ה בביאוה\"ז כאן. אבל בהמצויין לעיל בהערה 998 כבפנים. וראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 15 שמציין לע\"ח (הובא ביאיר נתיב למאו\"א שם)."],["2318","1001","<b>וא\"ו. . שבראשו יו\"ד</b>: ראה תו\"א בראשית ג, ג. מאמרי אדה\"א דברים ח\"ב ע' תרעח. וש\"נ. תו\"ח בשלח ח\"א קנ, ג. וש\"נ."],["2319","1002","<b>אבי\"ע. . החכ'. . אצי' שבאצי' והבינה. ֿ. בריאה</b>: ראה (בנוסף ללקו\"ת המצויין בפנים) לקו\"ת סוכות פ, ב. אוה\"ת וארא ע' קנ. תשא ע' ב'פא. פ' ראה ע' תרסו. (יהל אור) תהלים ע' שצז. ביאוה\"ז להצ\"צ כרך ב ע' תתסב. המשך תרס\"ו ע' תנז. ע' תפו. ע' תקד. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה להבין שרש ענין מקיפים דבינה על יד הערה 15."],["2320","1005","<b>ד\"י ארמ\"ע</b>: ראה שה\"א סו, א ובהערה 17. סה\"מ תרכ\"ט ע' קעט. וש\"נ. תרל\"ח ע' תצא."],["2321","1006","<b>בחי' היולי</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. שער קיצור אבי\"ע ש\"נ, פ\"י. תו\"ח תשא ח\"ב שפד, ד הערה 48. מכתב ה' מ\"ח תש\"י נדפס באג\"ק ח\"ג ע' רו."],["2322","1003","<b>א\"א. . היולי</b>: ראה אוה\"ת בשלח ע' תרפה. אחרי ע' תקנו. ואתחנן ע' רכח. סה\"מ תרס\"ה ריש ע' רסד."],["2323","1004","<b>ד\"י. . היולי שכולל כולם</b>: ראה אוה\"ת שמות ע' מה. בשלח ע' שצג. ע' שצה."]]],[2000470290,"לד\"י הנ\"ל, וכן משמע בלק\"ת סד\"ה ששים המה מלכות דל\"ט ע\"ג בשם ע\"ח שער מ\"ז פ\"ג<sup data-n=\"2324\">1007</sup> וז\"ל<sup data-n=\"2325\">1008</sup> דכל עיקר ענין המסך שבין אצי' לבריאה ז\"ע שהבינה דאצי' מלבשת התלבשות גמור להחכ' והיא בחי' מסך מבדיל בין א\"ס וחכמה אל בריאה כו' עכ\"ל. לכן לפ\"ז הרי כמו שהאצי' גבוה הרבה מהבריאה, כך הוא גבוה בחי' אבא מבחי' אימא<sup data-n=\"2326\">1009</sup> כו', ולכן עצמיות בחי' אבא אינו מאיר בבינה רק הארה לבד הוא שמאיר מאבא לאימא ע\"י בחי' חלון שהוא יסוד דאבא כו'.\n<b>אמנם</b> בביאור ע\"פ ושננתם לבניך<sup data-n=\"2327\">1010</sup> משמע שהכתר הוא אצי' שבאצי' וחכ' היא בריאה שבאצי', וכ\"מ בד\"ה את שבתותי תשמרו שבלק\"ת פ' בהר<sup data-n=\"2328\">1011</sup> בענין בורא קדושים ישתבח שמך, וכ\"כ הרמ\"ז פ' ויצא בדף ק\"נ<sup data-n=\"2329\">1012</sup>, וכ\"כ עוד ס\"פ קרח<sup data-n=\"2330\">1013</sup>, אבל עכ\"ז כאן הולך ע\"ד הנ\"ל דאבא הוא אצי' שבאצי' ובינה הוא בריאה שבאצי', וכמדומה שכן<sup data-n=\"2331\">1014</sup> האריך בס' אשל אברהם<sup data-n=\"2332\">1015</sup>, ואל\"ב<sup data-n=\"2333\">1016</sup>.\n<b>וענין</b> בחי' ההארה &lt;46&gt;\nּ שנמשך מאבא לאימא היא רק שנמשך ממנה השכלה כמו שמסביר אחד איזה דבר קטן נקודה אחרונה שבשכלו לתלמיד ובודאי מובן מאליו אשר גם הנקודה קטנה שבשכלו אינו מבין התלמיד כמו שמבין הרב, רק המשכה והארה מנקודה הקטנה נמשך ומאיר בשכל התלמיד, ולבעבור זה נק' קדוש בוא\"ו היינו שמקבלת בהרחבה המשכה מהארת נקודה קטנה של בחי' קדש, וע' מענין ב' בחי' נקודה בביאור מאה\"ז<sup data-n=\"2334\">1017</sup> בלק דף קצ\"ג ע\"פ אודה שמך כי עשית פלא, שנקודה א' היא בחי'<sup data-n=\"2335\">1018</sup> יסו\"א שמאיר בבינה, ונקודה עילאה סתימאה זהו כמו",[["2324","1007","<b>ע\"ח. . פ\"ג</b>: בדפו\"א פ\"ב. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 20 בשם הפע\"ח."],["2325","1008","<b>וז\"ל</b>: של הלקו\"ת. הובא גם באוה\"ת (יהל אור) תהלים ע' שצז."],["2326","1009","<b>כמו שהאצי'. . כך. . אבא מבחי' אימא</b>: ראה לקו\"ת סוכות פ, ב. המשך וככה תרל\"ז פ\"ה."],["2327","1010","<b>בביאור ע\"פ ושננתם לבניך</b>: מאמרי אדה\"ז תקס\"ז ע' שיא. ראה גם אוה\"ת ואתחנן ע' רפה. ע' רצו ואילך. המשך תרס\"ו ע' מא. ע' תפו. בהבא לקמן ראה גם המשך וככה תרל\"ז פל\"ה."],["2328","1011","<b>בד\"ה את שבתותי תשמרו שבלק\"ת פ' בהר</b>: מא, ד."],["2329","1012","<b>וכ\"כ הרמ\"ז בפ' ויצא בדף ק\"נ</b>: ע\"א ד\"ה חמא."],["2330","1013","<b>וכ\"כ עוד בס\"פ קרח</b>: באוה\"ת ואתחנן ריש ע' רצז: הרמ\"ז ר\"פ קרח — קעו, ב."],["2331","1014","<b>וכמדומה שכן</b>: לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 25: וכ\"ה. בהמשך וככה שם: וכן. לקמן (בחלק ההנחות) כאן על יד הערה 40: וכן משמע."],["2332","1015","<b>בס' אשל אברהם</b>: — לר' מרדכי אשכנזי[ednref_126_א] פיורדא תס\"א — ראה ביאוה\"ז להצ\"צ כרך א וירא ריש ע' סה: ובסידור מוהר\"ר יעקב קאפיל ז\"ל בהקדמה. . בשם אשל אברהם[ednref_127_ב] שהכתר הוא אצי' וחו\"ב בריאה."],["2333","1016","<b>ואל\"ב</b>: ואין להאריך בזה? בביאוה\"ז כאן: ואין להאריך כאן. אבל בהמשך וככה שם כבפנים."],["2334","1017","<b>ב' בחי' נקודה בביאור מאה\"ז. . פ\"ד</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' רצו ואילך. ביאוה\"ז בלק להצ\"צ כרך א ע' תקיח ואילך. (ראה גם המשך וככה תרל\"ז פל\"ה)."],["2335","1018","<b>היא בחי'</b>: בהמשך הנדפס: הוא בבחי'.\n\n[edn_126_א] מתלמידי הרמ\"ז — אוה\"ת שה\"ש כרך ג ע' תתי.\n\n[edn_127_ב] ראה שם סוד ארבע דרגין קדישין ח, א ואילך."]]],[2000470291,"שהחכ' מקבל מהכתר, וגם בח\"ס שייך לומר כן ע\"ש פ\"ד, וי\"ל שלכן נק' החכ' אין כו', וכאשר בבינה מתקבל בבחי' הרחבה עז\"נ להנחיל אוהבי יש, ש\"י עולמות<sup data-n=\"2336\">1019</sup>, וזהו שרש ההפרש בין שבת ליו\"ט שהשבת נק' קדש כמ\"ש ושמרתם את השבת כי קדש היא, ויו\"ט נק' מקרא קדש, כי מה שהשבת נק' קדש שהוא לשון מובדל לפי שענין השבת הוא בחי' עליות העולמות למעלה מעלה כמו למשל כאשר אדם עוסק במלאכתו בכתיבה עד\"מ וכדומה אז יורדים ומתפשטי' כחות נפשו ונתצמצם בעסק דבר מעשה ההוא, וכאשר שובת ממלאכתו אז חוזרים כחותיו למקורם ושרשם ונכללי' שם ושובת ממה שירדו כחותיו למטה תחלה, ולכן בשבת נא' וישבות ביום השביעי<sup data-n=\"2337\">1020</sup>, והיינו כי כל ימי המעשה נמשך וירד מאתו ממקורו בחי' הבל<sup data-n=\"2338\">1021</sup> לעשרה מאמרות יהי אור<sup data-n=\"2339\">1022</sup> כו' וביום השביעי שבת ממלאכתו ונתעלו כל העולמות לשרשן, לכן שבת נק' קדש למעלה מגדר המשכה, ואז זווגא דכנס\"י במלכא קדישא<sup data-n=\"2340\">1023</sup> היינו להוליד נשמות חדשות דכתי' אין כל חדש תחת השמש, בקהלת סי' י\"א ט'<sup data-n=\"2341\">1024</sup>, כי אחר ההשתלשלות אין כל חדש רק לחזק הישינות אחר שכבר בא בגדר ההשתלשלו' אורות בכלים א\"כ אין כל חדש רק לחזק כו', אבל בשבת כשחוזר ונתעלה לשרשו למעלה, אז נמשך ומתגלה הארה אורות נשמות חדשות<sup data-n=\"2342\">1025</sup>, וזהו שלמעלה מן השמש יש חדשות והיינו בחי' נשמות חדשות.\n<b>והרמ\"ז</b> ר\"פ בהעלותך דקמ\"ח ע\"ב כ' בד\"ה והוא שמשא כו'<sup data-n=\"2343\">1026</sup> וז\"ל נודע שאור הגנוז הוא בחי'<sup data-n=\"2344\">1027</sup> פנימיות יסוד אבא דכתי' בי' ופני לא יראו<sup data-n=\"2345\">1028</sup>, אבל הארת<sup data-n=\"2346\">1029</sup> יסודו שמאירות בתוך<sup data-n=\"2347\">1030</sup> זעיר ה\"ס השמש, באופן שמה שתמצא בזהר ובדברי הקדמונים שהתפארת ה\"ס השמש ירצה לומר אור זעיר שמצד אבא, והוא מאיר לכל דכתי' כולם בחכ' עשית<sup data-n=\"2348\">1031</sup> עכ\"ל. וא\"כ צ\"ל משנ\"ת שכשמקבל מבחי' חכ' יש כל חדש לחדש נשמות חדשות, צ\"ל שיש בזה ג' מדרגות, הא' הוא הארת יסוד אבא כשמאיר בז\"א הוא סוד השמש ובבחי' זו אין כל חדש, ויסוד אבא בעצמו הוא",[["2336","1019","<b>ש\"י עולמות</b>: עוקצי' בסופה. ראה גם אוה\"ת בהעלותך ע' תטז."],["2337","1020","<b>וישבות ביום השביעי</b>: בראשית ב, ב."],["2338","1021","<b>הבל</b>: בביאוה\"ז כאן ע' תתקסד: הכל. וכנצ\"ל כבפנים."],["2339","1022","<b>לעשרה מאמרות יהי אור</b>: אבות רפ\"ה. בראשית א, ג. ראה זהר ויקרא יא, סע\"ב ואילך. שע\"ת יב, ג הערה 42."],["2340","1023","<b>זווגא דכנס\"י במלכא קדישא</b>: זהר אמור ק, ב."],["2341","1024","<b>אין. . השמש בקהלת סי' י\"א ט'</b>: וכ\"ה בהמשך הנדפס. וצ\"ל כביאוה\"ז כאן: א' ט' [ושם: ואין]. ראה גם מאמרי אדה\"א דברים ח\"א ע' רעו."],["2342","1025","<b>בשבת. . נשמות חדשות</b>: ראה גם ביאוה\"ז תרומה כרך ב ע' תתיט ואילך ובהנסמן שם. וראה גם בענין נשמות חדשות לקמן ח\"ב (בחלק ההנחות) הנחה ד\"ה ביום השמיני עצרת ובהערה 44."],["2343","1026","<b>כו'</b>: ברמ\"ז: וכו'. בביאוה\"ז כאן: כ' — וכנשצ\"ל כבפנים. בביאוה\"ז אמור ע' תתקסז ובהמשך וככה תרל\"ז כאן פל\"ו: ליתא. וראה לקמן הערה 1033."],["2344","1027","<b>בחי'</b>: וכ\"ה בביאוה\"ז כאן. שם: ליתא."],["2345","1028","<b>ופני לא יראו</b>: תשא לג, כג."],["2346","1029","<b>הארת</b>: וכ\"ה בביאוה\"ז כאן. ברמ\"ז שם: בחינות הארות. בביאוה\"ז אמור שם: בחי' הארה."],["2347","1030","<b>שמאירות בתוך</b>: בהמשך הנדפס: שמאירת בתוך. בביאוה\"ז אמור: שמאיר תוך. ברמ\"ז ובביאוה\"ז כאן כבפנים."],["2348","1031","<b>כולם בחכ' עשית</b>: תהלים קד, כד."]]],[2000470292,"למעלה מהשמש וזהו בחי' ב', ולהיות כי זהו לעילא מן שמשא לכן נמשך מזה נשמות חדשות וזהו שנת' שכשנמשך מן החכ' נמשך נשמות חדשות כו', ובחי' הג' זהו פנימיות יסו\"א &lt;47&gt;\nּ שמבחי' זו א\"א להמשיך עכשיו כי פנימיות אבא הוא חשוב כמו פנימיות עת\"י<sup data-n=\"2349\">1032</sup> כמ\"ש הרמ\"ז פ' כי תצא דרע\"ו ע\"ב בד\"ה כימי צאתך כו'<sup data-n=\"2350\">1033</sup>.\n<b></b>קיצור. שכאשר נמשך מחכ' הארה מועטת ע\"י חלון בחי' יו\"ד כשנמשך בבינה נעשה וא\"ו, וזהו קדוש בוא\"ו, כי החכ' הוא אצי' שבאצי' ובינה בריאה שבאצי', כמו שמסביר א' נקודה אחרונה שבשכלו לתלמיד, להנחיל אוהבי יש, ושבת אקרי קדש ל' הבדלה עליות העולמות למעלה מגדר המשכה, ואז זיווגא דכנס\"י במלכא קדישא כי אין כל חדש תחת השמש אבל בשבת כשחוזר ונתעלה לשרשו למעלה אז נמשך ומתגלה<sup data-n=\"2351\">1034</sup> נשמות חדשות, וצ\"ל שיסו\"א עצמו הוא למעלה מן השמש, וזה מאיר בשבת כו'.\n(לב) <b>והנה</b><sup data-n=\"2352\">1035</sup> כתיב ה' בחכ' יסד ארץ<sup data-n=\"2353\">1036</sup> כונן שמים בתבונה, וצ\"ל זה איך ארץ שהיא בחי' תחתונה יותר מן השמים יסודתה מחכ' ושמים מתבונה, אך הענין הוא דשמים עם היות שהם אהוי\"ר<sup data-n=\"2354\">1037</sup> עכ\"ז העיקר הוא בחי' אהבה ולכן בתיבת שמים יש תיבת מים בשלימות ומאש הוא רק השי\"ן לבד<sup data-n=\"2355\">1038</sup>, ולמעלה הם בחי' חו\"ג דז\"א<sup data-n=\"2356\">1039</sup>, שהוא בחי' יש מי שאוהב<sup data-n=\"2357\">1040</sup> וזה נמשך מבינה שהוא מקור ושרש היש<sup data-n=\"2358\">1041</sup>, בינה דינין מתערין מינה<sup data-n=\"2359\">1042</sup>, כי אחר שנמשך בבחי' השגה והבנה שייך שיומשך ע\"י הבנה זו לאהוב את הדבר או להיפך לשנוא אותה וזהו מה שבינה היא אם הבנים<sup data-n=\"2360\">1043</sup> כו', דחו\"ג דז\"א כנודע.",[["2349","1032","<b>פנימיות אבא. . פנימיות עת\"י</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתסה. לקו\"ת נצבים מט, ד. תו\"ח שמות ח\"א כג, א הערה 951."],["2350","1033","<b>כו'</b>: וכ\"ה בהמשך וככה תרל\"ז כאן פל\"ו. ברמ\"ז: וכו'. וראה לעיל הערה 1026."],["2351","1034","<b>ומתגלה</b>: בהמשך הנדפס: ומתגלי'. בביאוה\"ז כאן: ונתגלה."],["2352","1035","<b>והנה</b>: לשון ביאוה\"ז להצ\"צ כרך ב' ע' תתקסה בהוספות ובשינויים. ראה גם ביאוה\"ז כרך א ע' תכג ואילך. המשך וככה תרל\"ז פל\"ז."],["2353","1036","<b>ה' בחכמה יסד ארץ</b>: משלי ג, יט."],["2354","1037","<b>דשמים. . אהוי\"ר</b>: ראה גם (בנוסף להערה 1035) לקו\"ת ר\"ה סא, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסה."],["2355","1038","<b>שמים. . מים. . ומאש. . השי\"ן לבד</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשנט. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וביום הביכורים כאן על יד הערה 51 (בחלק ההנחות) בהנחה כאן על יד הערה 62. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ויאמר לך לך על יד הערה 88 (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה שם על יד הערה 115. סה\"מ תרל\"ח ע' רס. וש\"נ. מובא בסה\"מ תרנ\"א ע' ד."],["2356","1039","<b>שמים. . חו\"ג דז\"א</b>: ראה גם (בנוסף להערה 1035) לקו\"ת פ' ראה כד, א. שה\"ש יד, א. שעה\"י קי, סע\"ב ובהערה 24. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 52. (בחלק ההנחות) בהנחה כאן על יד הערה 61."],["2357","1040","<b>יש מי שאוהב</b>: מובא בכ\"מ בדא\"ח ומהם תו\"א וארא נו, א. יתרו סז, ג. סה\"מ תרל\"ח ס\"ע קלה. וש\"נ."],["2358","1041","<b>מבינה. . היש</b>: בהמשך וככה תרל\"ז פל\"ז כאן: כמ\"ש להנחיל אוהבי יש."],["2359","1042","<b>בינה דינין מתערין מינה</b>: ראה זהר ויקרא י, סע\"ב. יא, רע\"א. מאמרי אדה\"א דברים ח\"ב ע' שעז. וש\"נ."],["2360","1043","<b>שבינה היא אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. פרדס שעה\"כ שכ\"ג, פ\"א מערכת אם הבנים. לקו\"ת שמ\"ע פח, ד. שעה\"י קי, ב ובהערה 19."]]],[2000470293,"<b>ובזח\"א</b><sup data-n=\"2361\">1044</sup> דמ\"ז סע\"א דהא באורייתא אתברא עלמא ואשתכליל<sup data-n=\"2362\">1046</sup> הה\"ד ה' בחכ' יסד ארץ כונן שמים בתבונה (משלי ג' י\"ט), ובפ' ויגש דר\"ז ע\"א פי' וז\"ל כד ברא קוב\"ה עלמא חמי דלא יכיל לאתקיימא עד דברא אורייתא, פי' במק\"מ וז\"ל כד ברא קוב\"ה א\"ס עלמא עולם האצי' חמי דלא יכיל לאתקיימא<sup data-n=\"2363\">1047</sup> עד דברא אורייתא פי' אבא כי יסו\"א נק' תורה, ובזח\"ג פנחס דרמ\"ח ע\"א וז\"ל בחכ' יסד ארץ, חכמה אבא ארץ ברתא, כונן שמים דאיהו ברא עם אימא דאיהו תבונה, ודף רנ\"ו סע\"ב בחכ' יסד ארץ, באבא יסד ברתא וכ\"כ עוד שם דרנ\"ח ע\"א<sup data-n=\"2364\">1045</sup>, והענין הוא כי בחי' מל' הוא ביטול היש כמו עבד המשתחוה לאדונו שמבטל מהו\"ע ומשתחוה בפישוט ידים ורגלים לאדוניו שענין ההשתחוואה הוא שמשוה ראשו ורגליו ששניהם בטלים בשוה לאדוניו, ששרש ומקור בחי' ביטול זה נמשך מבחי' החכ', רק כי חכ' עצמה היא בחי' ביטול עצמי בלי שום מציאות יש כלל וכלל, ובחי' מל' הוא בחי' ביטול היש לבד, שעם היותו מציאות היש מ\"מ הנה הוא בטל ומשתחוה לאדוניו כו', ובאמת בעבודה י\"ל עוד יתרון בבחי' ביטול היש לגבי בחי' החכ', שהרי בחכ' לא יפלא כלל ענין בחי' הביטול שהרי לא יש שם כלל בחי' מציאות היש, משא\"כ במל' שיש מציאות היש ועכ\"ז הוא משתחוה לאדוניו מלא קומתו שמורה על ביטולו ה\"ז עבודה כו'. אך מ\"מ הביטול דחכ' כח מ\"ה הוא &lt;48&gt;\nּ בחי' ביטול יותר, רק שבחי' ביטול זה שיש בבחי' המל' שרשו מעצם בחי' הביטול שיש בחכ' וזהו בחכ' יסד ארץ כו'.\n<b></b>קיצור. בחכ' יסד ארץ, כונן שמים בתבונה, שמים חו\"ג שרשם מהבינה אם הבנים, אבל ארץ בחי' מל' ביטול היש שרשו מבחי' ביטול אמיתי דמ\"ה דחכ', לכן בחכ' דוקא יסד ארץ.\n(ג\"ל) ולהיות<sup data-n=\"2365\">1048</sup> כי החכ' והמל' שניהם הם בחי' ביטול לכן נק' שניהם בשם אחד, והיינו כי המל' נק' בשם דוד<sup data-n=\"2366\">1049</sup> עבדי<sup data-n=\"2367\">1050</sup>, ומשה עבדי<sup data-n=\"2368\">1051</sup> הוא",[["2361","1044","<b>ובזח\"א</b>: בהמשך הנדפס אינו פיסקא חדשה."],["2362","1046","<b>אתברא. . ואשתכליל</b>: בזהר: אתבני. בביאוה\"ז כאן ובהמשך הנדפס: אתברי. . בזהר ובביאוה\"ז: ואשתכלל."],["2363","1047","<b>חמי דלא יכיל לאתקיימא</b>: במק\"מ ובביאוה\"ז כאן ליתא. והוא לשון הזהר דלעיל."],["2364","1045","<b>ובזח\"א דמ\"ז. . ע\"א</b>: בביאוה\"ז כאן (ע' תתקסה) כ\"ז בא בחצע\"ג."],["2365","1048","<b>ולהיות</b>: לשון ביאוה\"ז להצ\"צ כרך ב' ע' תתקסה ואילך בהוספות ובשינויים. ראה גם ביאוה\"ז כרך א ע' תכד ואילך. המשך וככה תרל\"ז פל\"ז. — התחלת הפרק מובא בסה\"מ תרנ\"א ע' ד ואילך."],["2366","1049","<b>המל'. . דוד</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ד מערכת דוד. הנסמן המאמרי אדה\"א דברים ח\"ג ע' תתקט."],["2367","1050","<b>דוד עבדי</b>: שמואל-ב ג, יח. ועוד. ראה גם מאמרי אדה\"ז תקס\"ז ע' שסט. בהערה הבאה."],["2368","1051","<b>ומשה עבדי</b>: יהושע א, ב. ז. מלאכי ג, כב. ראה גם לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 140 ואילך."]]],[2000470294,"בחי' חכ', שהוא בחי' ביטול עצמי ולכן אמר ונחנו מ\"ה<sup data-n=\"2369\">1052</sup> היינו בחי' מ\"ה דחכמה כו', ודוד עבדי בחי' ביטול היש, ולכן אמר ע\"ע ואנכי תולעת<sup data-n=\"2370\">1053</sup> ולא איש חרפת אדם להיותו בבחי' הביטול רק שהוא בחי' ביטול היש, ועכ\"ז שם אחד להם עבד ע\"ש הביטול, וכן שניהם נק' בשם חכמה ובשם יו\"ד וכענין יו\"ד בראש יו\"ד בסוף<sup data-n=\"2371\">1054</sup> חכ' בראש וחכ' בסוף<sup data-n=\"2372\">1055</sup>, וכן שניהם נק' בשם יראה, יר\"ע ויר\"ת, רק שזה עילא וזה תתא, ומ\"מ הכל שם אחד, והיינו מפני כי המל' בחי' יראה תתאה שרשה מהחכ' בחי' יראה עילאה כו'. ושרש ההפרש בין ששת ימי החול לשבת, שבכל ששת ימי המעשה הוא כמו עד\"מ המלך שיוצא לעבדיו לחוץ במקום שהם ושם העבד משתחוה לאדוניו במקומו עצמו, אבל בשבת הוא עליות העולמות היינו כמו שהעבד נכנס לפני ולפנים לבוא לפני אדוניו להשתחוות אליו, ובודאי שאינו דומה ההשתחוואה ובחי' הביטול שבחוץ לבחי' ההשתחווא' והביטול שבפנים, רק מ\"מ שניהם בחי' הביטול כו', ולהיות כי בשבת הוא עליות העולמות שבא למקור ושרש הביטול בחי' ביטול העצמי, לכן אז הוא הזווג להוליד נשמות חדשות כו', רק שם למעלה הוא רק התגלות אורות לבד, וע\"י מטרוניתא ששם הוא ה\"ג מנצפ\"ך<sup data-n=\"2373\">1056</sup> המחלקן לנשמות אברהם לבד כו' כ\"א בפ\"ע, לכן עיקר ההולדה הוא ע\"י מטרוניתא וזהו זיווגא דכנס\"י במלכא קדישא כי ההשפעה שמקבלת המל' מן חכ' צ\"ל ע\"י זעיר לכן נק' מלכא קדישא<sup data-n=\"2374\">1057</sup> כי בשבת מקבל זעיר מוחין דאבא הנק' קדש ומשפיע למטרוניתא, אך הנה ידוע כי באתעדל\"ת אתעדל\"ע וא\"כ ממילא מובן שבשבת צ\"ל העלאת מ\"ן דמל' בא\"א<sup data-n=\"2375\">1058</sup> שלא כאשר בימי החול ולפ\"ע ההעלאת מ\"ן<sup data-n=\"2376\">1059</sup> כן נמשך המ\"ד, וזהו שא' בזהר מהיכן יהי' הכח לבחי' מל' להעלות מ\"ן גבוה זהו בזמנא דנטלא מבי אבא כו', כי בחול יש ג\"כ זיווג בשמ\"ע<sup data-n=\"2377\">1060</sup> לצורך ההשפעה לחזק הישינות כו', וכל ההשפעות והמשכות דחול הוא הכל למטה מן השמש מה שנמשך ע\"י השתלשלו' מבינה שדינין מתערין מינה היינו שהיא אם הבנים דחו\"ג אברהם ויצחק שאברהם יצא ממנו ישמעאל<sup data-n=\"2378\">1061</sup> כו' עד שבהשתלשלו'<sup data-n=\"2379\">1062</sup> נתהוה צפרנים",[["2369","1052","<b>ונחנו מ\"ה</b>: בשלח טז, ז. ח. ראה גם לעיל המשך זאת חנוכת המזבח פכ\"א ובהערה 593."],["2370","1053","<b>ואנכי תולעת</b>: תהלים כב, ז."],["2371","1054","<b>יו\"ד בראש יו\"ד בסוף</b>: ראה מגן דוד להרדב\"ז אות היוד. מאמרי אדה\"א בראשית ע' תכד. וש\"נ. או\"ת ר\"פ לך הובא באוה\"ת ואתחנן ס\"ע רעו ואילך."],["2372","1055","<b>חכ' בראש וחכ' בסוף</b>: ראה זהר בראשית כו, ב. שעה\"י קמג, א הערה 8."],["2373","1056","<b>ה\"ג מנצפ\"ך</b>: ראה שער היחוד והאמונה ספ\"ד. מאמרי אדה\"א ויקרא ח\"א ע' רלז. וש\"נ."],["2374","1057","<b>זעיר. . מלכא קדישא</b>: ראה זהר בשלח נה, א ובמק\"מ שם."],["2375","1058","<b>בא\"א</b>: בביאוה\"ז כאן: באופן אחר."],["2376","1059","<b>ולפ\"ע ההעלאת מ\"ן</b>: ראה גם מאמרי אדה\"א קונטרסים ע' שעט [ושם: הכלל הידוע]. שה\"א כו, ב ובהערה 29."],["2377","1060","<b>בחול יש ג\"כ זיווג בשמ\"ע</b>: ראה גם ביאוה\"ז כרך א כאן ע' תכה. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וביום הביכורים כאן על יד הערה 63. (בחלק ההנחות) בהנחה כאן על יד הערה 89. ראה פע\"ח שער העמידה ש\"ט, פ\"כ בברכת שים שלום."],["2378","1061","<b>שאברהם יצא ממנו ישמעאל</b>: ראה פסחים נו, א. מאמרי אדה\"א דברים ח\"ג ע' א'קטו ואילך. וש\"נ. שע\"ת פה, ג ובהערה 14. תו\"ח בא ח\"א קכז, ד."],["2379","1062","<b>עד שבהשתלשלו'</b>: בביאוה\"ז כרך א כאן ע' תכה ניתוסף: מתרין דרועין חו\"ג."]]],[2000470295,"ויש גמור, א\"כ כל העבודה דחול אין יכול להיות רק לאכפיי', כי מאחר שההמשכה וההתגלות &lt;49&gt;\nּ הוא מבינה אשר היא מקור להיות דינין מתערין כו' א\"כ א\"י להיות העבודה בבחי' אתהפכא לגמרי, כ\"א העלאת מ\"ן בבחי' אתכפיא לבד, וזהו מפני שבששת ימי המעשה נמשך הכל ע\"י השתלשלו' אורות בכלים כו', אבל בשבת דנטלא מבי אבא שיש התגלות הארה למעלה מהשתלשלות מבחי' חכ' אשר והחכ' תחי', וכתי' ימותו ולא בחכ'<sup data-n=\"2380\">1063</sup> שלא הי' שם שבירה כלל, ומחמת בחי' זו יכול כאו\"א למסו\"נ על קדה\"ש בלי שום טעם ודעת רק מפני שבבחי'<sup data-n=\"2381\">1064</sup> חכ' שבנפשו אין שום מקום לסט\"א לאחוז כלל, לכן בשבת דנטלא מבי אבא הארת החכ' יכול להיות העלאת מ\"ן בבחי' אתהפכא, ולפ\"ע אתעדל\"ת אתעדל\"ע מן בחי' שלמעלה מהשתלשלו' ג\"כ התגלות אורות לבד להוליד נשמות חדשות, אבל יו\"ט שחל להיות בחול עיקר ההמשכה מאימא דרך השתלשלו' רק בהעלם<sup data-n=\"2382\">1065</sup> יש בה הארה מבחי' יסו\"א, לכן נק' מקרא קדש כו', ומכ\"ז מובן איך שע\"י היראה דוקא יכולים לבא לבחי' קדש עילאה ולא ע\"י אהבה, ונמצא כי בינה יתירה יש בבחי' אשה יראת ה' יותר מבאיש בחי' זכר חסדו<sup data-n=\"2383\">1066</sup> כו'.\n<b></b>קיצור. החכ' והמל' שניהם נק' חכ' ויו\"ד ויראה ועבד, רק בחול הוא השתחואות העבד בחוץ ובשבת עולה לפנים, והכח ע\"ז הוא דנטלא מבי אבא הארת החכ' במל', והעבודה היא בבחי' אתהפכא כו', ולכן מובן שבינה יתירה יש בבחי' היראה כו'.\n(והנה כ\"ז הוא בכל המועדים שנק' מקרא קדש כנ\"ל, אבל נוסף עליהם חה\"ש שבו ניתנה תורה<sup data-n=\"2384\">1068</sup> שזהו לבד היו\"ט דחה\"ש, שהרי מועד דחה\"ש הוא שהוא יום החמשים<sup data-n=\"2385\">1069</sup>, וכמ\"ש בזהר בענין ז' שבועות שהם ז\"נ<sup data-n=\"2386\">1070</sup> ויום החמשים הוא הטבילה<sup data-n=\"2387\">1071</sup>, ומה שניתנה תורה זהו היחוד המשכת הטיפה, ולכן הכל מודים שמ\"ת הי' בשבת<sup data-n=\"2388\">1072</sup>, והיינו כשם ששבת הוא מוחין דאבא כך בחי' התורה היא ג\"כ המשכת",[["2380","1063","<b>ימותו ולא בחכ'</b>: איוב ד, כא. ראה סידור שחרית מה, ב. לעיל המשך זאת חנוכת המזבח פי\"ג. וש\"נ."],["2381","1064","<b>למסו\"נ על קדה\"ש. . חכ'</b>: ראה תניא פי\"ח. ראה גם סה\"מ מלוקט ב' ע' קסו הערה 97."],["2382","1065","<b>בהעלם</b>: בהמשך הנדפס: בהשתלשלו'. בביאוה\"ז כבפנים."],["2383","1066","<b>זכר חסדו</b>: תהלים צח, ג. ראה תניא פמ\"ג (סב, א). תו\"ח שמות ח\"א כו, א ובהערה 93."],["2384","1068","<b>חה\"ש שבו ניתנה תורה</b>: ראה נוסח התפלה וקידוש ליו\"ט. שו\"ע אדה\"ז חאו\"ח סתצ\"ד, ס\"א. לקו\"ש שבועות כרך ח ע' 21."],["2385","1069","<b>מועד דחה\"ש. . יום החמישים</b>: אמור כג, טז. כא. פ' ראה טז, י. פינחס כח, כו. תשא לד, כב."],["2386","1070","<b>ז' שבועות שהם ז\"נ</b>: ראה זהר אמור צז, סע\"א ואילך. הנסמן בלקו\"ש אמור כרך כב ע' 119. וראה ג\"כ תוד\"ה וספרה כתובות עב, א."],["2387","1071","<b>ויום החמשים. . הטבילה</b>: ראה זהר אמור צח, ב. ביאוה\"ז אמור כרך ב' ע' תתקמה. אוה\"ת אמור ריש ע' קעב. סה\"מ תרל\"ח ע' תכג. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' נ. תרנ\"ב ע' לד ואילך."],["2388","1072","<b>הכל מודים שמ\"ת הי' בשבת</b>: ראה אוה\"ת ר\"ה כרך ה ע' ב'תקט: ארז\"ל הכל מודים שבשבת ניתנה תורה. המשך תער\"ב ח\"ב ע' א'צא: וכמא' הכל מודים כו'. שבת פו, ב. תורת לוי יצחק תענית ג, רע\"א."]]],[2000470296,"החכ' רק ששבת היא בבחי' עלי' ומ\"ת הוא המשכה למטה, ולכן בחה\"ש זמן מ\"ת הי' קרב גם חמץ<sup data-n=\"2389\">1073</sup> להיות כי ימותו ולא בחכ', והיש דחמץ מתעלה להיות ויגבה לבו בדרכי ה'<sup data-n=\"2390\">1074</sup>, משא\"כ בשבת להיותו בבחי' עלי' הרי א\"א שיתעלה החמץ, אבל בחה\"ש כשנמשך למטה מתברר גם החמץ, שיהי' אכילה לכהנים<sup data-n=\"2391\">1075</sup> שזהו ע\"ד אכילת אדם כו' כמ\"ש בד\"ה מזמור לתודה<sup data-n=\"2392\">1067</sup> )<sup data-n=\"2393\">1076</sup>.",[["2389","1073","<b>בחה\"ש. . חמץ</b>: אמור כג, יז. וראה גם תשובות וביאורים קה\"ת ס\"ג."],["2390","1074","<b>ויגבה לבו בדרכי ה'</b>: דהי\"ב יז, ו. ראה גם כש\"ט קה\"ת סשצ\"ג (נז, א ואילך)."],["2391","1075","<b>בחה\"ש. . החמץ. . לכהנים</b>: מנחות עד, ב במשנה."],["2392","1067","<b>(והנה. . לתודה)</b>: ראה לעיל הערה 988."],["2393","1076","<b>בד\"ה מזמור לתודה</b>: ראה סידור שחרית מה, ב-ג. פיה\"מ פקמ\"ז. אוה\"ת תהלים כרך ב ע' תתקפד ואילך."]]],[2000470297,"<h3>ויאמר כו' אל תיראו כו' ויובן בהקדם</h3>\n<b></b><b>בס\"ד יום ב' דחה\"ש אחר התפלה</b>\n(לד-לו)\nב' דחה\"ש\n<b>(ויאמר</b> משה אל העם אל תיראו<sup data-n=\"2394\">1077</sup> כו' תהי' יראתו על פניכם לבלתי תחטאו<sup data-n=\"2395\">1078</sup>. וצ\"ל הלא היראה היא הראשית לכל כמ\"ש ראשית חכ' יראת ה', וכתי' מה ה' אלקיך שואל מעמך כ\"א ליראה<sup data-n=\"2396\">1079</sup>, והרבה פסוקים בתורה מזהירים על היראה, את ה' אלקיך תירא<sup data-n=\"2397\">1080</sup>, למען תירא<sup data-n=\"2398\">1081</sup> וכדומה, וכתי' סוף דבר כו' את האלקי' ירא<sup data-n=\"2399\">1082</sup> כו' כי זה כל האדם, וכנודע שיראה היא שרש שס\"ה ל\"ת והאיך",[["2394","1077","<b>ויאמר משה אל העם אל תיראו</b>: מכאן מתחיל מאמר הי\"א מהמשך מצה זו (הכולל פרקים לד-לו).\nפל\"ד — לפיסקא ויובן — לשון מאמרי אדה\"ז תקס\"ד ע' נ (הועתק באוה\"ת שה\"ש ח\"ב כאן ע' תלו (בהוספות) — וראה שם ע' תנא) בהוספות ושינויים. ונו\"א במאמרי אדה\"ז על פרשיות התורה ח\"א ריש ע' נו ובשולי היריעה שם.\n— לפיסקא וביאור — לשון לקו\"ת שה\"ש כא, ב בשינויים והוספות (צויין אליו באוה\"ת שה\"ש כאן). וראה גם בהנסמו במ\"מ לשם.\nפל\"ה — המשך לשון הלקו\"ת שה\"ש כא, ב בשינויים והוספות.\nפל\"ו — לשון מאמרי אדה\"ז תקס\"ד ע' נ (הועתק באוה\"ת שה\"ש ח\"ב כאן ע' תלו (בהוספות) — וראה שם ע' תנא) בהוספות ושינויים. ונו\"א במאמרי אדה\"ז על פרשיות התורה ח\"א ע נו.\nממאמר זה ישנם עוד שני הנחות והם: א) הנחת<sup data-n=\"e128\">*</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נמצא רק הפסוק ולא רשם יותר ונדפס לקמן (בחלק הנחותיו). ב) הנחה אחרת נדפסה לקמן (בחלק ההנחות).\nהפתיחה וכן סיום המאמר באים בסוגרים — אולי ניתוספו לאחרי כתיבת המאמר [בצילום גוכתי\"ק שנמצא בריש המשך והחרים תרל\"א ע' 5 (לקמן ע' תעח), הנה פתיחה זו נרשמה מהצד].\nהכותרת המופיע בריש המאמר הנה התיבות: ”יום ב' ד\" ”אחר התפלה\" ניתוספו מהנחת כ\"ק אדמו\"ר מהורש\"ב."],["2395","1078","<b>ויאמר משה אל העם אל תיראו. . תחטאו</b>: יתרו כ, יז."],["2396","1079","<b>מה ה' אלקיך. . ליראה</b>: עקב י, יב."],["2397","1080","<b>את ה' אלקיך תירא</b>: ואתחנן ו, יג. עקב י, כ."],["2398","1081","<b>למען תירא</b>: ואתחנן ו, ב."],["2399","1082","<b>סוף דבר. . האלקי' ירא</b>: קהלת יב, יג."],["e128","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470298,"אמר משה לכ\"י אל תיראו<sup data-n=\"2400\">1083</sup> כו', וגם כי בכאן עצמו אמר אח\"כ שבא האלקי' בכדי שתהי' יראתו ע\"פ והאיך אומר אל תיראו).\n&lt;50&gt;\nּ <b>(לד)</b> ויובן<sup data-n=\"2401\">1084</sup> בהקדם עוד מעלת היראה על בחי' האהבה ע\"פ מה שנודע שהיראה נק' זאת, והאהבה נק' בשם זה<sup data-n=\"2402\">1085</sup> בחי' דכר<sup data-n=\"2403\">1086</sup> כו', וכתי' זה אלי ואנוהו<sup data-n=\"2404\">1087</sup>, פי' אנוהו הוא תיבה מורכבת משני תיבות אני<sup data-n=\"2405\">1088</sup> והוא<sup data-n=\"2406\">1089</sup>, כלומר בחי' אוא\"ס מה שכבר נמשך ושהי' מתחלה בבחי' הוא לשון נסתר והעלם להיות כי אוא\"ס הוא קדוש ומובדל הוא בערך גם מהנאצלים כו' שע\"ז רומז תיבת הוא כידוע, ועתה נמשך בבחי' התחברות וגילוי אור בנאצלים שע\"ז רומז תי' אני כו' וזהו אני והוא, מה שהי' בבחי' הוא היינו בבחי' נסתר נתגלה להיות נק' אני כלומר שנתגליתי כאדם האומר ע\"ע אני הוא, למי ששואלו אי' פלוני שנעלם ממנו איה הוא, ואומר לו אני הוא הנעלם שאתה דורש עליו ואני הוא שנגלה לפניך כו', וא\"כ תיבת ואנוהו רומז שאוא\"ס בחי' אור המאציל שהי' בבחי' הוא בבחי' הסתר מתגלה בנאצלים להיות מתחברים יחד, והוא בחי' ת\"ת דז\"א שעליו נא' זה אלי ואנוהו בבחי' נוי ותפארת שבו נמשך אור הכתר הנק' הוא<sup data-n=\"2407\">1090</sup>, ואזי נק' הקב\"ה קדוש בוא\"ו, וזהו בחי' גילוי אור ממש עד שיוכלו להורות עליו ולומר זה כו', כמ\"ש במ\"א ע\"פ זה הדבר<sup data-n=\"2408\">1091</sup> כו', ואין לגילוי אור זה ערך עם עצמיות אוא\"ס ב\"ה שלמעלה מבחי' התפשטות וגילוי אור הנק' קדש עילאה שנת\"ל.\n<b>וביאור</b><sup data-n=\"2409\">1092</sup> הענין יובן בהקדם מארז\"ל לא זז מחבבה<sup data-n=\"2410\">1093</sup> עד שקראה אמי, שהקב\"ה קרא לכנס\"י בשם אמי, והיינו כמו שהאם מברכת בנה כך כנס\"י מברכת להקב\"ה כו', כי הנה שם הקב\"ה הוא קדוש וברוך<sup data-n=\"2411\">1094</sup>, קדוש בוא\"ו שהוא",[["2400","1083","<b>והאיך אמר משה לכ\"י אל תיראו</b>: ראה גם מאמרי אדה\"ז הקצרים ע' ס. סה\"מ תרל\"ח ע' קמו."],["2401","1084","<b>ויובן</b>: מכאן עד סיום הפיסקא — לשון מאמרי אדה\"ז תקס\"ד ע' נ (הועתק באוה\"ת שה\"ש ח\"ב כאן ע' תלו (בהוספות) — וראה שם ע' תנא) בהוספות ושינויים. ונו\"א במאמרי אדה\"ז על פרשיות התורה ח\"א ריש ע' נו ובשולי היריעה שם."],["2402","1085","<b>והאהבה נק' בשם זה</b>: ראה הערה שלפנ\"ז."],["2403","1086","<b>והאהבה. . בחי' דכר</b>: ראה תניא פמ\"ג."],["2404","1087","<b>זה אלי ואנוהו</b>: בשלח טו, ב."],["2405","1088","<b>אנוהו. . אני והוא</b>: ראה (בנוסף להערה 1084) של\"ה בעשרה מאמרות המאמר הראשון מ, א. המשך תער\"ב ח\"א ע' שכז וע' תסג."],["2406","1089","<b>והוא</b>: בשל\"ה ואוה\"ת (וכן בהקיצור) כאן: והו[ednref_129_א]. אבל בסמוך באוה\"ת שם וכן בע' תנא במאמרי אדה\"ז שם כבפנים."],["2407","1090","<b>הכתר הנק' הוא</b>: ראה שערי אורה — לר\"י גיקטלייא — שער י [ירושלים תש\"ך קא, ב]. פרדס שעה\"כ שכ\"ג, פ\"ה מערכת הוא. ע\"ח (שער תיקון הנוקבא) של\"ד, ספ\"ב."],["2408","1091","<b>כמ\"ש במ\"א ע\"פ זה הדבר</b>: במאמרי אדה\"ז תקס\"ד כאן: כמ\"ש בזוהר ע\"פ זה הדבר. ראה גם מאמרי אדה\"ז שם ע' קצ וע' קצה. לקו\"ת מטות פב סע\"א ואילך. פג, ב."],["2409","1092","<b>וביאור</b>: מכאן ועד לקמן קרוב לספל\"ה — לשון לקו\"ת שה\"ש כא, ב בשינויים והוספות (צויין אליו באוה\"ת שה\"ש כאן). וראה גם בהנסמן במ\"מ לשם."],["2410","1093","<b>לא זז מחבבה</b>: ראה פדר\"כ פסקא א ויהי ביום כלות משה. הנסמן במ\"מ ללקו\"ת כאן."],["2411","1094","<b>שם הקב\"ה הוא קדוש וברוך</b>: ראה ברכות ג, א. ב. ראה גם לקו\"ת תזריע כב, ג. תו\"ח תרומה ח\"ב שיז, ב ואילך. וש\"נ. וראה גם תו\"ח בא ח\"א קכב, ב. בסמוך הערה 1098.\n\n[edn_129_א] להעיר ג\"כ מסוכה מה, א וברש\"י שם. וראה ג\"כ פרדס שעה\"כ שכ\"ג, פ\"ו מערכת וה\"ו."]]],[2000470299,"מורה על בחי' המשכה<sup data-n=\"2412\">1095</sup> שהוא המשכת קדושתו ית' להיות ממכ\"ע וסוכ\"ע שהוא המשכה והארה בעלמא שאין ערוך אליו ית' כי הוא אחדות פשוט והנבראים המה בע\"ג, ואפי' נבראים עליונים אלף אלפים ורבוי<sup data-n=\"2413\">1096</sup> רבבן, ולגדודיו אין מספר<sup data-n=\"2414\">1097</sup> שהם נבראים הגדולים כנודע שהמלאך בשליש העולם עומד, והם בבחי' אין מספר ואין סוף, מ\"מ הרי הם בבחי' התחלקות, אלא שההתחלקות הוא בתוס' וריבוי עד אין קץ ותכלית, משא\"כ בבחי' אוא\"ס ב\"ה בכבודו ובעצמו לא שייך כלל כל זה כי הוא ית' אחדות פשוט בתכלית הפשיטות, אלא שנמשך המשכה והארה מצומצמת בכדי שיהיו העולמות והנבראים יכולים לקבל כאו\"א לפי מדריגתו<sup data-n=\"2415\">1098</sup>, ומ\"מ הארה והמשכה זו נק' בחי' קדוש להיותה מובדל כי הארה והמשכה זו<sup data-n=\"2416\">1099</sup> אינה כמו הנשמה המתפשטת בתוך הגוף להחיותו ולקיימו שהיא מתפעלת ממקרי הגוף לפי שהיא מלובשת ממש בתוך הגוף, שהרי כשמתלבשת במחשבה א' היא נתפסת ומוקפת בה עד שאינה יכולה להתלבש במח' אחרת<sup data-n=\"2417\">1100</sup>, משא\"כ ההארה וההמשכה שממנו ית' להחיות ולהוות העולמות רבים ונבראים עד אין קץ ותכלית שעליהם אמר דהע\"ה\n&lt;51&gt;\nּ מה רבו מעשיך ה'<sup data-n=\"2418\">1101</sup> שהם ריבוי והתחלקות הנבראים לאין שיעור, וכולם שונות זה מזה, ואין דעותיהם שוות ואין מחשבותיהם שוות זל\"ז, ואין מחשבת ודיעה נברא<sup data-n=\"2419\">1102</sup> א' תופסת ומקפת החיות הנמשך ממנו ית' להטריד ולבלבל שלא יתלבש להחיות ולהוות נבראים אחרים שבמח' ודיעות משונים מדיעה ומח' נברא זה, לפי שההארה והמשכה זו אינה אלא בבחי' השגחה בעלמא פי' עם היות שהוא השגחה פרטיות על כל דרכי איש<sup data-n=\"2420\">1103</sup> ועלילות מצעדי גבר<sup data-n=\"2421\">1104</sup> אך אין זה כידיעת<sup data-n=\"2422\">1105</sup> האדם שכאשר ברצונו לידע איזה דבר הנה ידיעתו מלובשת באותו דבר שיודע, אבל בו ית' אינו כן אלא ע\"ד שהכל גלוי וידוע לפניו כמ\"ש במ\"א בד\"ה רני ושמחי<sup data-n=\"2423\">1106</sup> וע\"פ ארדה נא ואראה<sup data-n=\"2424\">1107</sup>, ואינה נתפסת ומלובשת ממש בתוך הנבראים, רק צופה ומביט עד סוף כל הדורות בסקירה אחת, וכמ\"ש היוצר יחד לבם<sup data-n=\"2425\">1108</sup> המבין אל כל מעשיהם, ולכן נק' ההארה והמשכה זו בחי' קדוש ומובדל, אלא שהוא קדוש בוא\"ו",[["2412","1095","<b>קדוש בוא\"ו. . המשכה</b>: ראה גם (בנוסף ללקו\"ת כאן) לעיל הערה 942."],["2413","1096","<b>ורבוי</b>: בהמשך הנדפס: ורבוא. בלקו\"ת כאן: ורבי."],["2414","1097","<b>ולגדודיו אין מספר</b>: חגיגה יג, ב. ראה גם סה\"מ תרל\"ה ח\"ב ע' שנג תרל\"ח ע' ב והנסמן בהנ\"ל."],["2415","1098","<b>מדריגתו</b>: באוה\"ת שה\"ש כרך ג' ע' תתצג ניתוסף: ונקראת הארה זו סובב וממלא (והן הנק' קדוש וברוך וז\"ס קב\"ה)."],["2416","1099","<b>נק'. . והמשכה זו</b>: בהמשך הנדפס: ליתא. ואולי נשמט מפני תיבות הדומות: והמשכה זו. . והמשכה זו. ובלקו\"ת כבפנים (בשינוי קצת)."],["2417","1100","<b>כשמתלבשת במחשבה א'. . אחרת</b>: ראה גם שו\"ע אדה\"ז הל' ק\"ש רסע\"ג קו\"א ס\"ג."],["2418","1101","<b>מה רבו מעשיך ה'</b>: תהלים קד, כד. ראה גם לעיל מאמר ד\"ה ואעשך לגוי גדול על יד הערה 36 ואילך ובהנסמן שם."],["2419","1102","<b>נברא</b>: בהמשך הנדפס: ליתא."],["2420","1103","<b>על כל דרכי איש</b>: ע\"פ איוב לד, כא. משלי טז, ב. ירמי' לב, יט."],["2421","1104","<b>ועלילות מצעדי גבר</b>: ברכת זכרונות."],["2422","1105","<b>כידיעת</b>: בהמשך הנדפס: כמו דיעות. בלקו\"ת כבפנים."],["2423","1106","<b>בד\"ה רני ושמחי</b>: תו\"א מקץ לו, א."],["2424","1107","<b>וע\"פ ארדה נא ואראה</b>: תו\"א וירא יד, ד."],["2425","1108","<b>היוצר יחד לבם</b>: תהלים לג, טו."]]],[2000470300,"שמורה על ההמשכה שהוא ההמשכת בחי' ההשגחה וסקירה אחת, וז\"ע שהמלאכי' אומרים ג\"פ קדוש<sup data-n=\"2426\">1109</sup> עד שאומרים ה' צבאות שפי' צבאות הוא אות הוא בצבא דילי'<sup data-n=\"2427\">1110</sup> ובחי' זו הוא ג\"כ קדוש ומובדל כו'.\n<b></b>קיצור. היראה נק' זאת והאהבה זה, זה אלי ואנוהו ת\"ת דז\"א שנק' הקב\"ה קדוש בוא\"ו, כי אוא\"ס הוא אח\"פ ושיומשך ריבוי התהוות הנבראים זהו מהארה בעלמא, וג\"ז הוא קדוש ומובדל, ולא כמו הנשמה שמתלבשת ומתפעלת, אלא שסוקר הכל בסקירה א' כו'.\n(לה) <b>וזהו</b><sup data-n=\"2428\">1111</sup> דכתי' אין קדוש כהוי'<sup data-n=\"2429\">1112</sup>, ופי' בזח\"ג תזריע דמ\"ג א'<sup data-n=\"2430\">1113</sup>, דכמה קדישין אינון<sup data-n=\"2431\">1114</sup> כו' ולאו קדישין כהוי' ע\"ש, והענין הוא כי פי' הוי' ל' מהוה<sup data-n=\"2432\">1115</sup> שמהוה את הנבראים, ואע\"פ שמהוה הכל אעפ\"כ הוא קדוש ומובדל ממש מהם בבחי' סוכ\"ע ואינו כדמיון הנשמה וכנ\"ל, ולכן בחי' קדוש כזה לא נמצא בכל בחי' קדישין דלעילא מפני שבכל סדרי ההשתל' מי שנק' קדוש שהוא מובדל מאיזה דבר, לא ימצא בו ההפכי היינו ההתפשטות והאחיזה בדבר<sup data-n=\"2433\">1116</sup> שהוא קדוש ומובדל ממנו, משא\"כ למעלה באוא\"ס ב\"ה הסוכ\"ע שהוא קדוש ומובדל, ואעפ\"כ הוא דוקא המהוה כל העולמות שעיקר החיות וההתהוות הוא מבחי' המקיף, וכמ\"ש בסש\"ב ס\"פ ך\"ג וס\"פ מ\"ח, וכ\"ה בע\"ח שהמקיף מצחצח הכלי מבחוץ<sup data-n=\"2434\">1117</sup>, ועמ\"ש בת\"א בד\"ה יביאו לבוש מל'<sup data-n=\"2435\">1118</sup>, וזהו אין קדוש כהוי', והיינו משום דאיהו תפיס בכולהו עלמין<sup data-n=\"2436\">1119</sup> ע\"י שהוא סוכ\"ע, ומחי' ומהוה אותם עי\"ז מאין ליש, ועכ\"ז לית מאן דתפיס בי' והוא קדוש ומובדל כו'. והנה כתי' שאו ידיכם קדש<sup data-n=\"2437\">1120</sup> וברכו את הוי' כי המשכת בחי' קדוש להיות הוי' צבאות צריכה ברכה והמשכה שתמשך בכל דור ודור שלא יסתלק החיות מפני הדור שאינו ראוי לכך, ויהי' נצרך להמשיך",[["2426","1109","<b>שהמלאכי' אומרים ג\"פ קדוש</b>: ישעי' ו, ג."],["2427","1110","<b>צבאות. . בצבא דילי'</b>: ראה חגיגה טז, רע\"א [לגי' הע\"י]. לקו\"ת האזינו עד, רע\"ד ובהנסמן במ\"מ לשם. מאמרי אדה\"א שמות ח\"א ע' רפה. וש\"נ. סה\"מ מלוקט א' ע' שעט. וש\"נ."],["2428","1111","<b>וזהו</b>: המשך לשון הלקו\"ת שה\"ש כא, ב בשינויים והוספות."],["2429","1112","<b>אין קדוש כהוי'</b>: שמואל-א ב, ב."],["2430","1113","<b>דמ\"ג א'</b>: וכ\"ה בלקו\"ת כאן. אבל בסה\"מ תרל\"ה ח\"א ע' פה (שמעתיק לשון הלקו\"ת): דמ\"ד א'. תרנ\"ד ע' קנא."],["2431","1114","<b>אינון</b>: בזהר ובלקו\"ת: נינהו."],["2432","1115","<b>הוי' ל' מהוה</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. פרדס שער עשר ולא תשע ש\"א, פ\"ט. שער עצמות וכלים שער ד, ספ\"י. שער היחוה\"א פ\"ד. פ\"ז. הערה בסה\"מ ת\"ש ע' 40. וראה ג\"כ לקמן פמ\"ז."],["2433","1116","<b>בדבר</b>: בהמשך הנדפס ליתא. בלקו\"ת כבפנים."],["2434","1117","<b>שהמקיף מצחצח הכלי מבחוץ</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"ב. שער השתל' הי\"ס ש\"ב, ענף ג. מאמרי אדה\"ז תקס\"ה ח\"א ע' תצט. ח\"ב ע' תתקלט ואילך. תו\"ח פקודי ח\"ב תמט, ד ואילך. (לקמן בחלק ההנחות) הנחה ד\"ה ויאמר משה אל העם אל תיראו כאן פיסקא וזהו דכתיב."],["2435","1118","<b>בת\"א בד\"ה יביאו לבוש מל'</b>: מג\"א צא, ג."],["2436","1119","<b>דאיהו תפיס בכולהו עלמין</b>: ראה זהר רע\"מ פינחס רכה, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קפב. תו\"ח נח סו, ג הערה 30."],["2437","1120","<b>שאו ידיכם קדש</b>: תהלים קלד, ב."]]],[2000470301,"מחדש בחי' המשכת קדושתו ית', וברכה והמשכה זו הוא מבחי' קדש &lt;52&gt;\nּ העליון שהוא למעלה מעלה מבחי' קדוש בוא\"ו שה\"ע להיות המשכה בחי' ממכ\"ע וסוכ\"ע, משא\"כ קדש בלא וא\"ו אינה<sup data-n=\"2438\">1121</sup> בגדר עלמין כלל, והוא למעלה מעלה מבחי' ממכ\"ע ומבחי' סוכ\"ע, ועל בחי' זו נא' אם חטאת מה תפעל<sup data-n=\"2439\">1122</sup> ורבו פשעיך כו' אם צדקת<sup data-n=\"2440\">1123</sup> כו' שאין העוונות פוגמים כלל ומשם נמשך שפע ברכה היינו מקדש העליון להיות המשכת אוא\"ס ב\"ה בנבראים גם שלא לפי מעשיהם, וזהו פי' הקב\"ה שהוא קדוש בוא\"ו להיות המשכה להוות ולהחיות הנבראים הוא ברוך ונמשך מקדש העליון בכל דור ודור.\n<b>אך</b> הגורם להיות השפעת שפע ברכה והמשכה מקדש העליון להיות קדוש בוא\"ו זהו ע\"י שאו ידיכם בבחי' קדש, פי' ידיכם זהו היחוד דק\"ש שמע ובשכמל\"ו, שהם יחו\"ע ויחו\"ת<sup data-n=\"2441\">1124</sup>, יחו\"ע למס\"נ באחד<sup data-n=\"2442\">1125</sup> במס\"נ ממש שתתהפך נפשו להיות בטילה ונכללת באוא\"ס ב\"ה ומיוחדת בבחי' יחו\"ע איך שהוא אחד ממש שהוא לבדו הוא ואין עוד מלבדו, ואי לזאת תכלה ותכסוף הנפש לצאת מנרתיקה הוא מאסר הגוף כו', ובחי' יחו\"ת הוא בע\"כ אתה חי<sup data-n=\"2443\">1126</sup> דהיינו אחר שכבר נמשך שם כבוד מל' להיות מל' כ\"ע להוות מאין ליש דוקא, ומוכרחת להיות יש גשמי, רק שיהי' בחי' ביטול היש שיהי' היש בטל ונכלל ג\"כ באוא\"ס ב\"ה בקיום עוצם עיניו מראות ברע<sup data-n=\"2444\">1127</sup> ובשמירתן<sup data-n=\"2445\">1128</sup> ממח' אשר לא לה' המה, ולא תתורו אחרי לבבכם<sup data-n=\"2446\">1129</sup>, וע\"י נשיאת ידים אלו בבחי' יחוד אוא\"ס שהוא לבדו הוא, וכמו קודם שנבה\"ע, ולכן ע\"י העלאה זו נמשך הברכה מבחי' קדש העליון שיומשך אוא\"ס ב\"ה להיות ממכ\"ע וסוכ\"ע כו', וזהו עד שקראה אמי שהיא מברכת לבחי' קדוש בוא\"ו כו', ונמצא מובן שבחי' קדוש בוא\"ו אינו בערך כלל לבחי' קדש העליון עצמו כו'.\n<b></b>קיצור. אין קדוש כהוי' שהגם שהוא מהוה עכ\"ז הוא מובדל, ואיהו תפיס ולית מאן דתפיס בי', ולהיות המשכה זו זהו ע\"י שאו ידיכם יחו\"ע ויחו\"ת, שנמשך ברכה מקדש העליון להיות קדוש בוא\"ו.\n(לו) <b>והנה</b><sup data-n=\"2447\">1130</sup> כמו שע\"י העבודה דשאו ידיכם באים לבחי' קדש העליון כן ע\"י היראה באים ג\"כ לבחי' קדש העליון בחי' קדש עילאה, וזהו בזאת",[["2438","1121","<b>אינה</b>: בהמשך הנדפס ובלקו\"ת: אינו."],["2439","1122","<b>אם חטאת מה תפעל</b>: איוב לה, ו [בדילוג]."],["2440","1123","<b>אם צדקת</b>: איוב לה, ז. בלקו\"ת ועד\"ז באוה\"ת (שה\"ש כרך ג' ע' תתצד) מובאים הפסוקים בשינוי. ובסה\"מ תרל\"ה ח\"א ריש ע' פו מובא כבפנים."],["2441","1124","<b>שמע ובשכמל\"ו. . יחו\"ע ויחו\"ת</b>: זהר בראשית יח, ב. ראה תו\"א ויקהל קטו, ב ואילך."],["2442","1125","<b>למס\"נ באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["2443","1126","<b>בע\"כ אתה חי</b>: ראה אבות ספ\"ד."],["2444","1127","<b>עוצם עיניו מראות ברע</b>: ישעי' לג, טו."],["2445","1128","<b>ובשמירתן</b>: בהמשך הנדפס ובלקו\"ת: ובשמירתו."],["2446","1129","<b>ולא תתורו אחרי לבבכם</b>: שלח טו, לט."],["2447","1130","<b>והנה. . דודי</b>: לשון מאמרי אדה\"ז תקס\"ד ע' נ (הועתק באוה\"ת שה\"ש ח\"ב כאן ע' תלו (בהוספות) — וראה שם ע' תנא) בהוספות ושינויים. ונו\"א במאמרי אדה\"ז על פרשיות התורה ח\"א ע נו."]]],[2000470302,"יבא אהרן אל הקדש ע\"י בחי' יראה שנק' בשם זאת יבא לבחי' ומדריגת קדש עילאה לפי שענין היראה היא בחי' הביטול והכנעת עצמותו בבחי' חותם שוקע שעי\"ז נמשך גילוי בחי' חותם בולט שמלמעלה היינו בחי' קדש בלא וא\"ו שלמעלה מעלה מבחי' קדוש בוא\"ו, וע' בזח\"ב תרומה קנ\"ח ב' הה\"ד וזאת<sup data-n=\"2448\">1131</sup> כו', וכתי' אל יתהלל כו' כ\"א בזאת<sup data-n=\"2449\">1132</sup>, בזאת אני בוטח<sup data-n=\"2450\">1133</sup>, וז\"ע וזאת הברכה<sup data-n=\"2451\">1134</sup>, אבל בבחי' האהבה שהוא בחי' יש מי שאוהב, שזהו עדיין בחי' יש, שיש מי שמתפעל<sup data-n=\"2452\">1135</sup> בבחי' האהבה, ואינו דומה לבחי' &lt;53&gt;\nּ היראה שהיא כוויצת וסילוק מהותו כו' שזהו בחי' ביטול גמור, לכן ע\"י האהבה א\"א לבא כ\"א לבחי' אוא\"ס מה שכבר נמשך הגילוי בנאצלים בלבד שז\"ע זה אלי ואנוהו כמשנ\"ל, לפי שבחי' אהבה היא בבחי' זה בחי' התגלות מציאות יש ודבר מה, ומזה יובן ענין מעלת מצה שנק' לחם עני בחי' הכנעה ויר\"ת שעי\"ז נמשך מה שנגלה עליהם ממה\"מ כמ\"ש בלק\"ת בד\"ה קול דודי<sup data-n=\"2453\">1136</sup>, ולכן לע\"ל בב\"א<sup data-n=\"2454\">1137</sup> נא' והריחו ביראת ה'<sup data-n=\"2455\">1138</sup> יראה דוקא, וז\"ע שם ירושלים יראה שלם כמ\"ש התוס'<sup data-n=\"2456\">1139</sup>, שלימות היראה<sup data-n=\"2457\">1140</sup> דוקא בחי' חותם שוקע, ועי\"ז יתגלה לע\"ל בחי' חותם בולט<sup data-n=\"2458\">*1141</sup> כמ\"ש חשף ה' את זרוע קדשו<sup data-n=\"2459\">1141</sup>, ואז יגיעו כולם לשלימות היראה כמ\"ש ובאו במערות צורים מפני פחד ה' והדר גאונו<sup data-n=\"2460\">1142</sup> שמחמת עוצם הגילוי יתגלה בכאו\"א בחי' יראת הרוממות כו'.\n<b></b>קיצור. שכשם שע\"י נשיאות ידים מגיעים לבחי' קדש כן ע\"י היראה באים לבחי' קדש כמ\"ש בזאת יבא אהרן אל הקדש, והיינו לפי שהיראה היא ביטול",[["2448","1131","<b>הה\"ד וזאת</b>: ויחי מט, כח."],["2449","1132","<b>אל יתהלל כו' כ\"א בזאת</b>: ירמי' ט, כב. כג."],["2450","1133","<b>בזאת אני בוטח</b>: תהלים כז, ג."],["2451","1134","<b>וזאת הברכה</b>: ברכה לג, א."],["2452","1135","<b>שיש מי שמתפעל</b>: ראה גם מאמרי אדה\"ז תקס\"ד ואוה\"ת כאן. שע\"ת לה, ד. לו, רע\"א. מאמרי אדה\"א קונטרסים ע' רנג. ע' שז. תו\"ח בשלח ח\"א קלח, סע\"ג. ויקהל ח\"ב תיג, ב. המשך תער\"ב ח\"א ע' קכו."],["2453","1136","<b>בלק\"ת בד\"ה קול דודי</b>: שה\"ש יד, ד ואילך."],["2454","1137","<b>בב\"א</b>: בהמשך הנדפס: בג\"א בגאולה אחרונה?."],["2455","1138","<b>והריחו ביראת ה'</b>: ישעי' יא, ג."],["2456","1139","<b>ירושלים יראה שלום כמ\"ש התוס'</b>: ראה תוד\"ה הר תענית טז, א[ednref_130_ב]. ב\"ר פנ\"ו, י. לקמן (בחלק ההנחות) בהנחה כאן ד\"ה ויאמר משה אל העם אל תיראו על יד הערה 85. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ושם העיר מיום ה' שמה על יד הערה 9. (בחלק ההנחות) ד\"ה שובה ישראל הא' על יד הערה 140. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רצה ובהנסמן במ\"מ לשם. סה\"מ תרכ\"ז ע' תיד. וש\"נ. תרל\"ח ע' תמא. וש\"נ."],["2457","1140","<b>ירושלים. . שלימות היראה</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 86. לקמן ח\"ב (בחלק המאמרים) בהמאמר שם בשם הלקו\"ת. וש\"נ. (בחלק ההנחות) הנחה ד\"ה שובה שם על יד הערה 141. סה\"מ תרכ\"ז ע' תיט. תרל\"ח ע' תסז."],["2458","*1141","<b>חותם שוקע. . חותם בולט</b>: ראה גם לקו\"ת שה\"ש מו, א."],["2459","1141","<b>חשף ה' את זרוע קדשו</b>: ישעי' נב, י."],["2460","1142","<b>ובאו במערות. . והדר גאונו</b>: ישעי' ב, יט [בדילוג. ושם: ומהדר — ראה גם בהנחה כאן על יד הערה 90. תו\"ח בשלח קנד, ד ובהערה 212].\n\n[edn_130_ב] הובא גם באוה\"ת חוקת ע' תתנו. המשך תער\"ב ח\"ג ע' א'תנה."]]],[2000470303,"גמור, וה\"ז כמו בחי' היחוד דיחו\"ע ויחו\"ת שאין עוד מלבדו שזהו כמו קדש מלה בגרמי', ולכן לע\"ל והריחו ביראת ה' וכן ירושלים שלימות היראה.\n<b>(ומעתה</b> יובן ענין אל תיראו ע\"פ פי' הרמב\"ן ז\"ל<sup data-n=\"2461\">1143</sup> שפי' שמה שחרדו, וינועו ויעמדו מרחוק זה הי' קודם אשר ירד ה' על ה\"ס, ומפני כי נהפכו ציריהם ממה שראו הקולות והברקים לכן שיערו שכשישמעו הקול ימותו (פי' שיכלה נפשם במס\"נ וא\"כ לא יקיימו עוד התומ\"צ בגשמיות) ולזה רצו לשמוע מפי משה כו', והשערתם הי' נכונה שהרי עכדו\"ד פרחה נשמתם, רק שהחזירם בטל תחי'<sup data-n=\"2462\">1144</sup>, ולכן לא אמר להם משה לא תמותון שגם הוא שיער שיהי' כן רק שהבין שמסתמא יחיים בטל תחי' דאל\"כ למי יצווה לקיים התומ\"צ, ולזה א\"ל אל תיראו מחשש פן תמותון, ומה שבא האלקים זהו בשביל שיהי' אצלם היראה לבלי תחטאו היינו בחי' יראת חטא, וגם י\"ל שא\"ל אל תיראו פי' שאין דרך היראה שעי\"ז תעמדו מרחוק כ\"א שתגישו בכדי שיהי' שלימות היראה כו').",[["2461","1143","<b>ע\"פ פי' הרמב\"ן ז\"ל</b>: יתרו כ, טו."],["2462","1144","<b>שהחזירם בטל תחי'</b>: שבת פח, ב."]]],[2000470304,"<h3>[כי טובים דודיך מיין] והנה בתושבע\"פ כו' ערבים עלי</h3>\n<b>פ' נשא</b>\n(לז) <b>והנה</b><sup data-n=\"2463\">1145</sup> גם<sup data-n=\"2464\">1146</sup> בתושבע\"פ שנק' אשה כנ\"ל אנו רואים ג\"כ שיש בה בינה יתירה יותר מבתושב\"כ, שלכן ארז\"ל עריבים עלי דברי דודיך יותר מיינה של תורה, בפ\"ב<sup data-n=\"2465\">1147</sup> דע\"ז דל\"ה א', ופרש\"י דודיך דברי סופרים, מיינה, עיקר תורה שבכתב, וכנודע שיין הוא בינה<sup data-n=\"2466\">1148</sup> כו', וכמ\"ש במ\"א בענין ד' כוסות שהם",[["2463","1145","<b>והנה</b>: מכאן מתחיל מאמר הי\"ב מהמשך מצה זו (הכולל פרקים לז-טל).\nפל\"ז — בתחלתו לשון מאמרי אדה\"ז תקס\"ד ע' נ — ונו\"א במאמרי אדה\"ז על פרשיות התורה ח\"א ריש ע' נו. לשון אוה\"ת שה\"ש ח\"ב כאן ע' תלז בהוספות ושינויים.\nפיסקא וביאור — לשון לקו\"ת שה\"ש ב, א ואילך בהוספות ושינויים (צויין אליו באוה\"ת כאן). ראה גם מאמרי אדה\"ז הנחות הר\"פ ע' קמג ואילך. אוה\"ת שה\"ש כרך א ע' כ.\nפל\"ח — לשון לקו\"ת סוכות עט, ד ואילך בהוספות ושינויים (צויין אליו בלקו\"ת שה\"ש שם). ראה גם סידור שער הסוכות רסח, א (הנחת כ\"ק אדמו\"ר האמצעי).\nפט\"ל — פיסקא אמנם — המשך לשון הלקו\"ת בהוספות ובשינויים.\nהסיום — לשון אוה\"ת שה\"ש כאן ע' תלז בהוספות ושינויים.\nהנחת* כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן (בחלק הנחותיו) ושם הפתיחא: כי טובים דודיך מיין."],["2464","1146","<b>גם</b>: בהמשך הנדפס ליתא. אבל במאמרי אדה\"ז תקס\"ד ובאוה\"ת כאן כבפנים."],["2465","1147","<b>בפ\"ב</b>: וכן צ\"ל בהמשך הנדפס. וכ\"ה לקמן שם רד\"ה המזבח עץ."],["2466","1148","<b>שיין הוא בינה</b>: ראה זהר נשא קכז, א. מאמרי אדה\"א ויקרא ח\"א ע' לג. וש\"נ. בראשית ע' תקעא."]]],[2000470305,"מבינה<sup data-n=\"2467\">1149</sup> ובענין יין המשמח אלקים<sup data-n=\"2468\">1150</sup> כו', וז\"ע יינה של תורה, וכאשר ד\"ס עריבים יותר מיינה ש\"ת א\"כ זהו בינה יתירה יותר כו'.\n<b>וביאור</b><sup data-n=\"2469\">1151</sup> הענין יובן ע\"פ מ\"ש החדלתי את תירושי<sup data-n=\"2470\">1152</sup> המשמח אלקים ואנשים, וארז\"ל אם &lt;54&gt;\nּ משמח אנשים<sup data-n=\"2471\">1153</sup>, אלקי' במה משמח, מכאן שאין אומרים שירה אלא על היין, והענין הוא כי היין בענבים מבלע בליעי<sup data-n=\"2472\">1154</sup>, וע\"י הדריכה יוצאים מהעלם אל הגילוי, ולכן פעולתו בעבודה שיוצא ע\"י מהעלם אל הגילוי, וזהו שאמרו נכנס יין יצא סוד<sup data-n=\"2473\">1155</sup> כו' וכתי' ויין ישמח לבב<sup data-n=\"2474\">1156</sup>, שכ\"ז הוא היציאה מהעלם אל הגילוי, וכל דבר שהוא בהעלם והסתר ביותר הנה הגילוי שאח\"כ הוא ביתר שאת ויתר עז<sup data-n=\"2475\">1157</sup>, ואין לך דבר בגילוי שלא הי' בהעלם תחלה וכמו הולד שהי' טמון בבטן האם כו', וע\"י הלידה יוצא לגילוי, וכל שהוא בעיבור יותר<sup data-n=\"2476\">1158</sup> יוצא בריא יותר, וכן בזריעת הגרעין שצ\"ל הגרעין מכוסה וטמון בעפר, וכאשר פועל בו העפר שנרקב אז יצמיח<sup data-n=\"2477\">1159</sup> ממנו אם תבואה או אילן ופירות כו', וכל מה שטמון ומתרקב יותר בארץ, צומחין וגדילין התבואה או הפירות ביותר בתוס' ברכה וריבוי ביותר, וכן גלות מצרים הי' בבחי' העלם ע\"ד שאה\"כ אותותינו לא ראינו כו' עי\"ז הי' אח\"כ מ\"ת גילוי פב\"פ<sup data-n=\"2478\">1160</sup>, רק שהגילוי שבמ\"ת הי' בחי' גליא שבתורה לכן הי' די רד\"ו שנה, ולצורך גילוי היותר נעלה מוכרח שיהי' ההעלם יותר, וע\"י זריעת מעהמ\"צ יומשך הצמיחה כמ\"ש זורע צדקות<sup data-n=\"2479\">1161</sup> מצמיח ישועות, שע\"י הצדקה להחיות רוח שפלים<sup data-n=\"2480\">1162</sup> בכסף וזהב הגשמיים מצמיח ישועות לשון ויושע<sup data-n=\"2481\">1163</sup> ה' בחי' וגילוי שע\"ה<sup data-n=\"2482\">1164</sup> נהורין<sup data-n=\"2483\">1165</sup> עילאין, וז\"ע יין המשמח אלקי', כי פי' שם אלקים הוא בחי'",[["2467","1149","<b>ד' כוסות שהם מבינה</b>: ראה פע\"ח שחה\"מ שכ\"א, פ\"ז. אוה\"ת בא כרך ז ע' ב'תרמג. וארא ע' קפח."],["2468","1150","<b>יין המשמח אלקים</b>: ע\"פ הערה 1152."],["2469","1151","<b>וביאור</b>: לשון לקו\"ת שה\"ש ב, א ואילך בהוספות ושינויים (צויין אליו באוה\"ת כאן). ראה גם מאמרי אדה\"ז הנחות הר\"פ ע' קמג ואילך. אוה\"ת שה\"ש כרך א ע' כ."],["2470","1152","<b>החדלתי את תירושי</b>: ס' שופטים ט, יג. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ושאבתם מים פ\"א."],["2471","1153","<b>אם משמח אנשים. . שירה אלא על היין</b>: ברכות לה, א."],["2472","1154","<b>היין בענבים מבלע בליעי</b>: ראה פסחים לג, ב. ראה גם סה\"מ תרכ\"ט ס\"ע שפג ואילך. וש\"נ."],["2473","1155","<b>נכנס יין יצא סוד</b>: ערובין סה, סע\"א. ראה גם תו\"ח ויחי רלו, ב."],["2474","1156","<b>ויין ישמח לבב</b>: תהלים קד, טו."],["2475","1157","<b>ביתר שאת ויתר עז</b>: ע\"פ ויחי מט, ג."],["2476","1158","<b>וכל שהוא בעיבור יותר</b>: ראה גם סידור שער הלולב רסג, ב. לקו\"ש לך ח\"ב ע' 458."],["2477","1159","<b>הגרעין. . שנרקב אז יצמיח</b>: ראה אגה\"ק ס\"ח (קיג, א). מאמרי אדה\"א ויקרא ח\"ב ע' תקצח. וש\"נ. תו\"ח שמות ח\"א ב, ב. וש\"נ. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי טובים דודיך מיין כאן על יד הערה 14. הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 118."],["2478","1160","<b>מ\"ת גילוי פב\"פ</b>: ואתחנן ה, ד."],["2479","1161","<b>זורע צדקות</b>: ברכת יוצר. ראה גם לקמן בהנחות שם."],["2480","1162","<b>להחיות רוח שפלים</b>: ישעי' נז, טו. ראה גם סה\"מ תרל\"ג ח\"ב ע' תסה ובהנסמן שם."],["2481","1163","<b>ויושע ה'</b>: בשלח יד ט. בהמשך הנדפס (ובמקומות שבהערה 1151): וישע ה' — בראשית ד, ד."],["2482","1164","<b>שע\"ה נהורין</b>: וכ\"ה במאמרי אדה\"ז ואוה\"ת (שבהערה 1151). ובלקו\"ת כאן: ש\"ע נהורין."],["2483","1165","<b>שע\"ה נהורין</b>: ראה גם לעיל המשך זאת חנוכת המזבח פ\"ז ובהערה 121."]]],[2000470306,"העלם והסתר כמ\"ש שמש ומגן ה' אלקי'<sup data-n=\"2484\">1166</sup> שבחי' השם אלקי' הוא בחי' מגן ונרתק להעלים ולהסתיר להיות נראה ליש ודבר וכשיוצא מהעלם אל הגילוי אז תהי' השמחה גדולה לאלקי' דוקא ששמחה הוא בחי' הגילוי, וכשמתגלה צמצום דש' אלקים<sup data-n=\"2485\">1167</sup> ה\"ה בחי' שמחת אלקים שמשמח את הצמצומי' דש' אלקי', וזהו נכנס יין יצא סוד הוא בחי' סוד הוי' ליריאיו<sup data-n=\"2486\">1168</sup> כו', הוא בחי' יין המשומר בענביו שהוא בבחי' העלם והסתר גדול מששת ימי בראשית<sup data-n=\"2487\">1169</sup> שהגילוי שיהי' לע\"ל יהי' בבחי' א\"ס עין לא ראתה<sup data-n=\"2488\">1170</sup> כו', וע' מענין יין המשומר בענביו משי\"ב בד\"ה ענין ברכת הזימון בסופו<sup data-n=\"2489\">1171</sup>, אך הנה כל זה הוא בחי' השתלשלו' שה\"ע העלם וגילוי בחי' יין כו', אך הנה כתי' כי טובים דודיך מיין<sup data-n=\"2490\">1172</sup> שפי' דודיך שהוא למעלה מבחי' השתלשלו' שזהו למעלה גם מבחי' העלם והיינו בחי' שלמעלה מסוכ\"ע וממכ\"ע, כי אין ערוך לך<sup data-n=\"2491\">1173</sup>, כי נפלאותיך ומחשבותיך זהו אלינו<sup data-n=\"2492\">1174</sup> אבל אין ערוך אליך כו', להיותך קדוש ומובדל בבחי' קדש מלה בגרמה כו' וכנ\"ל שפנימיות אבא חשוב כמו פנימיות ע\"י, וקמי' כחשיכה כאורה<sup data-n=\"2493\">1175</sup> שוין, והענין הוא דכמו שנמשך ההעלם לגילוי זהו נחשב כמו שיוצא מאפילה לאור גדול<sup data-n=\"2494\">1176</sup>, וכמ\"ש העם היושבים בחשך<sup data-n=\"2495\">1177</sup> ראו אור גדול, שמתחלה כשהי' האור בבחי' העלם החשך יכסה ארץ<sup data-n=\"2496\">1178</sup>, וע\"י הגילוי הנה ראו אור גדול ותהי' השמחה גדולה לאלקי' אבל קמי' עצמותו ית' הנה האור והגילוי זה שוה עם החשך שהי' תחלה, שהרי כל נהוראן מתחשכאן קמי'<sup data-n=\"2497\">1179</sup>, וכתר עליון אע\"ג דאיהו אור צח אור מצוחצח אוכם &lt;55&gt;\nּ הוא קדם כו', וזהו כי טובים דודיך מיין התגלות בחי' מהותו ועצמותו הנמשך ע\"י עבודת התומ\"צ דעכשיו שהוא בחי' התגלות שמו הגדול הוא טוב יותר מגילוי בחי' היין.",[["2484","1166","<b>שמש ומגן ה' אלקי'</b>: תהלים פד, יב. ראה שהיחוה\"א רפ\"ד. אוה\"ת (יהל אור) תהלים ס\"ע ש ואילך."],["2485","1167","<b>צמצום דש' אלקים</b>: ראה שער היחוה\"א רפ\"ו. תו\"ח שמות ח\"א לד, ד. וש\"נ."],["2486","1168","<b>סוד הוי' ליריאיו</b>: תהלים כה, יד."],["2487","1169","<b>יין המשומר בענביו. . מששת ימי בראשית</b>: ראה ברכות לד, ב. מאמרי אדה\"א דברים ח\"א ע' סז. וש\"נ. תו\"ח לך צא, ג הערה 32."],["2488","1170","<b>עין לא ראתה</b>: ישעי' סד, ג."],["2489","1171","<b>יין המשומר. . בד\"ה ענין ברכת הזימון בסופו</b>: ראה סידור שער בהמ\"ז קב, ג ואילך. קג, ד. קו, ב ואילך."],["2490","1172","<b>כי טובים דודיך מיין</b>: שה\"ש א, ב."],["2491","1173","<b>אין ערוך לך</b>: ברכת יוצר לשבת."],["2492","1174","<b>נפלאותיך ומחשבותיך. . אלינו</b>: תהלים מ, ו."],["2493","1175","<b>כחשיכה כאורה</b>: תהלים קלט, יב. ראה לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה וזהו שרש יונתי על יד הערה 69 ד\"ה והנה כובע על יד הערה 24[ednref_131_א] שמציין: בלקו\"ת בד\"ה מצה זו — לקו\"ת צו יב, א. סידור סדר הגדה רצז, רע\"ד. עט\"ר דרוש לעשי\"ת ע' נא. סה\"מ תרכ\"ז ע' תצד. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 30."],["2494","1176","<b>מאפילה לאור גדול</b>: פסחים קטז, ב (במשנה). הגדה פיסקא לפיכך."],["2495","1177","<b>העם היושבים בחשך</b>: ישעי' ט, א [ושם: ההולכים[ednref_132_ב]]. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 150."],["2496","1178","<b>החשך יכסה ארץ</b>: ישעי' ס, ב."],["2497","1179","<b>כל נהוראן מתחשכאן קמי'</b>: ראה זהר בראשית כג, א.\n\n[edn_131_א] ראה גם לקמן ח\"ב שם מאמר ד\"ה ויובן כו' הני ששה ועשרים הודו על יד הערה 133.\n\n[edn_132_ב] אבל כ\"ה גם לקמן ספס\"ד. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 30."]]],[2000470307,"<b></b>קיצור. עריבים עלי דברי דודי' כו', כי יינה ש\"ת, הנה היין משמח אלקים כמו שהיין הוא אגור בענביו ויצא מהעלם אל הגילוי כן פעולתו לגלות צמצום דש' אלקי' וזהו השמחה לאלקי', אבל טובים דודיך שעי\"ז נמשך מבחי' מלה בגרמי', ומבחי' אשר כל נהוראין מתחשכאין קמי', בחי' שמו הגדול.\n(לח) <b>ויובן</b><sup data-n=\"2498\">1180</sup> בתוס' ביאור דהנה היין שרשו מבחי' הבינה וכתי' אם הבנים שמחה<sup data-n=\"2499\">1181</sup>, שענין השמחה הוא בחי' גילוי ההעלם לכן נמשך בחי' זו מהבינה דוקא שענין בחי' הבינה הוא כשמבין ומשיג בטוב טעם תעלומות בחי' החכ'<sup data-n=\"2500\">1182</sup>, שכשנמשכה בבחי' גילוי ההשגה והבנה להשיגה על בוריו אז יהי' השמחה כו', משא\"כ כשעדיין אינו משיג הדבר בהשגה היטב, רק שעדיין השכל נעלם בכח חכמתו ואינו בבחי' הגילוי אצלו שישיגנה על בורי' לא יקבל ענג ושמחה כלל, כ\"א טרוד הוא להוציאה מהעלם אל הגילוי ומייגע שכלו וכח בינתו להבינה בטוב שאז אינו נופל להיות בחי' שמחה עדיין מאחר שאין לו ממה עדיין, כ\"א שיכול להיות אצלו הזזה והתפעלות מבחי' ברק המבריק שהבריק בכח חכמתו שיש לומר בכאן סברא זו, ושזהו טעם דבר ההלכה אבל עדיין נעלמת ממנו, ומפני שעכ\"ז ה\"ז פתיחת הגילוי שהרי מקודם הי' נסתם ממנו לגמרי וכענין אשתומם כשעה חדא<sup data-n=\"2501\">1183</sup> שהוא העלאת כלי שכלו לבחי' משכיל כמ\"ש במ\"א, לכן כאשר נפתח אצלו מקור על בחי' הגילוי ה\"ז ניזז ממקומו ומתפעל, אבל א\"א לכנות זאת בשם שמחה שהרי ממה ישמח שהרי אינו יודע עדיין כלל כו', רק כשבא ההשכלה בהשגה גמורה בבינה להבין עומקה של הלכה וטעמה או את ההשכלה החדשה כשהשכיל אז מתמלא שמחה, ונמצא כי השמחה היא בבינה וזהו אם הבנים שמחה שמבחי' אם הבנים היינו בינה מקור הבנים ז\"א, משם נמשך השמחה כו', אך הנה נודע כי הבינה הוא בחי'<sup data-n=\"2502\">1184</sup> עלמא דאתכסי' כמ\"ש בזהר בכ\"ד וע' זח\"א ויצא קנ\"ג ב' ודף קנ\"ד<sup data-n=\"2503\">1185</sup>, לכן זה הי' עבודת הלוים דכתי' בהם ועבד הלוי הוא<sup data-n=\"2504\">1186</sup> שעבודת הלוים הוא להמשיך מבחי' הוא, דהיינו בחי' עדאת\"כ כי הוא פי' על דבר הנעלם והיינו בינה<sup data-n=\"2505\">1187</sup> עדאת\"כ, ובזהר פי' הוא דא עתיקא<sup data-n=\"2506\">1188</sup> היינו בחי' התגלות עתיק שבבינה, ועבודתם הוא להמשיך",[["2498","1180","<b>ויובן</b>: פרק זה לשון לקו\"ת סוכות עט, ד ואילך בהוספות ושינויים (צויין אליו בלקו\"ת שה\"ש שם). ראה גם סידור שער הסוכות רסח, א (הנחת כ\"ק אדמו\"ר האמצעי). פרק זה נזכר בלקו\"ש לך כרך כ ע' 42 הערה 32."],["2499","1181","<b>אם הבנים שמחה</b>: תהלים קיג, ט. ראה לעיל המשך זאת חנוכת המזבח הערה 208. וראה גם בהבא בסמוך לקו\"ת צו יא, ד ואילך."],["2500","1182","<b>תעלומות. . החכ'</b>: איוב יא, ו. ראה גם תו\"ח שמות ח\"א לג, א. וש\"נ."],["2501","1183","<b>אשתומם כשעה חדא</b>: דניאל ד, טז. שבת מז, א. ראה סידור שער נפ\"א צב, ג. תו\"ח פקודי ח\"ב תנ, ד. וש\"נ."],["2502","1184","<b>הוא בחי'</b>: בהמשך הנדפס: היא בחי' הוא בחי'."],["2503","1185","<b>זח\"א ויצא קנ\"ג ב' ודף קנ\"ד</b>: ע\"א. כ\"ה גם בלקו\"ת כאן. ובלקו\"ת שמע\"צ פח, ד מציין: ”בזח\"א (ויצא דקנ\"ח ע\"ב) ושאר דוכתי\"."],["2504","1186","<b>ועבד הלוי הוא</b>: קרח יח, כג."],["2505","1187","<b>הוא. . בינה</b>: ראה ביאוה\"ז בלק — להצ\"צ כרך א — ע' תקכ ואילך. וש\"נ. לקו\"ת קרח נה, ב. תו\"ח לך פא, ב ובהערה 7. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ושאבתם מים פ\"ג. ו(בחלק ההנחות) בהנחה שם על יד הערה 92."],["2506","1188","<b>הוא דא עתיקא</b>: ראה זהר קרח קעח, ב. תו\"ח שמות ח\"א לד, א הערה 345."]]],[2000470308,"מהעלם דעדאתכ\"ס לבחי' הגילוי, וזהו ע\"י השיר שהיו אומרים על היין שהוא בחי' בינה, ושהי' כנוס עצור ואגור בענבי' תחלה ויצא מהעלם אל הגילוי לכן פעולתו שע\"י שיר הלוים על היין יצא העלם בחי' עדאת\"כ אל בחי' הגילוי, וזהו יין המשמח אלקים ואנשים שמביא בחי' האלקות לידי גילוי לאנשים, והיינו &lt;56&gt;\nּ ע\"י הבינה שמבין ומשיג גדולת ה' שעי\"ז תתלהב נפשו בה' אחד, וכמו יין הגשמי שמביא וגורם השמחה וגילוי ההעלם, וכאמרם ז\"ל נכנס יין יצא סוד שמה שהי' אצלו בסוד כמוס ונעלם יוצא ע\"י היין לגילוי כו', ונמצא כי עבודת הלוים בשוררם שירה על היין ה\"ז כדוגמת המועדים שכמו המועדים<sup data-n=\"2507\">1189</sup> הם גילוי השמחה כמ\"ש מועדים לשמחה<sup data-n=\"2508\">1190</sup> כן ע\"י שיר הלוים שמשוררים על היין נמשך ג\"כ השמחה, ועכ\"ז יש הפרש ביניהם, והוא עד\"מ אדם שמתפעל ושמח מאיזהו דבר אעפ\"כ יכול להיות השמחה וההתפעלות אצלו בהעלם מזולתו, והיינו שיהי' תוכו רצוף חדוה ושמחה ואינו גילוי לעין כל, אבל כשנתפעל ונשמח מאד מאיזהו דבר אזי בולט ויוצא לחוץ עד שנראה שמחתו לעין כל ומרנן ומרקד ברגל ומטפח בידיו כמו בשמחת נשואין, או מחדות<sup data-n=\"2509\">1191</sup> ושמחת יו\"ט שלכן אומרים והשיאנו ביו\"ט<sup data-n=\"2510\">1192</sup> שלהיות גילוי השמחה אז בתוקף מאד נעלה אינה יכולה להיות בהסתר כלל מרוב גדולת השמחה, ועד\"ז יובן בשיר הלוים ג\"כ שעם היות שע\"י שמשוררים על היין נמשך גילוי השמחה שמתפעל מבחי' גילוי גדולת א\"ס ב\"ה עכ\"ז ה\"ה מתיישב בכלי שזה נחשב לקצת העלם להיות כי אור השמחה מתלבש בכלי, והכלי מגבילתו, אבל במועדים השמחה בוקע הכלי והאור יוצא לחוץ שמחמת ריבוי ותוקף האור הנה האור בוקע את הכלי כו' ויוצא לחוץ להיות נראה לכל מחמת רוב גדולת השמחה וריבוי גילוי ההעלם וע' בלק\"ת בד\"ה ה' לי בעוזרי<sup data-n=\"2511\">1193</sup>, וכמו שא\"י היא ארץ זבת חלב ודבש<sup data-n=\"2512\">1194</sup> שמחמת תוס' האור אין הכלים מגבילי'<sup data-n=\"2513\">1195</sup> השפע לכן זבת חלב ודבש כו'.\n<b>וכמו</b> שענין השמחה בגשמיות הוא שמרנן ומרקד ברגליו שהוא ברעש כו' כן ויותר מכן הוא הרינון והריקוד ברוחניות בשירות ותשבחות לפני ה' ע\"ד מש\"א והאופנים וחיוה\"ק ברעש גדול<sup data-n=\"2514\">1196</sup>, רק שבאופנים נת' במ\"א שזהו מפני העדר השגתם<sup data-n=\"2515\">1197</sup>, וכאן זהו מפני גילוי ההשגה כנ\"ל.\n<b></b>קיצור. בינה אם הבנים שמחה, שעיקר השמחה כשמבין בטוב ההשכלה אבל כשעדיין בבחי' ברק המבריק לא שייך שמחה, וזהו שיר הלוים ועבד הלוי",[["2507","1189","<b>שכמו המועדים</b>: בהמשך הנדפס ליתא."],["2508","1190","<b>מועדים לשמחה</b>: נוסח תפלת העמידה וקידוש ליו\"ט."],["2509","1191","<b>או מחדות</b>: בהמשך הנדפס ליתא."],["2510","1192","<b>שלכן אומרים והשיאנו ביו\"ט</b>: בתפלת העמידה."],["2511","1193","<b>בלק\"ת בד\"ה ה' לי בעוזרי</b>: שמע\"צ פח, ד."],["2512","1194","<b>ארץ זבת חלב ודבש</b>: שמות ג, ח. ראה לקו\"ת שלח לו, ג ואילך. לח, ב ואילך."],["2513","1195","<b>מגבילי'</b>: בהמשך הנדפס: מקבלים."],["2514","1196","<b>והאופנים וחיוה\"ק ברעש גדול</b>: ברכת יוצר."],["2515","1197","<b>שבאופנים. . העדר השגתם</b>: ראה לעיל המשך זאת חנוכת המזבח פ\"ג ופ\"ד ובהנסמן שם."]]]]});
